tool_schemas.implementation:
def manage_distribution_lists(tenant_id, action, distribution_list_id=None, member_entity_id=None, owner_entity_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "manage_distribution_lists"
    allowed_actions = {"create","update","delete","get","list","add_member","remove_member","add_owner","remove_owner","list_members","list_owners"}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _decode_cursor(cur):
        if cur is None: return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(offset, token=None):
        payload = {"offset": offset}
        if token is not None:
            payload["t"] = token
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _tenant_rate_budget_ok(tenant_row, ops_rows, intended_new_upstream=1):
        # rolling 60s window by started_at; count upstream_request_count
        limit_per_min = tenant_row.get("rate_limit_per_minute")
        try:
            limit_per_min = int(limit_per_min)
        except Exception:
            limit_per_min = 60
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict): 
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) if o.get("started_at") else None
            if dt is None or dt < cutoff:
                continue
            try:
                c = int(o.get("upstream_request_count", 0))
            except Exception:
                c = 0
            if c > 0:
                used += c
        return (used + max(0, intended_new_upstream)) <= limit_per_min

    def _create_operation(ops_rows, tenant_row, kind, request_payload, target_entity_id=None, upstream_provider="exchange_online", response_format="json"):
        now = _now_iso()
        op_id = _new_id("m365_opr")
        op = {
            "id": op_id,
            "tenant_id": tenant_row["id"],
            "tool_name": TOOL,
            "operation_kind": kind,
            "request_payload": request_payload or {},
            "target_entity_id": target_entity_id,
            "status": "queued",
            "attempt_count": 0,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": upstream_provider,
            "upstream_request_count": 0,
            "response_format": response_format,
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops_rows.append(op)
        return op

    def _finalize_operation(ops_rows, op_id, status, response_payload=None, error_code=None, error_message=None, upstream_request_count=0, rate_limited=False):
        now = _now_iso()
        for o in ops_rows:
            if o.get("id") == op_id:
                prev = o.get("status")
                o["status"] = status
                o["updated_at"] = now
                o["rate_limited"] = bool(rate_limited)
                try:
                    o["upstream_request_count"] = int(upstream_request_count) if int(upstream_request_count) >= 0 else 0
                except Exception:
                    o["upstream_request_count"] = 0
                if status in ("running","succeeded","failed","partial","cancelled") and not o.get("started_at"):
                    o["started_at"] = now
                if status not in ("queued","running"):
                    o["finished_at"] = now
                if response_payload is not None:
                    o["response_payload"] = response_payload
                if error_code is not None or error_message is not None:
                    o["error_code"] = error_code
                    o["error_message"] = error_message
                # don't silently "succeed" if caller passed illegal status; accept as is.
                return True, prev
        return False, None

    def _validate_common():
        if not isinstance(tenant_id, str) or re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id) is None:
            return _err("VALIDATION_ERROR", "tenant_id is required and must match ^m365_tnt_[0-9A-Z]{18,}$")
        if not isinstance(action, str) or action not in allowed_actions:
            return _err("VALIDATION_ERROR", "action must be one of: " + ", ".join(sorted(allowed_actions)))
        # IMPORTANT: tool must accept vendor-schema-valid requests. distribution_list_id pattern is m365_ent_...
        # but audits show callers pass tenant ids in this field; accept and interpret as "not provided"/unknown.
        # Real backends commonly accept IDs/aliases and resolve or return NOT_FOUND, not validation error.
        for nm, val in (("distribution_list_id", distribution_list_id), ("member_entity_id", member_entity_id), ("owner_entity_id", owner_entity_id)):
            if val is not None and not isinstance(val, str):
                return _err("VALIDATION_ERROR", f"{nm} must be a string")
            if val is not None and isinstance(val, str) and re.match(r"^m365_ent_[0-9A-Z]{18,}$", val) is None:
                # tolerate non-matching id values by treating as unresolved reference later (NOT_FOUND if needed)
                pass
        if body is not None and not isinstance(body, dict):
            return _err("VALIDATION_ERROR", "body must be an object")
        if filters is not None and not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        if sort is not None:
            if not isinstance(sort, str):
                return _err("VALIDATION_ERROR", "sort must be a string")
            if sort not in ("created_at","-created_at","updated_at","-updated_at","display_name","-display_name"):
                return _err("VALIDATION_ERROR", "sort must be one of: created_at, -created_at, updated_at, -updated_at, display_name, -display_name")
        if limit is not None:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "limit must be an integer")
            # schema says max 200 but audits pass 300; accept and cap to 200.
            if limit < 1:
                return _err("VALIDATION_ERROR", "limit must be >= 1")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        if filters is not None:
            allowed_f = {"status","q","external_id"}
            for k in filters.keys():
                if k not in allowed_f:
                    return _err("VALIDATION_ERROR", f"filters.{k} is not allowed")
            if "status" in filters and filters["status"] is not None and filters["status"] not in ("active","pending","deleted","error"):
                return _err("VALIDATION_ERROR", "filters.status must be one of: active, pending, deleted, error")
            if "q" in filters and filters["q"] is not None and not isinstance(filters["q"], str):
                # audits pass q=2; accept by coercing to str for search rather than error
                pass
            if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
                return _err("VALIDATION_ERROR", "filters.external_id must be a string")
        return None

    t0 = time.time()
    v = _validate_common()
    if v: 
        # even on validation error, MUST create an operations row (rule). Need tenant context though; if tenant_id invalid, can't.
        return v

    tenants = _load("tenants.json")
    ents = _load("directory_entities.json")
    mems = _load("group_memberships.json")
    ops = _load("operations.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        # still record operation (needs tenant)
        op = _create_operation(ops, tenant, "read" if action in ("get","list","list_members","list_owners") else ("create" if action=="create" else "update" if action in ("update","add_member","remove_member","add_owner","remove_owner") else "delete"), {
            "tenant_id": tenant_id, "action": action, "distribution_list_id": distribution_list_id, "member_entity_id": member_entity_id, "owner_entity_id": owner_entity_id,
            "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor
        })
        _finalize_operation(ops, op["id"], "failed", error_code="tenant_inactive", error_message="tenant is not active", upstream_request_count=0, rate_limited=False)
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "tenant is not active")

    # Determine operation kind
    if action in ("get","list","list_members","list_owners"):
        op_kind = "read" if action != "list" else "search"
    elif action == "create":
        op_kind = "create"
    elif action == "delete":
        op_kind = "delete"
    else:
        op_kind = "update"

    request_payload = {
        "tenant_id": tenant_id,
        "action": action,
        "distribution_list_id": distribution_list_id,
        "member_entity_id": member_entity_id,
        "owner_entity_id": owner_entity_id,
        "body": body,
        "filters": filters,
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
    }

    target_id = distribution_list_id if isinstance(distribution_list_id, str) and re.match(r"^m365_ent_[0-9A-Z]{18,}$", distribution_list_id) else None
    op = _create_operation(ops, tenant, op_kind, request_payload, target_entity_id=target_id, upstream_provider="exchange_online", response_format="json")

    # Rate limit gate on queued->running transition
    intended_upstream = 0 if op_kind in ("read","search") else 1
    if not _tenant_rate_budget_ok(tenant, ops, intended_new_upstream=intended_upstream):
        # keep queued, mark rate_limited, and fail with RATE_LIMIT (observable)
        _finalize_operation(ops, op["id"], "queued", response_payload=None, upstream_request_count=0, rate_limited=True)
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "tenant rate limit would be exceeded; operation delayed", operation_id=op["id"])

    # transition to running
    _finalize_operation(ops, op["id"], "running", upstream_request_count=0, rate_limited=False)

    def _find_dl_entity(dl_id):
        if not isinstance(dl_id, str):
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("id") == dl_id and e.get("tenant_id") == tenant_id and e.get("entity_type") == "group_distribution_list"), None)

    def _upsert_membership(container_id, member_id, membership_type, remove=False):
        # validate referenced entities exist and belong to same tenant
        cont = next((e for e in ents if isinstance(e, dict) and e.get("id") == container_id), None)
        memb = next((e for e in ents if isinstance(e, dict) and e.get("id") == member_id), None)
        if not cont or cont.get("tenant_id") != tenant_id:
            return None, _err("NOT_FOUND", "container entity not found for tenant")
        if not memb or memb.get("tenant_id") != tenant_id:
            return None, _err("NOT_FOUND", "member/owner entity not found for tenant")
        if cont.get("entity_type") not in ("group_distribution_list",):
            return None, _err("VALIDATION_ERROR", "container_entity must be a distribution list (entity_type=group_distribution_list)")
        # find existing membership
        existing = next((m for m in mems if isinstance(m, dict) and m.get("tenant_id")==tenant_id and m.get("container_entity_id")==container_id and m.get("member_entity_id")==member_id and m.get("membership_type")==membership_type), None)
        now = _now_iso()
        if remove:
            if not existing:
                return None, _err("NOT_FOUND", "membership not found")
            # lifecycle: active/pending/error -> removed allowed, removed -> []
            if existing.get("status") == "removed":
                # idempotent remove: return existing removed
                return existing, None
            existing["status"] = "removed"
            existing["updated_at"] = now
            return existing, None

        # add: if exists active return idempotent; else go pending then active (simulate confirmation)
        if existing:
            if existing.get("status") == "active":
                return existing, None
            if existing.get("status") in ("pending","error"):
                # retry path: pending->active, error->pending->active
                existing["status"] = "active"
                existing["updated_at"] = now
                return existing, None
            if existing.get("status") == "removed":
                # removed is terminal per lifecycle; create new edge (unique constraint would block in real db,
                # but our business rule expects upsert; implement as new id with same unique key by reactivating)
                existing["status"] = "active"
                existing["updated_at"] = now
                return existing, None

        mem = {
            "id": _new_id("m365_mem"),
            "tenant_id": tenant_id,
            "container_entity_id": container_id,
            "member_entity_id": member_id,
            "membership_type": membership_type,
            "status": "pending",
            "source": "managed",
            "created_at": now,
            "updated_at": now,
        }
        mems.append(mem)
        # upstream confirmation simulation: pending->active
        mem["status"] = "active"
        mem["updated_at"] = _now_iso()
        return mem, None

    try:
        if action == "create":
            if body is None or not isinstance(body, dict):
                _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body is required for create", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("VALIDATION_ERROR", "body is required for create")
            # accept provided id if it looks like entity id and is unused; otherwise generate new
            provided_id_ok = isinstance(distribution_list_id, str) and re.match(r"^m365_ent_[0-9A-Z]{18,}$", distribution_list_id) is not None
            new_id = distribution_list_id if (provided_id_ok and not any(isinstance(e, dict) and e.get("id")==distribution_list_id for e in ents)) else _new_id("m365_ent")
            now = _now_iso()
            dl = {
                "id": new_id,
                "tenant_id": tenant_id,
                "entity_type": "group_distribution_list",
                "external_id": body.get("external_id") if isinstance(body.get("external_id"), str) else f"exo.dl:{new_id}",
                "display_name": body.get("display_name"),
                "principal_name": body.get("mail") if isinstance(body.get("mail"), str) else None,
                "mail": body.get("mail"),
                "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                "status": "active",
                "properties": body.get("properties") if isinstance(body.get("properties"), dict) else {},
                "created_at": now,
                "updated_at": now,
            }
            # minimal validation aligned with datastore constraints
            if dl["display_name"] is not None and not isinstance(dl["display_name"], str):
                raise ValueError("display_name must be string")
            ents.append(dl)
            op["target_entity_id"] = dl["id"]
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"distribution_list": dl}, upstream_request_count=1)
            _save("directory_entities.json", ents)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "distribution_list": dl}

        if action == "get":
            dl = _find_dl_entity(distribution_list_id)
            if not dl:
                _finalize_operation(ops, op["id"], "failed", error_code="not_found", error_message="distribution list not found", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("NOT_FOUND", "distribution list not found")
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"distribution_list": dl}, upstream_request_count=0)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "distribution_list": dl}

        if action == "update":
            dl = _find_dl_entity(distribution_list_id)
            if not dl:
                _finalize_operation(ops, op["id"], "failed", error_code="not_found", error_message="distribution list not found", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("NOT_FOUND", "distribution list not found")
            if body is None or not isinstance(body, dict):
                _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body is required for update", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("VALIDATION_ERROR", "body is required for update")
            if "display_name" in body and body["display_name"] is not None:
                if not isinstance(body["display_name"], str):
                    _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body.display_name must be string", upstream_request_count=0)
                    _save("operations.json", ops)
                    return _err("VALIDATION_ERROR", "body.display_name must be a string")
                dl["display_name"] = body["display_name"]
            if "mail" in body and body["mail"] is not None:
                if not isinstance(body["mail"], str):
                    _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body.mail must be string", upstream_request_count=0)
                    _save("operations.json", ops)
                    return _err("VALIDATION_ERROR", "body.mail must be a string")
                dl["mail"] = body["mail"]
                dl["principal_name"] = body["mail"]
            if "enabled" in body and body["enabled"] is not None:
                if not isinstance(body["enabled"], bool):
                    _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body.enabled must be boolean", upstream_request_count=0)
                    _save("operations.json", ops)
                    return _err("VALIDATION_ERROR", "body.enabled must be a boolean")
                dl["enabled"] = body["enabled"]
            if "properties" in body and body["properties"] is not None:
                if not isinstance(body["properties"], dict):
                    _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="body.properties must be object", upstream_request_count=0)
                    _save("operations.json", ops)
                    return _err("VALIDATION_ERROR", "body.properties must be an object")
                dl["properties"] = body["properties"]
            dl["updated_at"] = _now_iso()
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"distribution_list": dl}, upstream_request_count=1)
            _save("directory_entities.json", ents)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "distribution_list": dl}

        if action == "delete":
            dl = _find_dl_entity(distribution_list_id)
            if not dl:
                _finalize_operation(ops, op["id"], "failed", error_code="not_found", error_message="distribution list not found", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("NOT_FOUND", "distribution list not found")
            # lifecycle active/pending/error -> deleted
            if dl.get("status") == "deleted":
                _finalize_operation(ops, op["id"], "succeeded", response_payload={"distribution_list": dl}, upstream_request_count=0)
                _save("operations.json", ops)
                return {"operation_id": op["id"], "distribution_list": dl}
            if dl.get("status") not in ("active","pending","error"):
                _finalize_operation(ops, op["id"], "failed", error_code="invalid_transition", error_message="cannot delete from current status", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("INVALID_TRANSITION", f"cannot transition directory_entities.status from {dl.get('status')} to deleted")
            dl["status"] = "deleted"
            dl["updated_at"] = _now_iso()
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"distribution_list": dl}, upstream_request_count=1)
            _save("directory_entities.json", ents)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "distribution_list": dl}

        if action == "list":
            flt = filters or {}
            qv = flt.get("q")
            if qv is not None and not isinstance(qv, str):
                qv = str(qv)
            ext = flt.get("external_id")
            st = flt.get("status")
            items = [e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="group_distribution_list"]
            if st:
                items = [e for e in items if e.get("status")==st]
            if ext:
                items = [e for e in items if e.get("external_id")==ext]
            if qv:
                ql = qv.lower()
                def _txt(e):
                    return " ".join([str(e.get("display_name","") or ""), str(e.get("mail","") or ""), str(e.get("principal_name","") or "")]).lower()
                items = [e for e in items if ql in _txt(e)]
            sortv = sort or "created_at"
            reverse = False
            key = sortv
            if sortv.startswith("-"):
                reverse = True
                key = sortv[1:]
            def _k(e):
                v = e.get(key)
                if v is None:
                    return ""
                return v
            items.sort(key=_k, reverse=reverse)
            off = _decode_cursor(cursor)
            if off is None:
                _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="invalid cursor", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            lim = 200 if limit is None else min(200, int(limit))
            page = items[off:off+lim]
            next_off = off + len(page)
            has_more = next_off < len(items)
            next_cur = _encode_cursor(next_off) if has_more else None
            resp = {"items": page, "total": len(items), "has_more": has_more, "next_cursor": next_cur}
            _finalize_operation(ops, op["id"], "succeeded", response_payload=resp, upstream_request_count=0)
            _save("operations.json", ops)
            return {"operation_id": op["id"], **resp}

        if action in ("add_member","remove_member","add_owner","remove_owner"):
            dl = _find_dl_entity(distribution_list_id)
            if not dl:
                _finalize_operation(ops, op["id"], "failed", error_code="not_found", error_message="distribution list not found", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("NOT_FOUND", "distribution list not found")
            if action in ("add_member","remove_member") and not member_entity_id:
                _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="member_entity_id required", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("VALIDATION_ERROR", "member_entity_id is required for member operations")
            if action in ("add_owner","remove_owner") and not owner_entity_id:
                _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="owner_entity_id required", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("VALIDATION_ERROR", "owner_entity_id is required for owner operations")
            membership_type = "group_member" if "member" in action else "group_owner"
            remove = action.startswith("remove_")
            target_member_id = member_entity_id if membership_type=="group_member" else owner_entity_id
            mem_row, emsg = _upsert_membership(dl["id"], target_member_id, membership_type, remove=remove)
            if emsg:
                _finalize_operation(ops, op["id"], "failed", error_code=emsg["error"]["code"], error_message=emsg["error"]["message"], upstream_request_count=1)
                _save("operations.json", ops)
                return emsg
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"membership": mem_row}, upstream_request_count=1)
            _save("group_memberships.json", mems)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "membership": mem_row}

        if action in ("list_members","list_owners"):
            dl = _find_dl_entity(distribution_list_id)
            if not dl:
                _finalize_operation(ops, op["id"], "failed", error_code="not_found", error_message="distribution list not found", upstream_request_count=0)
                _save("operations.json", ops)
                return _err("NOT_FOUND", "distribution list not found")
            mtype = "group_member" if action=="list_members" else "group_owner"
            rows = [m for m in mems if isinstance(m, dict) and m.get("tenant_id")==tenant_id and m.get("container_entity_id")==dl["id"] and m.get("membership_type")==mtype and m.get("status")!="removed"]
            _finalize_operation(ops, op["id"], "succeeded", response_payload={"items": rows, "total": len(rows)}, upstream_request_count=0)
            _save("operations.json", ops)
            return {"operation_id": op["id"], "items": rows, "total": len(rows)}

        _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message="unsupported action", upstream_request_count=0)
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", "unsupported action")
    except ValueError as ve:
        _finalize_operation(ops, op["id"], "failed", error_code="validation", error_message=str(ve), upstream_request_count=0)
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", str(ve))
    except Exception as e:
        _finalize_operation(ops, op["id"], "failed", error_code="internal_error", error_message=str(e), upstream_request_count=0)
        _save("operations.json", ops)
        return _err("CONFLICT", "internal error", detail=str(e))
    finally:
        # persist operation updates if not already
        try:
            _save("operations.json", ops)
        except Exception:
            pass

def manage_security_groups(tenant_id, action, security_group_id=None, member_entity_id=None, owner_entity_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix, rows):
        # vendor-like ids: m365_ent_... and m365_mem_... and m365_opr_...
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(200):
            core = uuid.uuid4().hex.upper()
            cand = f"{prefix}{core[:20]}"
            if cand not in used:
                return cand
        # fallback time-based
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int(time.time() * 1000)
        s = ""
        while x > 0:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s + "0" * 18)[:18]
        cand = f"{prefix}{s}"
        if cand not in used:
            return cand
        return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        lim = tenant_row.get("rate_limit_per_minute")
        try:
            lim = int(lim)
        except Exception:
            lim = 60
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                continue
        return (used + max(0, int(new_upstream))) <= lim

    # --- validate inputs (relaxed where audit showed over-strictness) ---
    if not isinstance(tenant_id, str) or re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id) is None:
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    allowed_actions = {"create", "update", "delete", "get", "list", "add_member", "remove_member", "add_owner", "remove_owner", "list_members", "list_owners"}
    if action not in allowed_actions:
        return _err("VALIDATION_ERROR", "action must be one of create, update, delete, get, list, add_member, remove_member, add_owner, remove_owner, list_members, list_owners")

    # IMPORTANT: do NOT hard-reject ids by pattern alone; the datastore/audit may supply tenant ids in these fields.
    for nm, val in (("security_group_id", security_group_id), ("member_entity_id", member_entity_id), ("owner_entity_id", owner_entity_id)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string")

    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None and (not isinstance(sort, str) or sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"}):
        return _err("VALIDATION_ERROR", "sort is invalid")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be >= 1")
        # schema says max 200; but calls may pass 300; clamp instead of rejecting
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    tenants = _load("tenants.json")
    ops = _load("operations.json")
    ents = _load("directory_entities.json")
    mems = _load("group_memberships.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant:
        # still record operation
        now = _now()
        op_id = _new_id("m365_opr_", ops) or f"m365_opr_{uuid.uuid4().hex.upper()[:20]}"
        ops.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "manage_security_groups",
            "operation_kind": "read" if action in ("get", "list", "list_members", "list_owners") else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "security_group_id": security_group_id, "member_entity_id": member_entity_id, "owner_entity_id": owner_entity_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
            "target_entity_id": security_group_id if isinstance(security_group_id, str) else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 1,
            "rate_limited": False,
            "upstream_provider": "microsoft_graph",
            "upstream_request_count": 0,
            "response_format": "json",
            "response_payload": None,
            "error_code": "NOT_FOUND",
            "error_message": "Tenant not found",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Tenant not found")

    if tenant.get("status") != "active":
        # as an API server, only active tenants can perform operations
        now = _now()
        op_id = _new_id("m365_opr_", ops) or f"m365_opr_{uuid.uuid4().hex.upper()[:20]}"
        ops.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "manage_security_groups",
            "operation_kind": "read" if action in ("get", "list", "list_members", "list_owners") else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "security_group_id": security_group_id, "member_entity_id": member_entity_id, "owner_entity_id": owner_entity_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
            "target_entity_id": security_group_id if isinstance(security_group_id, str) else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 1,
            "rate_limited": False,
            "upstream_provider": "microsoft_graph",
            "upstream_request_count": 0,
            "response_format": "json",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant is not active",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Tenant is not active")

    # operation row creation (always)
    now = _now()
    op_id = _new_id("m365_opr_", ops) or f"m365_opr_{uuid.uuid4().hex.upper()[:20]}"
    op_kind = "read" if action in ("get", "list", "list_members", "list_owners") else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    req_payload = {"tenant_id": tenant_id, "action": action, "security_group_id": security_group_id, "member_entity_id": member_entity_id, "owner_entity_id": owner_entity_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor}
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_security_groups",
        "operation_kind": op_kind,
        "request_payload": req_payload,
        "target_entity_id": security_group_id if isinstance(security_group_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "microsoft_graph",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("operations.json", ops)

    def _finalize(status, response_payload=None, error_code=None, error_message=None, upstream_request_count=0, rate_limited=False):
        finished = _now()
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["status"] = status
                o["attempt_count"] = max(1, int(o.get("attempt_count") or 0) + 1)
                o["rate_limited"] = bool(rate_limited)
                o["upstream_request_count"] = int(upstream_request_count) if isinstance(upstream_request_count, int) and upstream_request_count >= 0 else 0
                o["started_at"] = o.get("started_at") or finished
                o["finished_at"] = finished if status not in ("queued", "running") else None
                o["updated_at"] = finished
                o["response_payload"] = response_payload
                o["error_code"] = error_code
                o["error_message"] = error_message
                break
        _save("operations.json", ops)

    # determine intended upstream usage (coarse)
    intended_upstream = 1 if action not in ("list",) else 0
    if action in ("list_members", "list_owners"):
        intended_upstream = 0
    # enforce: prevent queued->running if rate exceeds (business rule)
    if not _rate_limit_allows(tenant, ops, intended_upstream):
        # keep queued, mark rate_limited true
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["rate_limited"] = True
                o["updated_at"] = _now()
                break
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued and rate_limited=true", operation_id=op_id)

    # transition queued->running
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = _now()
            o["attempt_count"] = 1
            o["updated_at"] = o["started_at"]
            break
    _save("operations.json", ops)

    def _find_group_by_any_id(val):
        if not isinstance(val, str) or not val:
            return None
        # allow passing external_id in security_group_id slot
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id:
                continue
            if e.get("entity_type") != "group_security":
                continue
            if e.get("id") == val or e.get("external_id") == val:
                return e
        return None

    def _find_entity_any(val):
        if not isinstance(val, str) or not val:
            return None
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id:
                continue
            if e.get("id") == val or e.get("external_id") == val:
                return e
        return None

    # --- actions ---
    if action == "create":
        if body is None or not isinstance(body, dict):
            _finalize("failed", None, "VALIDATION_ERROR", "body is required for create", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "body is required for create", operation_id=op_id)
        display_name = body.get("display_name")
        if display_name is not None and not isinstance(display_name, str):
            _finalize("failed", None, "VALIDATION_ERROR", "body.display_name must be a string", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "body.display_name must be a string", operation_id=op_id)

        # external_id: if provided via filters.external_id or body.properties.external_id; else generate
        ext = None
        if isinstance(filters, dict):
            ext = filters.get("external_id")
        if not ext and isinstance(body.get("properties"), dict):
            ext = body["properties"].get("external_id")
        if not ext:
            ext = f"graph:group:{uuid.uuid4().hex}"

        # unique(tenant_id, entity_type, external_id)
        for e in ents:
            if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "group_security" and e.get("external_id") == ext:
                # idempotent create by external_id
                _finalize("succeeded", {"group": e, "operation_id": op_id}, upstream_request_count=intended_upstream)
                return {"operation_id": op_id, "group": e}

        ent_id = _new_id("m365_ent_", ents) or f"m365_ent_{uuid.uuid4().hex.upper()[:20]}"
        row = {
            "id": ent_id,
            "tenant_id": tenant_id,
            "entity_type": "group_security",
            "external_id": ext,
            "display_name": display_name,
            "principal_name": None,
            "mail": body.get("mail") if isinstance(body.get("mail"), str) else None,
            "enabled": None,  # enabled not applicable for groups per constraint
            "status": "active",
            "properties": body.get("properties") if isinstance(body.get("properties"), dict) else {},
            "created_at": now,
            "updated_at": now
        }
        ents.append(row)
        _save("directory_entities.json", ents)
        _finalize("succeeded", {"group": row, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": row}

    if action == "get":
        grp = _find_group_by_any_id(security_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Security group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Security group not found", operation_id=op_id)
        _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp}

    if action == "update":
        grp = _find_group_by_any_id(security_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Security group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Security group not found", operation_id=op_id)
        if body is None or not isinstance(body, dict):
            _finalize("failed", None, "VALIDATION_ERROR", "body is required for update", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "body is required for update", operation_id=op_id)

        if "display_name" in body:
            if body["display_name"] is not None and not isinstance(body["display_name"], str):
                _finalize("failed", None, "VALIDATION_ERROR", "body.display_name must be a string", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.display_name must be a string", operation_id=op_id)
            grp["display_name"] = body["display_name"]
        if "mail" in body:
            if body["mail"] is not None and not isinstance(body["mail"], str):
                _finalize("failed", None, "VALIDATION_ERROR", "body.mail must be a string", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.mail must be a string", operation_id=op_id)
            grp["mail"] = body["mail"]
        if "properties" in body:
            if body["properties"] is not None and not isinstance(body["properties"], dict):
                _finalize("failed", None, "VALIDATION_ERROR", "body.properties must be an object", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.properties must be an object", operation_id=op_id)
            grp["properties"] = body["properties"] or {}
        grp["updated_at"] = _now()
        _save("directory_entities.json", ents)
        _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp}

    if action == "delete":
        grp = _find_group_by_any_id(security_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Security group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Security group not found", operation_id=op_id)
        # lifecycle transition active/pending/error -> deleted
        if grp.get("status") == "deleted":
            # idempotent delete
            _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "group": grp}
        if grp.get("status") not in ("active", "pending", "error"):
            _finalize("failed", None, "INVALID_TRANSITION", f"Cannot delete from status {grp.get('status')}", upstream_request_count=intended_upstream)
            return _err("INVALID_TRANSITION", f"Cannot delete from status {grp.get('status')}", operation_id=op_id)
        grp["status"] = "deleted"
        grp["updated_at"] = _now()
        _save("directory_entities.json", ents)

        # cascade delete memberships (on delete cascade)
        before = len(mems)
        mems = [m for m in mems if not (isinstance(m, dict) and m.get("tenant_id") == tenant_id and m.get("container_entity_id") == grp.get("id"))]
        if len(mems) != before:
            _save("group_memberships.json", mems)

        _finalize("succeeded", {"group": grp, "operation_id": op_id, "memberships_deleted": before - len(mems)}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp, "memberships_deleted": before - len(mems)}

    if action == "list":
        # list groups
        f_status = None
        f_q = None
        f_ext = None
        if isinstance(filters, dict):
            if filters.get("status") is not None and filters.get("status") not in ("active", "pending", "deleted", "error"):
                _finalize("failed", None, "VALIDATION_ERROR", "filters.status is invalid", upstream_request_count=0)
                return _err("VALIDATION_ERROR", "filters.status is invalid", operation_id=op_id)
            f_status = filters.get("status")
            # accept non-string q by coercion (audit had q=2)
            if "q" in filters and filters.get("q") is not None:
                f_q = str(filters.get("q"))
            f_ext = filters.get("external_id") if isinstance(filters.get("external_id"), str) else None

        rows = []
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id or e.get("entity_type") != "group_security":
                continue
            if f_status and e.get("status") != f_status:
                continue
            if f_ext and e.get("external_id") != f_ext:
                continue
            if f_q:
                hay = " ".join([str(e.get("display_name") or ""), str(e.get("mail") or ""), str(e.get("principal_name") or ""), str(e.get("external_id") or "")]).lower()
                if f_q.lower() not in hay:
                    continue
            rows.append(e)

        # sort
        if sort is None:
            sort = "created_at"
        rev = sort.startswith("-")
        key = sort[1:] if rev else sort
        def _k(r):
            if key in ("created_at", "updated_at"):
                return _parse_dt(r.get(key)) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            v = r.get(key)
            return (v or "").lower() if isinstance(v, str) else ""
        rows.sort(key=_k, reverse=rev)

        off = _decode_cursor(cursor)
        if off is None:
            _finalize("failed", None, "VALIDATION_ERROR", "cursor is invalid", upstream_request_count=0)
            return _err("VALIDATION_ERROR", "cursor is invalid", operation_id=op_id)

        cap = 200
        if isinstance(limit, int) and limit >= 1:
            cap = min(200, max(1, limit))
        # if caller passed >200, clamp
        page = rows[off:off + cap]
        next_off = off + len(page)
        has_more = next_off < len(rows)
        next_cursor = _encode_cursor(next_off) if has_more else None

        resp = {"items": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "operation_id": op_id}
        _finalize("succeeded", resp, upstream_request_count=0)
        return resp

    # membership actions
    grp = _find_group_by_any_id(security_group_id)
    if not grp:
        _finalize("failed", None, "NOT_FOUND", "Security group not found", upstream_request_count=intended_upstream)
        return _err("NOT_FOUND", "Security group not found", operation_id=op_id)

    if action in ("list_members", "list_owners"):
        mtype = "group_member" if action == "list_members" else "group_owner"
        items = []
        for m in mems:
            if not isinstance(m, dict):
                continue
            if m.get("tenant_id") != tenant_id or m.get("container_entity_id") != grp.get("id") or m.get("membership_type") != mtype:
                continue
            items.append(m)
        # stable sort by created_at
        items.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc))
        _finalize("succeeded", {"items": items, "total": len(items), "operation_id": op_id}, upstream_request_count=0)
        return {"operation_id": op_id, "items": items, "total": len(items)}

    if action in ("add_member", "remove_member", "add_owner", "remove_owner"):
        target_id = member_entity_id if "member" in action else owner_entity_id
        if not isinstance(target_id, str) or not target_id:
            _finalize("failed", None, "VALIDATION_ERROR", "member_entity_id/owner_entity_id is required", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "member_entity_id/owner_entity_id is required", operation_id=op_id)
        target_ent = _find_entity_any(target_id)
        if not target_ent:
            _finalize("failed", None, "NOT_FOUND", "Target entity not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Target entity not found", operation_id=op_id)

        membership_type = "group_member" if "member" in action else "group_owner"
        # constraint: membership_type IN ('group_member','group_owner') requires container entity_type appropriate
        if grp.get("entity_type") not in ("group_security",):  # this tool only security groups
            _finalize("failed", None, "VALIDATION_ERROR", "container_entity is not a security group", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "container_entity is not a security group", operation_id=op_id)

        # find existing row
        existing = None
        for m in mems:
            if not isinstance(m, dict):
                continue
            if m.get("tenant_id") == tenant_id and m.get("container_entity_id") == grp.get("id") and m.get("member_entity_id") == target_ent.get("id") and m.get("membership_type") == membership_type:
                existing = m
                break

        # simulate managed action with pending->active on success; on failure set error and preserve prior active if existed
        # Since offline, treat as success unless body.properties.force_error is true
        force_error = False
        if isinstance(body, dict) and isinstance(body.get("properties"), dict) and body["properties"].get("force_error") is True:
            force_error = True

        if action.startswith("add_"):
            if existing and existing.get("status") == "active":
                # idempotent
                _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
                return {"operation_id": op_id, "membership": existing}

            prev_active_snapshot = None
            if existing and existing.get("status") == "active":
                prev_active_snapshot = dict(existing)

            if not existing:
                mem_id = _new_id("m365_mem_", mems) or f"m365_mem_{uuid.uuid4().hex.upper()[:20]}"
                existing = {
                    "id": mem_id,
                    "tenant_id": tenant_id,
                    "container_entity_id": grp.get("id"),
                    "member_entity_id": target_ent.get("id"),
                    "membership_type": membership_type,
                    "status": "pending",
                    "source": "managed",
                    "created_at": _now(),
                    "updated_at": _now()
                }
                mems.append(existing)
            else:
                # legal transitions to pending from error only; from removed is terminal
                if existing.get("status") == "removed":
                    _finalize("failed", None, "INVALID_TRANSITION", "Cannot re-add a removed membership record", upstream_request_count=intended_upstream)
                    return _err("INVALID_TRANSITION", "Cannot re-add a removed membership record", operation_id=op_id)
                if existing.get("status") in ("error", "pending"):
                    existing["status"] = "pending"
                    existing["updated_at"] = _now()

            if force_error:
                # failure must set status=error and preserve previous active if it existed
                existing["status"] = "error"
                existing["updated_at"] = _now()
                _save("group_memberships.json", mems)
                _finalize("failed", {"membership": existing, "previous_active": prev_active_snapshot, "operation_id": op_id}, "graph.upsert_membership_failed", "Upstream confirmation failed; membership set to error", upstream_request_count=intended_upstream)
                return _err("CONFLICT", "Upstream confirmation failed; membership set to error", operation_id=op_id, membership=existing)

            # success: pending -> active
            existing["status"] = "active"
            existing["updated_at"] = _now()
            _save("group_memberships.json", mems)
            _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "membership": existing}

        # remove_*
        if not existing:
            _finalize("failed", None, "NOT_FOUND", "Membership not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Membership not found", operation_id=op_id)
        if existing.get("status") == "removed":
            # idempotent
            _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "membership": existing}
        if existing.get("status") not in ("active", "pending", "error"):
            _finalize("failed", None, "INVALID_TRANSITION", f"Cannot remove membership from status {existing.get('status')}", upstream_request_count=intended_upstream)
            return _err("INVALID_TRANSITION", f"Cannot remove membership from status {existing.get('status')}", operation_id=op_id)

        if force_error:
            existing["status"] = "error"
            existing["updated_at"] = _now()
            _save("group_memberships.json", mems)
            _finalize("failed", {"membership": existing, "operation_id": op_id}, "graph.remove_membership_failed", "Upstream confirmation failed; membership set to error", upstream_request_count=intended_upstream)
            return _err("CONFLICT", "Upstream confirmation failed; membership set to error", operation_id=op_id, membership=existing)

        existing["status"] = "removed"
        existing["updated_at"] = _now()
        _save("group_memberships.json", mems)
        _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "membership": existing}

    _finalize("failed", None, "VALIDATION_ERROR", "Unsupported action", upstream_request_count=intended_upstream)
    return _err("VALIDATION_ERROR", "Unsupported action", operation_id=op_id)

def manage_m365_groups(tenant_id, action, m365_group_id=None, member_entity_id=None, owner_entity_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(200):
            core = uuid.uuid4().hex.upper()
            cand = f"{prefix}{core[:20]}"
            if cand not in used:
                return cand
        return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        lim = tenant_row.get("rate_limit_per_minute")
        try:
            lim = int(lim)
        except Exception:
            lim = 60
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                continue
        return (used + max(0, int(new_upstream))) <= lim

    # validate
    if not isinstance(tenant_id, str) or re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id) is None:
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    allowed = {"create", "update", "delete", "get", "list", "add_member", "remove_member", "add_owner", "remove_owner", "list_members", "list_owners", "enable_teams", "disable_teams"}
    if action not in allowed:
        return _err("VALIDATION_ERROR", "action is invalid")
    for nm, val in (("m365_group_id", m365_group_id), ("member_entity_id", member_entity_id), ("owner_entity_id", owner_entity_id)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None and (not isinstance(sort, str) or sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"}):
        return _err("VALIDATION_ERROR", "sort is invalid")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be >= 1")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    tenants = _load("tenants.json")
    ops = _load("operations.json")
    ents = _load("directory_entities.json")
    mems = _load("group_memberships.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)

    now = _now()
    op_id = _new_id("m365_opr_", ops) or f"m365_opr_{uuid.uuid4().hex.upper()[:20]}"
    op_kind = "read" if action in ("get", "list", "list_members", "list_owners") else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    ops.append({
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_m365_groups",
        "operation_kind": op_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "m365_group_id": m365_group_id, "member_entity_id": member_entity_id, "owner_entity_id": owner_entity_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
        "target_entity_id": m365_group_id if isinstance(m365_group_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "microsoft_graph",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    })
    _save("operations.json", ops)

    def _finalize(status, response_payload=None, error_code=None, error_message=None, upstream_request_count=0, rate_limited=False):
        finished = _now()
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["status"] = status
                o["attempt_count"] = max(1, int(o.get("attempt_count") or 0) + 1)
                o["rate_limited"] = bool(rate_limited)
                o["upstream_request_count"] = int(upstream_request_count) if isinstance(upstream_request_count, int) and upstream_request_count >= 0 else 0
                o["started_at"] = o.get("started_at") or finished
                o["finished_at"] = finished if status not in ("queued", "running") else None
                o["updated_at"] = finished
                o["response_payload"] = response_payload
                o["error_code"] = error_code
                o["error_message"] = error_message
                break
        _save("operations.json", ops)

    if not tenant:
        _finalize("failed", None, "NOT_FOUND", "Tenant not found", upstream_request_count=0)
        return _err("NOT_FOUND", "Tenant not found", operation_id=op_id)
    if tenant.get("status") != "active":
        _finalize("failed", None, "UNAUTHORIZED", "Tenant is not active", upstream_request_count=0)
        return _err("UNAUTHORIZED", "Tenant is not active", operation_id=op_id)

    intended_upstream = 1 if action not in ("list", "list_members", "list_owners") else 0
    if not _rate_limit_allows(tenant, ops, intended_upstream):
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["rate_limited"] = True
                o["updated_at"] = _now()
                break
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued and rate_limited=true", operation_id=op_id)

    # queued->running
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = _now()
            o["attempt_count"] = 1
            o["updated_at"] = o["started_at"]
            break
    _save("operations.json", ops)

    def _find_group(val):
        if not isinstance(val, str) or not val:
            return None
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id or e.get("entity_type") != "group_m365":
                continue
            if e.get("id") == val or e.get("external_id") == val:
                return e
        return None

    def _find_ent(val):
        if not isinstance(val, str) or not val:
            return None
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id:
                continue
            if e.get("id") == val or e.get("external_id") == val:
                return e
        return None

    if action == "create":
        if body is None or not isinstance(body, dict):
            _finalize("failed", None, "VALIDATION_ERROR", "body is required for create", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "body is required for create", operation_id=op_id)
        ext = None
        if isinstance(filters, dict):
            ext = filters.get("external_id")
        if not ext and isinstance(body.get("properties"), dict):
            ext = body["properties"].get("external_id")
        if not ext:
            ext = f"graph:m365group:{uuid.uuid4().hex}"

        for e in ents:
            if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "group_m365" and e.get("external_id") == ext:
                _finalize("succeeded", {"group": e, "operation_id": op_id}, upstream_request_count=intended_upstream)
                return {"operation_id": op_id, "group": e}

        ent_id = _new_id("m365_ent_", ents) or f"m365_ent_{uuid.uuid4().hex.upper()[:20]}"
        row = {
            "id": ent_id,
            "tenant_id": tenant_id,
            "entity_type": "group_m365",
            "external_id": ext,
            "display_name": body.get("display_name") if isinstance(body.get("display_name"), str) else None,
            "principal_name": None,
            "mail": body.get("mail") if isinstance(body.get("mail"), str) else None,
            "enabled": None,
            "status": "active",
            "properties": body.get("properties") if isinstance(body.get("properties"), dict) else {}
        }
        # Teams enablement stored in properties.teamEnabled
        row["properties"].setdefault("teamEnabled", False)
        row["created_at"] = now
        row["updated_at"] = now
        ents.append(row)
        _save("directory_entities.json", ents)
        _finalize("succeeded", {"group": row, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": row}

    if action == "get":
        grp = _find_group(m365_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Group not found", operation_id=op_id)
        _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp}

    if action == "update":
        grp = _find_group(m365_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Group not found", operation_id=op_id)
        if body is None or not isinstance(body, dict):
            _finalize("failed", None, "VALIDATION_ERROR", "body is required for update", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "body is required for update", operation_id=op_id)
        if "display_name" in body:
            if body["display_name"] is not None and not isinstance(body["display_name"], str):
                _finalize("failed", None, "VALIDATION_ERROR", "body.display_name must be a string", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.display_name must be a string", operation_id=op_id)
            grp["display_name"] = body["display_name"]
        if "mail" in body:
            if body["mail"] is not None and not isinstance(body["mail"], str):
                _finalize("failed", None, "VALIDATION_ERROR", "body.mail must be a string", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.mail must be a string", operation_id=op_id)
            grp["mail"] = body["mail"]
        if "properties" in body:
            if body["properties"] is not None and not isinstance(body["properties"], dict):
                _finalize("failed", None, "VALIDATION_ERROR", "body.properties must be an object", upstream_request_count=intended_upstream)
                return _err("VALIDATION_ERROR", "body.properties must be an object", operation_id=op_id)
            grp["properties"] = body["properties"] or {}
            grp["properties"].setdefault("teamEnabled", False)
        grp["updated_at"] = _now()
        _save("directory_entities.json", ents)
        _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp}

    if action == "delete":
        grp = _find_group(m365_group_id)
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Group not found", operation_id=op_id)
        if grp.get("status") == "deleted":
            _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "group": grp}
        if grp.get("status") not in ("active", "pending", "error"):
            _finalize("failed", None, "INVALID_TRANSITION", f"Cannot delete from status {grp.get('status')}", upstream_request_count=intended_upstream)
            return _err("INVALID_TRANSITION", f"Cannot delete from status {grp.get('status')}", operation_id=op_id)
        grp["status"] = "deleted"
        grp["updated_at"] = _now()
        _save("directory_entities.json", ents)
        before = len(mems)
        mems = [m for m in mems if not (isinstance(m, dict) and m.get("tenant_id") == tenant_id and m.get("container_entity_id") == grp.get("id"))]
        if len(mems) != before:
            _save("group_memberships.json", mems)
        _finalize("succeeded", {"group": grp, "operation_id": op_id, "memberships_deleted": before - len(mems)}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp, "memberships_deleted": before - len(mems)}

    if action == "list":
        f_status = None
        f_q = None
        f_ext = None
        if isinstance(filters, dict):
            if filters.get("status") is not None and filters.get("status") not in ("active", "pending", "deleted", "error"):
                _finalize("failed", None, "VALIDATION_ERROR", "filters.status is invalid", upstream_request_count=0)
                return _err("VALIDATION_ERROR", "filters.status is invalid", operation_id=op_id)
            f_status = filters.get("status")
            if "q" in filters and filters.get("q") is not None:
                f_q = str(filters.get("q"))
            f_ext = filters.get("external_id") if isinstance(filters.get("external_id"), str) else None

        rows = []
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("tenant_id") != tenant_id or e.get("entity_type") != "group_m365":
                continue
            if f_status and e.get("status") != f_status:
                continue
            if f_ext and e.get("external_id") != f_ext:
                continue
            if f_q:
                hay = " ".join([str(e.get("display_name") or ""), str(e.get("mail") or ""), str(e.get("external_id") or "")]).lower()
                if f_q.lower() not in hay:
                    continue
            rows.append(e)

        if sort is None:
            sort = "created_at"
        rev = sort.startswith("-")
        key = sort[1:] if rev else sort
        def _k(r):
            if key in ("created_at", "updated_at"):
                return _parse_dt(r.get(key)) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            v = r.get(key)
            return (v or "").lower() if isinstance(v, str) else ""
        rows.sort(key=_k, reverse=rev)

        off = _decode_cursor(cursor)
        if off is None:
            _finalize("failed", None, "VALIDATION_ERROR", "cursor is invalid", upstream_request_count=0)
            return _err("VALIDATION_ERROR", "cursor is invalid", operation_id=op_id)

        cap = 200
        if isinstance(limit, int) and limit >= 1:
            cap = min(200, max(1, limit))
        page = rows[off:off + cap]
        next_off = off + len(page)
        has_more = next_off < len(rows)
        next_cursor = _encode_cursor(next_off) if has_more else None
        resp = {"items": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "operation_id": op_id}
        _finalize("succeeded", resp, upstream_request_count=0)
        return resp

    # teams enable/disable
    grp = _find_group(m365_group_id)
    if action in ("enable_teams", "disable_teams"):
        if not grp:
            _finalize("failed", None, "NOT_FOUND", "Group not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Group not found", operation_id=op_id)
        grp.setdefault("properties", {})
        grp["properties"]["teamEnabled"] = True if action == "enable_teams" else False
        grp["updated_at"] = _now()
        _save("directory_entities.json", ents)
        _finalize("succeeded", {"group": grp, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "group": grp}

    # membership operations (same semantics as groups business rule)
    if not grp:
        grp = _find_group(m365_group_id)
    if not grp:
        _finalize("failed", None, "NOT_FOUND", "Group not found", upstream_request_count=intended_upstream)
        return _err("NOT_FOUND", "Group not found", operation_id=op_id)

    if action in ("list_members", "list_owners"):
        mtype = "group_member" if action == "list_members" else "group_owner"
        items = [m for m in mems if isinstance(m, dict) and m.get("tenant_id") == tenant_id and m.get("container_entity_id") == grp.get("id") and m.get("membership_type") == mtype]
        items.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc))
        _finalize("succeeded", {"items": items, "total": len(items), "operation_id": op_id}, upstream_request_count=0)
        return {"operation_id": op_id, "items": items, "total": len(items)}

    if action in ("add_member", "remove_member", "add_owner", "remove_owner"):
        target_id = member_entity_id if "member" in action else owner_entity_id
        if not isinstance(target_id, str) or not target_id:
            _finalize("failed", None, "VALIDATION_ERROR", "member_entity_id/owner_entity_id is required", upstream_request_count=intended_upstream)
            return _err("VALIDATION_ERROR", "member_entity_id/owner_entity_id is required", operation_id=op_id)
        target_ent = _find_ent(target_id)
        if not target_ent:
            _finalize("failed", None, "NOT_FOUND", "Target entity not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Target entity not found", operation_id=op_id)

        membership_type = "group_member" if "member" in action else "group_owner"
        existing = None
        for m in mems:
            if not isinstance(m, dict):
                continue
            if m.get("tenant_id") == tenant_id and m.get("container_entity_id") == grp.get("id") and m.get("member_entity_id") == target_ent.get("id") and m.get("membership_type") == membership_type:
                existing = m
                break

        force_error = False
        if isinstance(body, dict) and isinstance(body.get("properties"), dict) and body["properties"].get("force_error") is True:
            force_error = True

        if action.startswith("add_"):
            if existing and existing.get("status") == "active":
                _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
                return {"operation_id": op_id, "membership": existing}
            if not existing:
                mem_id = _new_id("m365_mem_", mems) or f"m365_mem_{uuid.uuid4().hex.upper()[:20]}"
                existing = {
                    "id": mem_id,
                    "tenant_id": tenant_id,
                    "container_entity_id": grp.get("id"),
                    "member_entity_id": target_ent.get("id"),
                    "membership_type": membership_type,
                    "status": "pending",
                    "source": "managed",
                    "created_at": _now(),
                    "updated_at": _now()
                }
                mems.append(existing)
            else:
                if existing.get("status") == "removed":
                    _finalize("failed", None, "INVALID_TRANSITION", "Cannot re-add a removed membership record", upstream_request_count=intended_upstream)
                    return _err("INVALID_TRANSITION", "Cannot re-add a removed membership record", operation_id=op_id)
                existing["status"] = "pending"
                existing["updated_at"] = _now()

            if force_error:
                existing["status"] = "error"
                existing["updated_at"] = _now()
                _save("group_memberships.json", mems)
                _finalize("failed", {"membership": existing, "operation_id": op_id}, "graph.upsert_membership_failed", "Upstream confirmation failed; membership set to error", upstream_request_count=intended_upstream)
                return _err("CONFLICT", "Upstream confirmation failed; membership set to error", operation_id=op_id, membership=existing)

            existing["status"] = "active"
            existing["updated_at"] = _now()
            _save("group_memberships.json", mems)
            _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "membership": existing}

        if not existing:
            _finalize("failed", None, "NOT_FOUND", "Membership not found", upstream_request_count=intended_upstream)
            return _err("NOT_FOUND", "Membership not found", operation_id=op_id)
        if existing.get("status") == "removed":
            _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
            return {"operation_id": op_id, "membership": existing}

        if force_error:
            existing["status"] = "error"
            existing["updated_at"] = _now()
            _save("group_memberships.json", mems)
            _finalize("failed", {"membership": existing, "operation_id": op_id}, "graph.remove_membership_failed", "Upstream confirmation failed; membership set to error", upstream_request_count=intended_upstream)
            return _err("CONFLICT", "Upstream confirmation failed; membership set to error", operation_id=op_id, membership=existing)

        existing["status"] = "removed"
        existing["updated_at"] = _now()
        _save("group_memberships.json", mems)
        _finalize("succeeded", {"membership": existing, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "membership": existing}

    _finalize("failed", None, "VALIDATION_ERROR", "Unsupported action", upstream_request_count=intended_upstream)
    return _err("VALIDATION_ERROR", "Unsupported action", operation_id=op_id)

def manage_exchange_settings(tenant_id, action, mailbox_entity_id=None, transport_rule_entity_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    def _op_kind_for_action(act):
        if act in ("get_mailbox", "get_transport_rule"):
            return "read"
        if act in ("list_mailboxes", "list_transport_rules"):
            return "search"
        if act in ("create_transport_rule",):
            return "create"
        if act in ("update_mailbox", "update_transport_rule"):
            return "update"
        if act in ("delete_transport_rule",):
            return "delete"
        return "update"

    def _validate_body(b):
        if b is None:
            return True, None
        if not isinstance(b, dict):
            return False, "body must be an object"
        allowed = {"display_name", "principal_name", "mail", "enabled", "properties"}
        for k in b.keys():
            if k not in allowed:
                return False, f"body contains unknown field '{k}'"
        if "display_name" in b and b["display_name"] is not None and not isinstance(b["display_name"], str):
            return False, "body.display_name must be a string"
        if "principal_name" in b and b["principal_name"] is not None and not isinstance(b["principal_name"], str):
            return False, "body.principal_name must be a string"
        if "mail" in b and b["mail"] is not None and not isinstance(b["mail"], str):
            return False, "body.mail must be a string"
        if "enabled" in b and b["enabled"] is not None and not isinstance(b["enabled"], bool):
            return False, "body.enabled must be a boolean"
        if "properties" in b and b["properties"] is not None and not isinstance(b["properties"], dict):
            return False, "body.properties must be an object"
        return True, None

    # Validate minimal required types/enums; relax over-strict regex enforcement (audit requires accepting actual args)
    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    allowed_actions = {
        "get_mailbox", "update_mailbox", "list_mailboxes",
        "get_transport_rule", "create_transport_rule", "update_transport_rule",
        "delete_transport_rule", "list_transport_rules"
    }
    if action not in allowed_actions:
        return _err("VALIDATION_ERROR", "action must be one of get_mailbox, update_mailbox, list_mailboxes, get_transport_rule, create_transport_rule, update_transport_rule, delete_transport_rule, list_transport_rules")
    ok, msg = _validate_body(body)
    if not ok:
        return _err("VALIDATION_ERROR", msg)

    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        for k in filters.keys():
            if k not in ("entity_type", "status", "q", "external_id"):
                return _err("VALIDATION_ERROR", f"filters contains unknown field '{k}'")
        if "entity_type" in filters and filters["entity_type"] is not None and filters["entity_type"] not in ("exchange_mailbox", "exchange_transport_rule"):
            return _err("VALIDATION_ERROR", "filters.entity_type must be 'exchange_mailbox' or 'exchange_transport_rule'")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("active", "pending", "deleted", "error"):
            return _err("VALIDATION_ERROR", "filters.status must be one of active, pending, deleted, error")
        # accept q as any primitive convertible to str (audit showed integer input)
        if "q" in filters and filters["q"] is not None and not isinstance(filters["q"], (str, int, float, bool)):
            return _err("VALIDATION_ERROR", "filters.q must be a string")
        if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
            return _err("VALIDATION_ERROR", "filters.external_id must be a string")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"):
        return _err("VALIDATION_ERROR", "sort must be one of created_at, -created_at, updated_at, -updated_at, display_name, -display_name")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")

    # Create operation row (always)
    op_id = _new_id("m365_opr_", ops)
    op_now = _now()
    target_entity_id = None
    if action in ("get_mailbox", "update_mailbox"):
        target_entity_id = mailbox_entity_id if isinstance(mailbox_entity_id, str) and mailbox_entity_id else None
    elif action in ("get_transport_rule", "update_transport_rule", "delete_transport_rule"):
        target_entity_id = transport_rule_entity_id if isinstance(transport_rule_entity_id, str) and transport_rule_entity_id else None

    # Determine upstream request cost heuristically
    upstream_cost = 1 if action.startswith("list_") else 1
    rate_limited = not _rate_limit_allows(tenant_row, ops, upstream_cost)

    op_row = {
        "id": op_id,
        "tenant_id": tenant_row["id"],
        "tool_name": "manage_exchange_settings",
        "operation_kind": _op_kind_for_action(action),
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "mailbox_entity_id": mailbox_entity_id,
            "transport_rule_entity_id": transport_rule_entity_id,
            "body": body,
            "filters": filters,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        },
        "target_entity_id": target_entity_id,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": bool(rate_limited),
        "upstream_provider": "exchange_online",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": op_now,
        "updated_at": op_now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    # If rate-limited, keep queued and return operation snapshot (observable dynamics)
    if rate_limited:
        op_row["upstream_request_count"] = 0
        op_row["updated_at"] = _now()
        _save("operations.json", ops)
        return {
            "operation": op_row,
            "rate_limited": True,
            "result": None,
        }

    # Transition queued->running (allowed); record started_at
    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload, upstream_count=1):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = int(upstream_count)
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(code, message, upstream_count=1):
        op_row["status"] = "failed"
        op_row["error_code"] = code
        op_row["error_message"] = message
        op_row["upstream_request_count"] = int(upstream_count) if isinstance(upstream_count, int) and upstream_count >= 0 else 0
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err("NOT_FOUND" if code in ("exo.mailbox_not_found", "exo.transport_rule_not_found") else "VALIDATION_ERROR", message, operation_id=op_id)

    def _find_entity(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("id") == eid and e.get("tenant_id") == tenant_id), None)

    # Actions
    if action == "get_mailbox":
        ent = _find_entity(mailbox_entity_id)
        if not ent or ent.get("entity_type") != "exchange_mailbox":
            return _finish_error("exo.mailbox_not_found", "Mailbox entity not found for tenant", upstream_count=1)
        return _finish_success({"mailbox": ent}, upstream_count=1)

    if action == "update_mailbox":
        ent = _find_entity(mailbox_entity_id)
        if not ent or ent.get("entity_type") != "exchange_mailbox":
            return _finish_error("exo.mailbox_not_found", "Mailbox entity not found for tenant", upstream_count=1)

        # enforce entity constraints: principal_name required for exchange_mailbox
        merged = dict(ent)
        b = body or {}
        for k in ("display_name", "principal_name", "mail", "enabled"):
            if k in b:
                merged[k] = b.get(k)
        if "properties" in b:
            props = merged.get("properties") if isinstance(merged.get("properties"), dict) else {}
            props.update(b.get("properties") or {})
            merged["properties"] = props

        if not merged.get("principal_name"):
            return _finish_error("exo.validation_failed", "principal_name is required for exchange_mailbox", upstream_count=1)

        # enabled may be non-null only for certain types; exchange_mailbox not allowed -> force validation error if set non-null
        if "enabled" in b and b.get("enabled") is not None:
            return _finish_error("exo.validation_failed", "enabled may be non-null only for user/device/intune_device_* entity types", upstream_count=1)

        # Apply update
        ent.update({
            "display_name": merged.get("display_name"),
            "principal_name": merged.get("principal_name"),
            "mail": merged.get("mail"),
            "properties": merged.get("properties"),
            "updated_at": _now(),
        })
        _save("directory_entities.json", ents)
        return _finish_success({"mailbox": ent}, upstream_count=1)

    if action == "list_mailboxes" or action == "list_transport_rules":
        wanted_type = "exchange_mailbox" if action == "list_mailboxes" else "exchange_transport_rule"
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == wanted_type]

        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("q") is not None:
            q = str(f.get("q")).lower()
            def _m(e):
                for key in ("display_name", "mail", "principal_name", "external_id"):
                    v = e.get(key)
                    if isinstance(v, str) and q in v.lower():
                        return True
                return False
            rows = [e for e in rows if _m(e)]

        # sort
        rev = sort.startswith("-")
        field = sort[1:] if rev else sort
        def _key(e):
            v = e.get(field)
            if v is None:
                return ""
            return v
        rows.sort(key=_key, reverse=rev)

        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _encode_cursor(next_off) if has_more else None

        payload = {
            "items": page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
        return _finish_success(payload, upstream_count=1)

    if action == "get_transport_rule":
        ent = _find_entity(transport_rule_entity_id)
        if not ent or ent.get("entity_type") != "exchange_transport_rule":
            return _finish_error("exo.transport_rule_not_found", "Transport rule entity not found for tenant", upstream_count=1)
        return _finish_success({"transport_rule": ent}, upstream_count=1)

    if action == "create_transport_rule":
        b = body or {}
        # allow create without display_name but must have at least properties or display_name
        if not b:
            return _finish_error("exo.validation_failed", "body is required for create_transport_rule", upstream_count=1)

        ext = None
        props = b.get("properties") if isinstance(b.get("properties"), dict) else {}
        # external_id from props if present, else generated
        if isinstance(props.get("external_id"), str) and props.get("external_id"):
            ext = props.get("external_id")
        if not ext:
            ext = f"TransportRule:{uuid.uuid4().hex}"

        # unique(tenant_id, entity_type, external_id)
        for e in ents:
            if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "exchange_transport_rule" and e.get("external_id") == ext:
                # idempotent-ish: treat as update of properties/display_name
                if "display_name" in b:
                    e["display_name"] = b.get("display_name")
                if "properties" in b:
                    p0 = e.get("properties") if isinstance(e.get("properties"), dict) else {}
                    p0.update(props)
                    e["properties"] = p0
                e["updated_at"] = _now()
                _save("directory_entities.json", ents)
                return _finish_success({"transport_rule": e, "idempotent": True}, upstream_count=1)

        ent = {
            "id": _new_id("m365_ent_", ents),
            "tenant_id": tenant_id,
            "entity_type": "exchange_transport_rule",
            "external_id": ext,
            "display_name": b.get("display_name"),
            "principal_name": None,
            "mail": None,
            "enabled": None,
            "status": "active",
            "properties": props if props else None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        ents.append(ent)
        _save("directory_entities.json", ents)
        op_row["target_entity_id"] = ent["id"]
        _save("operations.json", ops)
        return _finish_success({"transport_rule": ent}, upstream_count=1)

    if action == "update_transport_rule":
        ent = _find_entity(transport_rule_entity_id)
        if not ent or ent.get("entity_type") != "exchange_transport_rule":
            return _finish_error("exo.transport_rule_not_found", "Transport rule entity not found for tenant", upstream_count=1)
        b = body or {}
        if "display_name" in b:
            ent["display_name"] = b.get("display_name")
        if "properties" in b:
            p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
            p0.update(b.get("properties") or {})
            ent["properties"] = p0
        if "enabled" in b and b.get("enabled") is not None:
            return _finish_error("exo.validation_failed", "enabled may be non-null only for user/device/intune_device_* entity types", upstream_count=1)
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"transport_rule": ent}, upstream_count=1)

    if action == "delete_transport_rule":
        ent = _find_entity(transport_rule_entity_id)
        if not ent or ent.get("entity_type") != "exchange_transport_rule":
            return _finish_error("exo.transport_rule_not_found", "Transport rule entity not found for tenant", upstream_count=1)
        # lifecycle: active/pending/error -> deleted allowed; deleted terminal
        cur = ent.get("status")
        if cur == "deleted":
            # idempotent delete
            return _finish_success({"transport_rule": ent, "idempotent": True}, upstream_count=1)
        if cur not in ("active", "pending", "error"):
            return _finish_error("exo.validation_failed", "Invalid entity status transition to deleted", upstream_count=1)
        ent["status"] = "deleted"
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"transport_rule": ent}, upstream_count=1)

    return _finish_error("exo.validation_failed", "Unhandled action", upstream_count=0)

def manage_user_settings(tenant_id, action, user_id=None, body=None, sku_ids=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
