                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    def _validate_body(b):
        if b is None:
            return True, None
        if not isinstance(b, dict):
            return False, "body must be an object"
        allowed = {"display_name", "principal_name", "mail", "enabled", "properties"}
        for k in b.keys():
            if k not in allowed:
                return False, f"body contains unknown field '{k}'"
        if "display_name" in b and b["display_name"] is not None and not isinstance(b["display_name"], str):
            return False, "body.display_name must be a string"
        if "principal_name" in b and b["principal_name"] is not None and not isinstance(b["principal_name"], str):
            return False, "body.principal_name must be a string"
        if "mail" in b and b["mail"] is not None and not isinstance(b["mail"], str):
            return False, "body.mail must be a string"
        if "enabled" in b and b["enabled"] is not None and not isinstance(b["enabled"], bool):
            return False, "body.enabled must be a boolean"
        if "properties" in b and b["properties"] is not None and not isinstance(b["properties"], dict):
            return False, "body.properties must be an object"
        return True, None

    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if action not in ("get", "list", "update", "assign_licenses", "remove_licenses", "enable", "disable"):
        return _err("VALIDATION_ERROR", "action must be one of get, list, update, assign_licenses, remove_licenses, enable, disable")

    ok, msg = _validate_body(body)
    if not ok:
        return _err("VALIDATION_ERROR", msg)

    if sku_ids is not None:
        if not isinstance(sku_ids, list) or any((not isinstance(x, str)) for x in sku_ids):
            return _err("VALIDATION_ERROR", "sku_ids must be an array of strings")

    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        for k in filters.keys():
            if k not in ("status", "enabled", "q", "external_id"):
                return _err("VALIDATION_ERROR", f"filters contains unknown field '{k}'")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("active", "pending", "deleted", "error"):
            return _err("VALIDATION_ERROR", "filters.status must be one of active, pending, deleted, error")
        if "enabled" in filters and filters["enabled"] is not None and not isinstance(filters["enabled"], bool):
            return _err("VALIDATION_ERROR", "filters.enabled must be a boolean")
        if "q" in filters and filters["q"] is not None and not isinstance(filters["q"], (str, int, float, bool)):
            return _err("VALIDATION_ERROR", "filters.q must be a string")
        if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
            return _err("VALIDATION_ERROR", "filters.external_id must be a string")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name", "principal_name", "-principal_name"):
        return _err("VALIDATION_ERROR", "sort must be one of created_at, -created_at, updated_at, -updated_at, display_name, -display_name, principal_name, -principal_name")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")

    # create operation row
    op_id = _new_id("m365_opr_", ops)
    op_now = _now()
    target_entity_id = user_id if isinstance(user_id, str) and user_id else None
    upstream_cost = 1
    rate_limited = not _rate_limit_allows(tenant_row, ops, upstream_cost)
    kind = "read" if action == "get" else ("search" if action == "list" else "update")

    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_user_settings",
        "operation_kind": kind,
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "user_id": user_id,
            "body": body,
            "sku_ids": sku_ids,
            "filters": filters,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        },
        "target_entity_id": target_entity_id,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": bool(rate_limited),
        "upstream_provider": "microsoft_graph",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": op_now,
        "updated_at": op_now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload, upstream_count=1):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = int(upstream_count)
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(err_code, msg, upstream_count=1, api_code="VALIDATION_ERROR"):
        op_row["status"] = "failed"
        op_row["error_code"] = err_code
        op_row["error_message"] = msg
        op_row["upstream_request_count"] = int(upstream_count) if isinstance(upstream_count, int) and upstream_count >= 0 else 0
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err(api_code, msg, operation_id=op_id)

    def _find_user(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("id") == eid and e.get("tenant_id") == tenant_id and e.get("entity_type") == "user"), None)

    if action == "get":
        u = _find_user(user_id)
        if not u:
            return _finish_error("graph.user_not_found", "User entity not found for tenant", upstream_count=1, api_code="NOT_FOUND")
        return _finish_success({"user": u}, upstream_count=1)

    if action == "list":
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "user"]
        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("enabled") is not None:
            rows = [e for e in rows if e.get("enabled") == f.get("enabled")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("q") is not None:
            q = str(f.get("q")).lower()
            def _m(e):
                for key in ("display_name", "mail", "principal_name", "external_id"):
                    v = e.get(key)
                    if isinstance(v, str) and q in v.lower():
                        return True
                return False
            rows = [e for e in rows if _m(e)]
        rev = sort.startswith("-")
        field = sort[1:] if rev else sort
        def _key(e):
            v = e.get(field)
            if v is None:
                return ""
            return v
        rows.sort(key=_key, reverse=rev)
        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _encode_cursor(next_off) if has_more else None
        return _finish_success({"items": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}, upstream_count=1)

    # update/enable/disable/license ops
    u = _find_user(user_id)
    if not u:
        return _finish_error("graph.user_not_found", "User entity not found for tenant", upstream_count=1, api_code="NOT_FOUND")

    if action in ("enable", "disable"):
        desired = True if action == "enable" else False
        # enabled allowed for user
        u["enabled"] = desired
        u["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"user": u}, upstream_count=1)

    if action == "update":
        b = body or {}
        if not b:
            return _finish_error("graph.validation_failed", "body is required for update", upstream_count=0)
        for k in ("display_name", "principal_name", "mail", "enabled"):
            if k in b:
                u[k] = b.get(k)
        if "properties" in b:
            p0 = u.get("properties") if isinstance(u.get("properties"), dict) else {}
            p0.update(b.get("properties") or {})
            u["properties"] = p0
        # constraint: principal_name required for user
        if not u.get("principal_name"):
            return _finish_error("graph.validation_failed", "principal_name is required for user", upstream_count=1)
        u["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"user": u}, upstream_count=1)

    # licenses stored in properties.licenses (array)
    if action in ("assign_licenses", "remove_licenses"):
        if not sku_ids:
            return _finish_error("graph.validation_failed", "sku_ids is required for license operations", upstream_count=0)
        p0 = u.get("properties") if isinstance(u.get("properties"), dict) else {}
        lic = p0.get("licenses")
        if not isinstance(lic, list):
            lic = []
        if action == "assign_licenses":
            for s in sku_ids:
                if s not in lic:
                    lic.append(s)
        else:
            lic = [x for x in lic if x not in set(sku_ids)]
        p0["licenses"] = lic
        u["properties"] = p0
        u["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"user": u}, upstream_count=1)

    return _finish_error("graph.validation_failed", "Unhandled action", upstream_count=0)

def manage_offboarding(tenant_id, action, user_id=None, operation_id=None, body=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    # validate
    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if action not in ("start", "status", "cancel"):
        return _err("VALIDATION_ERROR", "action must be one of start, status, cancel")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")
    mems = _load("group_memberships.json")

    def _find_user(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("id") == eid and e.get("tenant_id") == tenant_id and e.get("entity_type") == "user"), None)

    def _append_op(op_row):
        ops.append(op_row)
        _save("operations.json", ops)

    def _update_op(op_row):
        _save("operations.json", ops)

    def _make_op(tool_name, kind, request_payload, target_entity_id=None, upstream_provider="other", upstream_request_count=0, parent_operation_id=None):
        op_id = _new_id("m365_opr_", ops)
        now = _now()
        rp = dict(request_payload or {})
        if parent_operation_id:
            rp["parent_operation_id"] = parent_operation_id
        row = {
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": tool_name,
            "operation_kind": kind,
            "request_payload": rp,
            "target_entity_id": target_entity_id,
            "status": "queued",
            "attempt_count": 0,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": upstream_provider,
            "upstream_request_count": int(upstream_request_count) if isinstance(upstream_request_count, int) and upstream_request_count >= 0 else 0,
            "response_format": "json",
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        return row

    def _run_child(op_row, do_fn, upstream_cost=1):
        # rate limiting is about queued->running transition
        rate_limited = not _rate_limit_allows(tenant_row, ops, upstream_cost)
        op_row["rate_limited"] = bool(rate_limited)
        _update_op(op_row)
        if rate_limited:
            # keep queued, do not run
            return ("rate_limited", None)

        op_row["status"] = "running"
        op_row["attempt_count"] = 1
        op_row["started_at"] = _now()
        op_row["updated_at"] = op_row["started_at"]
        op_row["rate_limited"] = False
        _update_op(op_row)

        try:
            result = do_fn()
        except Exception as e:
            op_row["status"] = "failed"
            op_row["error_code"] = "workflow.child_exception"
            op_row["error_message"] = str(e)
            op_row["upstream_request_count"] = upstream_cost
            op_row["finished_at"] = _now()
            op_row["updated_at"] = op_row["finished_at"]
            _update_op(op_row)
            return ("failed", None)

        if isinstance(result, dict) and result.get("error"):
            op_row["status"] = "failed"
            op_row["error_code"] = result["error"].get("code")
            op_row["error_message"] = result["error"].get("message")
            op_row["upstream_request_count"] = upstream_cost
            op_row["finished_at"] = _now()
            op_row["updated_at"] = op_row["finished_at"]
            _update_op(op_row)
            return ("failed", None)

        op_row["status"] = "succeeded"
        op_row["response_payload"] = result
        op_row["upstream_request_count"] = upstream_cost
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _update_op(op_row)
        return ("succeeded", result)

    # Always create an operations row for this tool invocation
    op_id = _new_id("m365_opr_", ops)
    now = _now()
    parent_lookup = operation_id

    request_payload = {
        "tenant_id": tenant_id,
        "action": action,
        "user_id": user_id,
        "operation_id": operation_id,
        "body": body,
    }

    parent_op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_offboarding",
        "operation_kind": "workflow",
        "request_payload": request_payload,
        "target_entity_id": user_id if isinstance(user_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(parent_op)
    _save("operations.json", ops)

    # status/cancel refer to existing workflow op
    if action in ("status", "cancel"):
        if not isinstance(parent_lookup, str) or not parent_lookup:
            parent_op["status"] = "failed"
            parent_op["error_code"] = "workflow.validation_failed"
            parent_op["error_message"] = "operation_id is required for status/cancel"
            parent_op["finished_at"] = _now()
            parent_op["updated_at"] = parent_op["finished_at"]
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "operation_id is required for status/cancel")

        existing = next((o for o in ops if isinstance(o, dict) and o.get("id") == parent_lookup and o.get("tenant_id") == tenant_id and o.get("tool_name") == "manage_offboarding"), None)
        if not existing:
            parent_op["status"] = "failed"
            parent_op["error_code"] = "workflow.not_found"
            parent_op["error_message"] = "Offboarding workflow operation not found"
            parent_op["finished_at"] = _now()
            parent_op["updated_at"] = parent_op["finished_at"]
            _save("operations.json", ops)
            return _err("NOT_FOUND", "Offboarding workflow operation not found")

        if action == "status":
            # children linked via request_payload.parent_operation_id
            children = [o for o in ops if isinstance(o, dict) and o.get("tenant_id") == tenant_id and isinstance(o.get("request_payload"), dict) and o["request_payload"].get("parent_operation_id") == existing.get("id")]
            parent_op["status"] = "succeeded"
            parent_op["response_payload"] = {"workflow": existing, "children": children}
            parent_op["finished_at"] = _now()
            parent_op["updated_at"] = parent_op["finished_at"]
            _save("operations.json", ops)
            return {"operation": parent_op, "result": parent_op["response_payload"]}

        # cancel
        # allowed transitions for operations: queued->cancelled, running->cancelled, partial->cancelled
        if existing.get("status") in ("succeeded", "cancelled"):
            parent_op["status"] = "succeeded"
            parent_op["response_payload"] = {"workflow": existing, "idempotent": True}
            parent_op["finished_at"] = _now()
            parent_op["updated_at"] = parent_op["finished_at"]
            _save("operations.json", ops)
            return {"operation": parent_op, "result": parent_op["response_payload"]}

        if existing.get("status") not in ("queued", "running", "partial"):
            parent_op["status"] = "failed"
            parent_op["error_code"] = "workflow.invalid_transition"
            parent_op["error_message"] = "Workflow is not in a cancellable state"
            parent_op["finished_at"] = _now()
            parent_op["updated_at"] = parent_op["finished_at"]
            _save("operations.json", ops)
            return _err("INVALID_TRANSITION", "Workflow is not in a cancellable state")

        existing["status"] = "cancelled"
        existing["updated_at"] = _now()
        existing["finished_at"] = existing["updated_at"]
        _save("operations.json", ops)

        parent_op["status"] = "succeeded"
        parent_op["response_payload"] = {"workflow": existing}
        parent_op["finished_at"] = _now()
        parent_op["updated_at"] = parent_op["finished_at"]
        _save("operations.json", ops)
        return {"operation": parent_op, "result": parent_op["response_payload"]}

    # start
    u = _find_user(user_id)
    if not u:
        parent_op["status"] = "failed"
        parent_op["error_code"] = "graph.user_not_found"
        parent_op["error_message"] = "User entity not found for tenant"
        parent_op["finished_at"] = _now()
        parent_op["updated_at"] = parent_op["finished_at"]
        _save("operations.json", ops)
        return _err("NOT_FOUND", "User entity not found for tenant")

    opts = body or {}
    disable_account = bool(opts.get("disable_account", True))
    revoke_sessions = bool(opts.get("revoke_sessions", True))
    remove_from_groups = bool(opts.get("remove_from_groups", False))
    transfer_to_user_id = opts.get("transfer_to_user_id")
    if transfer_to_user_id is not None and not isinstance(transfer_to_user_id, str):
        parent_op["status"] = "failed"
        parent_op["error_code"] = "workflow.validation_failed"
        parent_op["error_message"] = "body.transfer_to_user_id must be a string"
        parent_op["finished_at"] = _now()
        parent_op["updated_at"] = parent_op["finished_at"]
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", "body.transfer_to_user_id must be a string")

    # transition parent to running
    parent_op["status"] = "running"
    parent_op["attempt_count"] = 1
    parent_op["started_at"] = _now()
    parent_op["updated_at"] = parent_op["started_at"]
    _save("operations.json", ops)

    children = []
    results = {"disable_account": None, "revoke_sessions": None, "remove_from_groups": None, "transfer": None}

    # Create child ops per business rule with parent_operation_id
    if disable_account:
        child = _make_op("manage_user_settings", "update", {"action": "disable", "user_id": user_id}, target_entity_id=user_id, upstream_provider="microsoft_graph", parent_operation_id=parent_op["id"])
        _append_op(child)
        children.append(child)

        def _do():
            u["enabled"] = False
            u["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return {"user_id": user_id, "enabled": False}

        st, res = _run_child(child, _do, upstream_cost=1)
        results["disable_account"] = {"status": st, "result": res}

    if revoke_sessions:
        child = _make_op("dynamicendpoints m365 assistant", "workflow", {"provider": "microsoft_graph", "method": "POST", "path": "/v1.0/users/{id}/revokeSignInSessions", "user_id": user_id}, target_entity_id=user_id, upstream_provider="microsoft_graph", parent_operation_id=parent_op["id"])
        _append_op(child)
        children.append(child)

        def _do():
            # no upstream; just record intent in user properties
            p0 = u.get("properties") if isinstance(u.get("properties"), dict) else {}
            p0["sessions_revoked_at"] = _now()
            u["properties"] = p0
            u["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return {"user_id": user_id, "sessions_revoked_at": p0["sessions_revoked_at"]}

        st, res = _run_child(child, _do, upstream_cost=1)
        results["revoke_sessions"] = {"status": st, "result": res}

    if remove_from_groups:
        child = _make_op("manage_security_groups", "update", {"action": "remove_member_all_groups", "member_entity_id": user_id}, target_entity_id=user_id, upstream_provider="microsoft_graph", parent_operation_id=parent_op["id"])
        _append_op(child)
        children.append(child)

        def _do():
            # remove memberships: active->removed (allowed); preserve errors
            changed = 0
            for m in mems:
                if not isinstance(m, dict):
                    continue
                if m.get("tenant_id") != tenant_id:
                    continue
                if m.get("member_entity_id") != user_id:
                    continue
                if m.get("status") == "active":
                    m["status"] = "removed"
                    m["updated_at"] = _now()
                    changed += 1
            if changed == 0:
                return {"removed_memberships": 0}
            _save("group_memberships.json", mems)
            return {"removed_memberships": changed}

        st, res = _run_child(child, _do, upstream_cost=1)
        results["remove_from_groups"] = {"status": st, "result": res}

    if transfer_to_user_id:
        child = _make_op("manage_offboarding", "workflow", {"action": "transfer", "from_user_id": user_id, "to_user_id": transfer_to_user_id}, target_entity_id=user_id, upstream_provider="other", parent_operation_id=parent_op["id"])
        _append_op(child)
        children.append(child)

        def _do():
            # Validate target exists
            tgt = _find_user(transfer_to_user_id)
            if not tgt:
                return _err("NOT_FOUND", "transfer_to_user_id user not found")
            # record transfer intent
            p0 = u.get("properties") if isinstance(u.get("properties"), dict) else {}
            p0["transfer_to_user_id"] = transfer_to_user_id
            p0["transfer_requested_at"] = _now()
            u["properties"] = p0
            u["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return {"from_user_id": user_id, "to_user_id": transfer_to_user_id}

        st, res = _run_child(child, _do, upstream_cost=1)
        results["transfer"] = {"status": st, "result": res}

    # Finalize parent status: partial if any child fails and at least one succeeds
    succ = sum(1 for v in results.values() if isinstance(v, dict) and v.get("status") == "succeeded")
    fail = sum(1 for v in results.values() if isinstance(v, dict) and v.get("status") == "failed")
    if succ > 0 and fail > 0:
        parent_op["status"] = "partial"
    elif fail > 0 and succ == 0:
        parent_op["status"] = "failed"
        parent_op["error_code"] = "workflow.all_children_failed"
        parent_op["error_message"] = "All offboarding steps failed"
    else:
        parent_op["status"] = "succeeded"

    parent_op["response_payload"] = {"parent_operation_id": parent_op["id"], "children": [c.get("id") for c in children], "results": results}
    parent_op["upstream_request_count"] = len(children)
    parent_op["finished_at"] = _now()
    parent_op["updated_at"] = parent_op["finished_at"]
    _save("operations.json", ops)

    return {"operation": parent_op, "result": parent_op["response_payload"]}

def manage_sharepoint_sites(tenant_id, action, site_id=None, principal_entity_id=None, permission_level=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    def _validate_body(b):
        if b is None:
            return True, None
        if not isinstance(b, dict):
            return False, "body must be an object"
        allowed = {"display_name", "principal_name", "enabled", "properties"}
        for k in b.keys():
            if k not in allowed:
                return False, f"body contains unknown field '{k}'"
        if "display_name" in b and b["display_name"] is not None and not isinstance(b["display_name"], str):
            return False, "body.display_name must be a string"
        if "principal_name" in b and b["principal_name"] is not None and not isinstance(b["principal_name"], str):
            return False, "body.principal_name must be a string"
        if "enabled" in b and b["enabled"] is not None and not isinstance(b["enabled"], bool):
            return False, "body.enabled must be a boolean"
        if "properties" in b and b["properties"] is not None and not isinstance(b["properties"], dict):
            return False, "body.properties must be an object"
        return True, None

    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if action not in ("create", "update", "delete", "get", "list", "grant_permission", "revoke_permission", "list_permissions"):
        return _err("VALIDATION_ERROR", "action must be a supported value")
    ok, msg = _validate_body(body)
    if not ok:
        return _err("VALIDATION_ERROR", msg)
    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        for k in filters.keys():
            if k not in ("status", "q", "external_id"):
                return _err("VALIDATION_ERROR", f"filters contains unknown field '{k}'")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("active", "pending", "deleted", "error"):
            return _err("VALIDATION_ERROR", "filters.status must be one of active, pending, deleted, error")
        if "q" in filters and filters["q"] is not None and not isinstance(filters["q"], (str, int, float, bool)):
            return _err("VALIDATION_ERROR", "filters.q must be a string")
        if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
            return _err("VALIDATION_ERROR", "filters.external_id must be a string")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"):
        return _err("VALIDATION_ERROR", "sort must be one of created_at, -created_at, updated_at, -updated_at, display_name, -display_name")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")

    op_id = _new_id("m365_opr_", ops)
    op_now = _now()
    kind = "read" if action == "get" else ("search" if action == "list" or action == "list_permissions" else ("delete" if action == "delete" else "update"))
    upstream_cost = 1
    rate_limited = not _rate_limit_allows(tenant_row, ops, upstream_cost)

    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_sharepoint_sites",
        "operation_kind": kind,
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "site_id": site_id,
            "principal_entity_id": principal_entity_id,
            "permission_level": permission_level,
            "body": body,
            "filters": filters,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        },
        "target_entity_id": site_id if isinstance(site_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": bool(rate_limited),
        "upstream_provider": "sharepoint",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": op_now,
        "updated_at": op_now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = 1
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(api_code, msg, err_code=None):
        op_row["status"] = "failed"
        op_row["error_code"] = err_code or api_code
        op_row["error_message"] = msg
        op_row["upstream_request_count"] = 1
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err(api_code, msg, operation_id=op_id)

    def _find_site(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("id") == eid and e.get("tenant_id") == tenant_id and e.get("entity_type") == "sharepoint_site"), None)

    if action == "list":
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "sharepoint_site"]
        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("q") is not None:
            q = str(f.get("q")).lower()
            rows = [e for e in rows if any(isinstance(e.get(k), str) and q in e.get(k).lower() for k in ("display_name", "principal_name", "external_id"))]
        rev = sort.startswith("-")
        field = sort[1:] if rev else sort
        rows.sort(key=lambda e: e.get(field) or "", reverse=rev)
        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        return _finish_success({"items": page, "total": total, "has_more": next_off < total, "next_cursor": _encode_cursor(next_off) if next_off < total else None})

    if action == "get":
        s = _find_site(site_id)
        if not s:
            return _finish_error("NOT_FOUND", "SharePoint site not found")
        return _finish_success({"site": s})

    if action == "create":
        b = body or {}
        if not b:
            return _finish_error("VALIDATION_ERROR", "body is required for create")
        ext = None
        props = b.get("properties") if isinstance(b.get("properties"), dict) else {}
        if isinstance(props.get("external_id"), str) and props.get("external_id"):
            ext = props.get("external_id")
        if not ext:
            ext = f"Site:{uuid.uuid4().hex}"
        # unique(tenant_id, entity_type, external_id)
        for e in ents:
            if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "sharepoint_site" and e.get("external_id") == ext:
                return _finish_success({"site": e, "idempotent": True})
        ent = {
            "id": _new_id("m365_ent_", ents),
            "tenant_id": tenant_id,
            "entity_type": "sharepoint_site",
            "external_id": ext,
            "display_name": b.get("display_name"),
            "principal_name": b.get("principal_name"),
            "mail": None,
            "enabled": None,  # not applicable by constraints
            "status": "active",
            "properties": props if props else None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        ents.append(ent)
        _save("directory_entities.json", ents)
        op_row["target_entity_id"] = ent["id"]
        _save("operations.json", ops)
        return _finish_success({"site": ent})

    if action == "update":
        s = _find_site(site_id)
        if not s:
            return _finish_error("NOT_FOUND", "SharePoint site not found")
        b = body or {}
        if "display_name" in b:
            s["display_name"] = b.get("display_name")
        if "principal_name" in b:
            s["principal_name"] = b.get("principal_name")
        if "properties" in b:
            p0 = s.get("properties") if isinstance(s.get("properties"), dict) else {}
            p0.update(b.get("properties") or {})
            s["properties"] = p0
        if "enabled" in b and b.get("enabled") is not None:
            return _finish_error("VALIDATION_ERROR", "enabled may be non-null only for user/device/intune_device_* entity types")
        s["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"site": s})

    if action == "delete":
        s = _find_site(site_id)
        if not s:
            return _finish_error("NOT_FOUND", "SharePoint site not found")
        if s.get("status") == "deleted":
            return _finish_success({"site": s, "idempotent": True})
        if s.get("status") not in ("active", "pending", "error"):
            return _finish_error("INVALID_TRANSITION", "Invalid site status transition to deleted")
        s["status"] = "deleted"
        s["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"site": s})

    # permissions are stored in site.properties.permissions (list)
    s = _find_site(site_id)
    if not s:
        return _finish_error("NOT_FOUND", "SharePoint site not found")
    if action in ("grant_permission", "revoke_permission", "list_permissions"):
        if action != "list_permissions":
            if not isinstance(principal_entity_id, str) or not principal_entity_id:
                return _finish_error("VALIDATION_ERROR", "principal_entity_id is required")
            if permission_level not in ("read", "edit", "owner", "full_control"):
                return _finish_error("VALIDATION_ERROR", "permission_level must be one of read, edit, owner, full_control")
        p0 = s.get("properties") if isinstance(s.get("properties"), dict) else {}
        perms = p0.get("permissions")
        if not isinstance(perms, list):
            perms = []
        if action == "list_permissions":
            return _finish_success({"site_id": s["id"], "permissions": perms})
        if action == "grant_permission":
            found = False
            for r in perms:
                if isinstance(r, dict) and r.get("principal_entity_id") == principal_entity_id:
                    r["permission_level"] = permission_level
                    r["updated_at"] = _now()
                    found = True
            if not found:
                perms.append({"principal_entity_id": principal_entity_id, "permission_level": permission_level, "created_at": _now(), "updated_at": _now()})
        if action == "revoke_permission":
            before = len(perms)
            perms = [r for r in perms if not (isinstance(r, dict) and r.get("principal_entity_id") == principal_entity_id)]
            if len(perms) == before:
                return _finish_error("NOT_FOUND", "Permission entry not found to revoke")
        p0["permissions"] = perms
        s["properties"] = p0
        s["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"site": s, "permissions": perms})

    return _finish_error("VALIDATION_ERROR", "Unhandled action")

