        op["rate_limited"] = bool(rate_limited_flag)
        op["updated_at"] = now
        _save("operations.json", ops)

        op["attempt_count"] = 1
        op["status"] = status
        op["error_code"] = error_code
        op["error_message"] = error_message
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", ops)
        return op, True

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must be a string matching ^m365_tnt_[0-9A-Z]{18,}$")
    allowed = {"list_roles","get_role","assign_role_member","remove_role_member","list_role_members","list_role_assignments"}
    if action not in allowed:
        return _err("VALIDATION_ERROR", "action must be one of the supported role actions", allowed=sorted(allowed))
    if response_format is not None and response_format not in ("json","text","table","raw"):
        return _err("VALIDATION_ERROR", "response_format must be one of: json, text, table, raw")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    off = _parse_cursor(cursor)
    if cursor is not None and off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    for nm, val in (("role_entity_id", role_entity_id), ("member_entity_id", member_entity_id)):
        if val is not None:
            if not isinstance(val, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", val):
                return _err("VALIDATION_ERROR", f"{nm} must be a string matching ^m365_ent_[0-9A-Z]{{18,}}$")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active", tenant_status=tenant.get("status"))

    entities = _load("directory_entities.json")
    memberships = _load("group_memberships.json")
    ops = _load("operations.json")

    def _get_entity(ent_id):
        return next((e for e in entities if e.get("id") == ent_id and e.get("tenant_id") == tenant_id), None)

    def _resolve_role():
        if role_entity_id:
            e = _get_entity(role_entity_id)
            if not e:
                return None, _err("NOT_FOUND", "role_entity_id not found for tenant", role_entity_id=role_entity_id)
            if e.get("entity_type") != "azuread_role":
                return None, _err("VALIDATION_ERROR", "role_entity_id must reference an azuread_role directory entity")
            return e, None
        if external_role_id:
            if not isinstance(external_role_id, str) or not external_role_id.strip():
                return None, _err("VALIDATION_ERROR", "external_role_id must be a non-empty string")
            e = next((x for x in entities if x.get("tenant_id") == tenant_id and x.get("entity_type") == "azuread_role" and x.get("external_id") == external_role_id), None)
            if e:
                return e, None
            return None, None
        return None, None

    def _resolve_member():
        if member_entity_id:
            e = _get_entity(member_entity_id)
            if not e:
                return None, _err("NOT_FOUND", "member_entity_id not found for tenant", member_entity_id=member_entity_id)
            return e, None
        if external_member_id:
            if not isinstance(external_member_id, str) or not external_member_id.strip():
                return None, _err("VALIDATION_ERROR", "external_member_id must be a non-empty string")
            e = next((x for x in entities if x.get("tenant_id") == tenant_id and x.get("external_id") == external_member_id), None)
            if e:
                return e, None
            return None, None
        return None, None

    role_ent, role_err = _resolve_role()
    member_ent, mem_err = _resolve_member()

    req_payload = {
        "tenant_id": tenant_id, "action": action,
        "role_entity_id": role_entity_id, "external_role_id": external_role_id,
        "member_entity_id": member_entity_id, "external_member_id": external_member_id,
        "limit": limit, "cursor": cursor
    }
    target_entity_id = role_ent["id"] if role_ent else None

    if role_err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, role_err["error"]["code"], role_err["error"]["message"], target_entity_id=target_entity_id)
        return {**role_err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}
    if mem_err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, mem_err["error"]["code"], mem_err["error"]["message"], target_entity_id=target_entity_id)
        return {**mem_err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    # validate action requirements
    if action in {"get_role","assign_role_member","remove_role_member","list_role_members"} and not (role_ent or external_role_id):
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, "VALIDATION_ERROR", "role_entity_id or external_role_id is required", target_entity_id=target_entity_id)
        return {"error": {"code": "VALIDATION_ERROR", "message": "role_entity_id or external_role_id is required"}, "operation": op, "latency_ms": int((time.time()-t0)*1000)}
    if action in {"assign_role_member","remove_role_member"} and not (member_ent or external_member_id):
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, "VALIDATION_ERROR", "member_entity_id or external_member_id is required", target_entity_id=target_entity_id)
        return {"error": {"code": "VALIDATION_ERROR", "message": "member_entity_id or external_member_id is required"}, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    # upstream request count
    upstream_count = 1 if action.startswith("list_") or action.startswith("get_") else 2

    err = None
    result = None
    status = "succeeded"

    if action == "list_roles":
        rows = [e for e in entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "azuread_role" and e.get("status") != "deleted"]
        rows.sort(key=lambda r: (r.get("display_name") or "", r.get("id") or ""))
        lim = limit or 50
        start = off or 0
        page = rows[start:start+lim]
        next_off = start + lim
        has_more = next_off < len(rows)
        result = {"roles": page, "total": len(rows), "has_more": has_more, "next_cursor": (f"offset:{next_off}" if has_more else None)}
    elif action == "get_role":
        if not role_ent:
            err = _err("NOT_FOUND", "role not found in catalog (external_role_id not indexed)", external_role_id=external_role_id)
        else:
            result = {"role": role_ent}
    elif action == "list_role_members":
        if not role_ent:
            err = _err("NOT_FOUND", "role not found", external_role_id=external_role_id)
        else:
            edges = [m for m in memberships if m.get("tenant_id")==tenant_id and m.get("container_entity_id")==role_ent["id"] and m.get("membership_type")=="role_member" and m.get("status")=="active"]
            member_ids = [m.get("member_entity_id") for m in edges]
            mems = [e for e in entities if e.get("id") in member_ids]
            mems.sort(key=lambda r: (r.get("display_name") or "", r.get("id") or ""))
            lim = limit or 50
            start = off or 0
            page = mems[start:start+lim]
            next_off = start + lim
            has_more = next_off < len(mems)
            result = {"members": page, "total": len(mems), "has_more": has_more, "next_cursor": (f"offset:{next_off}" if has_more else None)}
    elif action == "list_role_assignments":
        edges = [m for m in memberships if m.get("tenant_id")==tenant_id and m.get("membership_type")=="role_member" and m.get("status")=="active"]
        # join minimal view
        out = []
        ent_by_id = {e.get("id"): e for e in entities if e.get("tenant_id")==tenant_id}
        for m in edges:
            role_e = ent_by_id.get(m.get("container_entity_id"))
            mem_e = ent_by_id.get(m.get("member_entity_id"))
            if not role_e or role_e.get("entity_type") != "azuread_role":
                continue
            out.append({"membership": m, "role": role_e, "member": mem_e})
        out.sort(key=lambda r: ((r["role"].get("display_name") or ""), (r["member"].get("display_name") or "")))
        lim = limit or 50
        start = off or 0
        page = out[start:start+lim]
        next_off = start + lim
        has_more = next_off < len(out)
        result = {"assignments": page, "total": len(out), "has_more": has_more, "next_cursor": (f"offset:{next_off}" if has_more else None)}
    elif action in {"assign_role_member","remove_role_member"}:
        if not role_ent:
            err = _err("NOT_FOUND", "role not found", external_role_id=external_role_id)
        else:
            # must represent as group_memberships role_member and container entity_type azuread_role
            if role_ent.get("entity_type") != "azuread_role":
                err = _err("VALIDATION_ERROR", "role container must be an azuread_role")
            else:
                if not member_ent:
                    err = _err("NOT_FOUND", "member not found in catalog (external_member_id not indexed)", external_member_id=external_member_id)
                else:
                    # same tenant constraint
                    if member_ent.get("tenant_id") != tenant_id:
                        err = _err("VALIDATION_ERROR", "member_entity_id must belong to same tenant_id")
                    else:
                        existing = next((m for m in memberships
                                         if m.get("tenant_id")==tenant_id and m.get("container_entity_id")==role_ent["id"]
                                         and m.get("member_entity_id")==member_ent["id"] and m.get("membership_type")=="role_member"), None)
                        if action == "assign_role_member":
                            if existing and existing.get("status") == "active":
                                err = _err("CONFLICT", "role assignment already exists", membership_id=existing.get("id"))
                            else:
                                if not existing:
                                    m = {
                                        "id": _new_id("m365_mem_"),
                                        "tenant_id": tenant_id,
                                        "container_entity_id": role_ent["id"],
                                        "member_entity_id": member_ent["id"],
                                        "membership_type": "role_member",
                                        "status": "pending",
                                        "source": "managed",
                                        "created_at": now,
                                        "updated_at": now
                                    }
                                    memberships.append(m)
                                    existing = m
                                # transition pending->active (simulate upstream confirmation)
                                if existing.get("status") not in ("pending","error"):
                                    err = _err("INVALID_TRANSITION", "cannot assign role from current membership status", current_status=existing.get("status"))
                                else:
                                    existing["status"] = "active"
                                    existing["updated_at"] = now
                                    _save("group_memberships.json", memberships)
                                    result = {"assignment": existing, "role": role_ent, "member": member_ent}
                        else:  # remove_role_member
                            if not existing or existing.get("status") == "removed":
                                err = _err("NOT_FOUND", "role assignment not found", role_entity_id=role_ent.get("id"), member_entity_id=member_ent.get("id"))
                            elif existing.get("status") != "active":
                                err = _err("INVALID_TRANSITION", "cannot remove role member unless membership is active", current_status=existing.get("status"))
                            else:
                                existing["status"] = "removed"
                                existing["updated_at"] = now
                                _save("group_memberships.json", memberships)
                                result = {"removed": True, "assignment": existing}

    if err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, err["error"]["code"], err["error"]["message"], target_entity_id=target_entity_id)
        return {**err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    op, transitioned = _record_op(ops, tenant, req_payload, status, upstream_count, False, None, None, target_entity_id=target_entity_id)
    latency_ms = int((time.time()-t0)*1000)
    if not transitioned:
        return {"error": {"code": "RATE_LIMIT", "message": "tenant rate limit exceeded; operation queued", "tenant_rate_limit_per_minute": tenant.get("rate_limit_per_minute")}, "operation": op, "latency_ms": latency_ms}
    op["response_payload"] = result
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", ops)
    return {"operation": op, "result": result, "latency_ms": latency_ms}

def manage_azuread_apps(tenant_id, action, app_entity_id=None, external_app_id=None, response_format=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        if c.startswith("offset:"):
            try:
                return int(c.split(":", 1)[1])
            except Exception:
                return None
        try:
            return int(c)
        except Exception:
            return None

    def _record_op(ops, tenant_row, req_payload, status, upstream_count, rate_limited_flag, error_code=None, error_message=None, target_entity_id=None):
        op_id = _new_id("m365_op_")
        if action.startswith("list_") or action.startswith("get_"):
            kind = "read"
        elif action.startswith("create_") or action in ("add_password","add_certificate"):
            kind = "create"
        elif action.startswith("delete_") or action in ("remove_password","remove_certificate"):
            kind = "delete"
        else:
            kind = "update"
        op = {
            "id": op_id,
            "tenant_id": tenant_row["id"],
            "tool_name": "manage_azuread_apps",
            "operation_kind": kind,
            "request_payload": req_payload,
            "target_entity_id": target_entity_id,
            "status": "queued",
            "attempt_count": 0,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "microsoft_graph",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)

        one_min_ago = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)).isoformat() + "Z"
        used = 0
        for r in ops:
            try:
                if r.get("tenant_id") != tenant_row["id"]:
                    continue
                st = r.get("started_at")
                if st and st > one_min_ago:
                    used += int(r.get("upstream_request_count") or 0)
            except Exception:
                continue
        budget = int(tenant_row.get("rate_limit_per_minute") or 60)
        if used + int(upstream_count) > budget:
            op["rate_limited"] = True
            op["status"] = "queued"
            op["updated_at"] = now
            _save("operations.json", ops)
            return op, False

        op["status"] = "running"
        op["started_at"] = now
        op["upstream_request_count"] = int(upstream_count)
        op["rate_limited"] = bool(rate_limited_flag)
        op["updated_at"] = now
        _save("operations.json", ops)

        op["attempt_count"] = 1
        op["status"] = status
        op["error_code"] = error_code
        op["error_message"] = error_message
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", ops)
        return op, True

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must be a string matching ^m365_tnt_[0-9A-Z]{18,}$")
    allowed = {"list_apps","get_app","create_app","update_app","delete_app","add_password","remove_password","add_certificate","remove_certificate","set_permissions"}
    if action not in allowed:
        return _err("VALIDATION_ERROR", "action must be one of the supported app actions", allowed=sorted(allowed))
    if response_format is not None and response_format not in ("json","text","table","raw"):
        return _err("VALIDATION_ERROR", "response_format must be one of: json, text, table, raw")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    off = _parse_cursor(cursor)
    if cursor is not None and off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    if app_entity_id is not None:
        if not isinstance(app_entity_id, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", app_entity_id):
            return _err("VALIDATION_ERROR", "app_entity_id must be a string matching ^m365_ent_[0-9A-Z]{18,}$")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active", tenant_status=tenant.get("status"))

    entities = _load("directory_entities.json")
    ops = _load("operations.json")

    def _get_app():
        if app_entity_id:
            e = next((x for x in entities if x.get("tenant_id")==tenant_id and x.get("id")==app_entity_id), None)
            if not e:
                return None, _err("NOT_FOUND", "app_entity_id not found for tenant", app_entity_id=app_entity_id)
            if e.get("entity_type") != "azuread_app_registration":
                return None, _err("VALIDATION_ERROR", "app_entity_id must reference an azuread_app_registration directory entity")
            return e, None
        if external_app_id:
            if not isinstance(external_app_id, str) or not external_app_id.strip():
                return None, _err("VALIDATION_ERROR", "external_app_id must be a non-empty string")
            e = next((x for x in entities if x.get("tenant_id")==tenant_id and x.get("entity_type")=="azuread_app_registration" and x.get("external_id")==external_app_id), None)
            return e, None
        return None, None

    app_ent, app_err = _get_app()
    req_payload = {"tenant_id": tenant_id, "action": action, "app_entity_id": app_entity_id, "external_app_id": external_app_id, "limit": limit, "cursor": cursor, "body": body}
    target_entity_id = app_ent["id"] if app_ent else None

    if app_err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, app_err["error"]["code"], app_err["error"]["message"], target_entity_id)
        return {**app_err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    if action in {"get_app","update_app","delete_app","add_password","remove_password","add_certificate","remove_certificate","set_permissions"} and not (app_ent or external_app_id):
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, "VALIDATION_ERROR", "app_entity_id or external_app_id is required", target_entity_id)
        return {"error": {"code": "VALIDATION_ERROR", "message": "app_entity_id or external_app_id is required"}, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    # Ensure properties container
    def _ensure_props(ent):
        if ent.get("properties") is None or not isinstance(ent.get("properties"), dict):
            ent["properties"] = {}
        ent["properties"].setdefault("redirect_uris", [])
        ent["properties"].setdefault("identifier_uris", [])
        ent["properties"].setdefault("sign_in_audience", None)
        ent["properties"].setdefault("api_permissions", [])
        ent["properties"].setdefault("password_credentials", [])  # list of dicts with keyId
        ent["properties"].setdefault("certificates", [])  # list of dicts with keyId

    upstream_count = 1 if action.startswith("list_") or action.startswith("get_") else 2

    err = None
    result = None
    status = "succeeded"

    if action == "list_apps":
        rows = [e for e in entities if e.get("tenant_id")==tenant_id and e.get("entity_type")=="azuread_app_registration" and e.get("status") != "deleted"]
        rows.sort(key=lambda r: (r.get("display_name") or "", r.get("id") or ""))
        lim = limit or 50
        start = off or 0
        page = rows[start:start+lim]
        next_off = start + lim
        has_more = next_off < len(rows)
        result = {"apps": page, "total": len(rows), "has_more": has_more, "next_cursor": (f"offset:{next_off}" if has_more else None)}
    elif action == "get_app":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found in catalog (external_app_id not indexed)", external_app_id=external_app_id)
        else:
            _ensure_props(app_ent)
            result = {"app": app_ent}
    elif action == "create_app":
        if body is None or not isinstance(body.get("display_name"), str) or not body.get("display_name").strip():
            err = _err("VALIDATION_ERROR", "body.display_name is required for create_app")
        else:
            new_external = external_app_id or _new_id("aad_app_")
            if any(e.get("tenant_id")==tenant_id and e.get("entity_type")=="azuread_app_registration" and e.get("external_id")==new_external for e in entities):
                err = _err("CONFLICT", "app with external_app_id already exists", external_app_id=new_external)
            else:
                ent = {
                    "id": _new_id("m365_ent_"),
                    "tenant_id": tenant_id,
                    "entity_type": "azuread_app_registration",
                    "external_id": new_external,
                    "display_name": body.get("display_name"),
                    "principal_name": body.get("principal_name") if isinstance(body.get("principal_name"), str) else None,
                    "mail": None,
                    "enabled": None,
                    "status": "active",
                    "properties": {},
                    "created_at": now,
                    "updated_at": now
                }
                _ensure_props(ent)
                if "redirect_uris" in body:
                    if not isinstance(body["redirect_uris"], list) or any(not isinstance(x, str) for x in body["redirect_uris"]):
                        err = _err("VALIDATION_ERROR", "body.redirect_uris must be an array of strings")
                    else:
                        ent["properties"]["redirect_uris"] = body["redirect_uris"]
                if not err and "identifier_uris" in body:
                    if not isinstance(body["identifier_uris"], list) or any(not isinstance(x, str) for x in body["identifier_uris"]):
                        err = _err("VALIDATION_ERROR", "body.identifier_uris must be an array of strings")
                    else:
                        ent["properties"]["identifier_uris"] = body["identifier_uris"]
                if not err and "sign_in_audience" in body:
                    if body["sign_in_audience"] is not None and not isinstance(body["sign_in_audience"], str):
                        err = _err("VALIDATION_ERROR", "body.sign_in_audience must be a string")
                    else:
                        ent["properties"]["sign_in_audience"] = body["sign_in_audience"]
                if not err:
                    entities.append(ent)
                    _save("directory_entities.json", entities)
                    result = {"app": ent}
                    target_entity_id = ent["id"]
    elif action == "update_app":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", app_entity_id=app_entity_id, external_app_id=external_app_id)
        elif app_ent.get("status") == "deleted":
            err = _err("INVALID_TRANSITION", "cannot update a deleted app")
        else:
            _ensure_props(app_ent)
            if body:
                if "display_name" in body:
                    if body["display_name"] is not None and not isinstance(body["display_name"], str):
                        err = _err("VALIDATION_ERROR", "body.display_name must be a string")
                    else:
                        app_ent["display_name"] = body["display_name"]
                if not err and "redirect_uris" in body:
                    if body["redirect_uris"] is not None and (not isinstance(body["redirect_uris"], list) or any(not isinstance(x, str) for x in body["redirect_uris"])):
                        err = _err("VALIDATION_ERROR", "body.redirect_uris must be an array of strings")
                    else:
                        app_ent["properties"]["redirect_uris"] = body["redirect_uris"] or []
                if not err and "identifier_uris" in body:
                    if body["identifier_uris"] is not None and (not isinstance(body["identifier_uris"], list) or any(not isinstance(x, str) for x in body["identifier_uris"])):
                        err = _err("VALIDATION_ERROR", "body.identifier_uris must be an array of strings")
                    else:
                        app_ent["properties"]["identifier_uris"] = body["identifier_uris"] or []
                if not err and "sign_in_audience" in body:
                    if body["sign_in_audience"] is not None and not isinstance(body["sign_in_audience"], str):
                        err = _err("VALIDATION_ERROR", "body.sign_in_audience must be a string")
                    else:
                        app_ent["properties"]["sign_in_audience"] = body["sign_in_audience"]
            if not err:
                app_ent["updated_at"] = now
                _save("directory_entities.json", entities)
                result = {"app": app_ent}
    elif action == "delete_app":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", app_entity_id=app_entity_id, external_app_id=external_app_id)
        else:
            if app_ent.get("status") == "deleted":
                err = _err("NOT_FOUND", "app already deleted", app_entity_id=app_ent.get("id"))
            else:
                app_ent["status"] = "deleted"
                app_ent["updated_at"] = now
                _save("directory_entities.json", entities)
                result = {"deleted": True, "app": app_ent}
    elif action == "add_password":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", external_app_id=external_app_id)
        else:
            pc = body.get("password_credential") if isinstance(body, dict) else None
            if not isinstance(pc, dict):
                err = _err("VALIDATION_ERROR", "body.password_credential (object) is required for add_password")
            else:
                _ensure_props(app_ent)
                key_id = pc.get("keyId") or pc.get("key_id") or _new_id("pwd_")
                creds = app_ent["properties"].get("password_credentials") or []
                if any(isinstance(c, dict) and (c.get("keyId")==key_id or c.get("key_id")==key_id) for c in creds):
                    err = _err("CONFLICT", "password credential with key_id already exists", key_id=key_id)
                else:
                    newc = dict(pc)
                    newc["keyId"] = key_id
                    newc.setdefault("created_at", now)
                    creds.append(newc)
                    app_ent["properties"]["password_credentials"] = creds
                    app_ent["updated_at"] = now
                    _save("directory_entities.json", entities)
                    result = {"password_credential": newc, "app": app_ent}
    elif action == "remove_password":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", external_app_id=external_app_id)
        else:
            key_id = body.get("key_id") if isinstance(body, dict) else None
            if not isinstance(key_id, str) or not key_id.strip():
                err = _err("VALIDATION_ERROR", "body.key_id is required for remove_password")
            else:
                _ensure_props(app_ent)
                creds = app_ent["properties"].get("password_credentials") or []
                before = len(creds)
                creds = [c for c in creds if not (isinstance(c, dict) and (c.get("keyId")==key_id or c.get("key_id")==key_id))]
                if len(creds) == before:
                    err = _err("NOT_FOUND", "password credential not found", key_id=key_id)
                else:
                    app_ent["properties"]["password_credentials"] = creds
                    app_ent["updated_at"] = now
                    _save("directory_entities.json", entities)
                    result = {"removed": True, "key_id": key_id}
    elif action == "add_certificate":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", external_app_id=external_app_id)
        else:
            cert = body.get("certificate") if isinstance(body, dict) else None
            if not isinstance(cert, dict):
                err = _err("VALIDATION_ERROR", "body.certificate (object) is required for add_certificate")
            else:
                _ensure_props(app_ent)
                key_id = cert.get("keyId") or cert.get("key_id") or _new_id("cert_")
                certs = app_ent["properties"].get("certificates") or []
                if any(isinstance(c, dict) and (c.get("keyId")==key_id or c.get("key_id")==key_id) for c in certs):
                    err = _err("CONFLICT", "certificate with key_id already exists", key_id=key_id)
                else:
                    newc = dict(cert)
                    newc["keyId"] = key_id
                    newc.setdefault("created_at", now)
                    certs.append(newc)
                    app_ent["properties"]["certificates"] = certs
                    app_ent["updated_at"] = now
                    _save("directory_entities.json", entities)
                    result = {"certificate": newc, "app": app_ent}
    elif action == "remove_certificate":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", external_app_id=external_app_id)
        else:
            key_id = body.get("key_id") if isinstance(body, dict) else None
            if not isinstance(key_id, str) or not key_id.strip():
                err = _err("VALIDATION_ERROR", "body.key_id is required for remove_certificate")
            else:
                _ensure_props(app_ent)
                certs = app_ent["properties"].get("certificates") or []
                before = len(certs)
                certs = [c for c in certs if not (isinstance(c, dict) and (c.get("keyId")==key_id or c.get("key_id")==key_id))]
                if len(certs) == before:
                    err = _err("NOT_FOUND", "certificate not found", key_id=key_id)
                else:
                    app_ent["properties"]["certificates"] = certs
                    app_ent["updated_at"] = now
                    _save("directory_entities.json", entities)
                    result = {"removed": True, "key_id": key_id}
    elif action == "set_permissions":
        if not app_ent:
            err = _err("NOT_FOUND", "app not found", external_app_id=external_app_id)
        else:
            perms = body.get("api_permissions") if isinstance(body, dict) else None
            if not isinstance(perms, list) or any(not isinstance(p, dict) for p in perms):
                err = _err("VALIDATION_ERROR", "body.api_permissions (array of objects) is required for set_permissions")
            else:
                _ensure_props(app_ent)
                # no-op detection -> CONFLICT (no success without effect)
                before = json.dumps(app_ent["properties"].get("api_permissions"), sort_keys=True)
                after = json.dumps(perms, sort_keys=True)
                if before == after:
                    err = _err("CONFLICT", "api_permissions already set to the same value")
                else:
                    app_ent["properties"]["api_permissions"] = perms
                    app_ent["updated_at"] = now
                    _save("directory_entities.json", entities)
                    result = {"api_permissions": perms, "app": app_ent}

    if err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, err["error"]["code"], err["error"]["message"], target_entity_id)
        return {**err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    op, transitioned = _record_op(ops, tenant, req_payload, status, upstream_count, False, None, None, target_entity_id)
    latency_ms = int((time.time()-t0)*1000)
    if not transitioned:
        return {"error": {"code": "RATE_LIMIT", "message": "tenant rate limit exceeded; operation queued", "tenant_rate_limit_per_minute": tenant.get("rate_limit_per_minute")}, "operation": op, "latency_ms": latency_ms}
    op["response_payload"] = result
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", ops)
    return {"operation": op, "result": result, "latency_ms": latency_ms}

def manage_azuread_devices(tenant_id, action, device_entity_id=None, external_device_id=None, response_format=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        if c.startswith("offset:"):
            try:
                return int(c.split(":", 1)[1])
            except Exception:
                return None
        try:
            return int(c)
        except Exception:
            return None

    def _record_op(ops, tenant_row, req_payload, status, upstream_count, rate_limited_flag, error_code=None, error_message=None, target_entity_id=None):
        op_id = _new_id("m365_op_")
        if action.startswith("list_") or action.startswith("get_"):
            kind = "read"
        elif action == "register_device":
            kind = "create"
        elif action == "delete_device":
            kind = "delete"
        else:
            kind = "update"
        op = {
            "id": op_id,
            "tenant_id": tenant_row["id"],
            "tool_name": "manage_azuread_devices",
            "operation_kind": kind,
            "request_payload": req_payload,
            "target_entity_id": target_entity_id,
            "status": "queued",
            "attempt_count": 0,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "microsoft_graph",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)

        one_min_ago = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)).isoformat() + "Z"
        used = 0
        for r in ops:
            try:
                if r.get("tenant_id") != tenant_row["id"]:
                    continue
                st = r.get("started_at")
                if st and st > one_min_ago:
                    used += int(r.get("upstream_request_count") or 0)
            except Exception:
                continue
        budget = int(tenant_row.get("rate_limit_per_minute") or 60)
        if used + int(upstream_count) > budget:
            op["rate_limited"] = True
            op["status"] = "queued"
            op["updated_at"] = now
            _save("operations.json", ops)
            return op, False

        op["status"] = "running"
        op["started_at"] = now
        op["upstream_request_count"] = int(upstream_count)
        op["rate_limited"] = bool(rate_limited_flag)
        op["updated_at"] = now
        _save("operations.json", ops)

        op["attempt_count"] = 1
        op["status"] = status
        op["error_code"] = error_code
        op["error_message"] = error_message
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", ops)
        return op, True

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must be a string matching ^m365_tnt_[0-9A-Z]{18,}$")
    allowed = {"list_devices","get_device","register_device","update_device","delete_device"}
    if action not in allowed:
        return _err("VALIDATION_ERROR", "action must be one of the supported device actions", allowed=sorted(allowed))
    if response_format is not None and response_format not in ("json","text","table","raw"):
        return _err("VALIDATION_ERROR", "response_format must be one of: json, text, table, raw")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    off = _parse_cursor(cursor)
    if cursor is not None and off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    if device_entity_id is not None:
        if not isinstance(device_entity_id, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", device_entity_id):
            return _err("VALIDATION_ERROR", "device_entity_id must be a string matching ^m365_ent_[0-9A-Z]{18,}$")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active", tenant_status=tenant.get("status"))

    entities = _load("directory_entities.json")
    ops = _load("operations.json")

    def _get_device():
        if device_entity_id:
            e = next((x for x in entities if x.get("tenant_id")==tenant_id and x.get("id")==device_entity_id), None)
            if not e:
                return None, _err("NOT_FOUND", "device_entity_id not found for tenant", device_entity_id=device_entity_id)
            if e.get("entity_type") != "device":
                return None, _err("VALIDATION_ERROR", "device_entity_id must reference a device directory entity")
            return e, None
        if external_device_id:
            if not isinstance(external_device_id, str) or not external_device_id.strip():
                return None, _err("VALIDATION_ERROR", "external_device_id must be a non-empty string")
            e = next((x for x in entities if x.get("tenant_id")==tenant_id and x.get("entity_type")=="device" and x.get("external_id")==external_device_id), None)
            return e, None
        return None, None

    dev_ent, dev_err = _get_device()
    req_payload = {"tenant_id": tenant_id, "action": action, "device_entity_id": device_entity_id, "external_device_id": external_device_id, "limit": limit, "cursor": cursor, "body": body}
    target_entity_id = dev_ent["id"] if dev_ent else None

    if dev_err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, dev_err["error"]["code"], dev_err["error"]["message"], target_entity_id)
        return {**dev_err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    if action in {"get_device","update_device","delete_device"} and not (dev_ent or external_device_id):
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, "VALIDATION_ERROR", "device_entity_id or external_device_id is required", target_entity_id)
        return {"error": {"code": "VALIDATION_ERROR", "message": "device_entity_id or external_device_id is required"}, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    # validate enabled constraint: enabled may be non-null only when entity_type in (user/device/intune devices).
    # Here entity_type is device so allowed.
    upstream_count = 1 if action.startswith("list_") or action.startswith("get_") else 2

    err = None
    result = None
    status = "succeeded"

    def _ensure_props(ent):
        if ent.get("properties") is None or not isinstance(ent.get("properties"), dict):
            ent["properties"] = {}

    if action == "list_devices":
        rows = [e for e in entities if e.get("tenant_id")==tenant_id and e.get("entity_type")=="device" and e.get("status") != "deleted"]
        rows.sort(key=lambda r: (r.get("display_name") or "", r.get("id") or ""))
        lim = limit or 50
        start = off or 0
        page = rows[start:start+lim]
        next_off = start + lim
        has_more = next_off < len(rows)
        result = {"devices": page, "total": len(rows), "has_more": has_more, "next_cursor": (f"offset:{next_off}" if has_more else None)}
    elif action == "get_device":
        if not dev_ent:
            err = _err("NOT_FOUND", "device not found in catalog (external_device_id not indexed)", external_device_id=external_device_id)
        else:
            _ensure_props(dev_ent)
            result = {"device": dev_ent}
    elif action == "register_device":
        if body is None or not isinstance(body.get("display_name"), str) or not body.get("display_name").strip():
            err = _err("VALIDATION_ERROR", "body.display_name is required for register_device")
        else:
            new_external = external_device_id or _new_id("aad_dev_")
            if any(e.get("tenant_id")==tenant_id and e.get("entity_type")=="device" and e.get("external_id")==new_external for e in entities):
                err = _err("CONFLICT", "device with external_device_id already exists", external_device_id=new_external)
            else:
                enabled = body.get("enabled") if "enabled" in body else None
                if enabled is not None and not isinstance(enabled, bool):
                    err = _err("VALIDATION_ERROR", "body.enabled must be a boolean when provided")
                else:
                    ent = {
                        "id": _new_id("m365_ent_"),
                        "tenant_id": tenant_id,
                        "entity_type": "device",
                        "external_id": new_external,
                        "display_name": body.get("display_name"),
                        "principal_name": None,
                        "mail": None,
                        "enabled": enabled,
                        "status": "active",
                        "properties": body.get("properties") if isinstance(body.get("properties"), dict) else {},
                        "created_at": now,
                        "updated_at": now
                    }
                    entities.append(ent)
                    _save("directory_entities.json", entities)
                    result = {"device": ent}
                    target_entity_id = ent["id"]
    elif action == "update_device":
        if not dev_ent:
            err = _err("NOT_FOUND", "device not found", device_entity_id=device_entity_id, external_device_id=external_device_id)
        elif dev_ent.get("status") == "deleted":
            err = _err("INVALID_TRANSITION", "cannot update a deleted device")
        else:
            _ensure_props(dev_ent)
            if body:
                if "display_name" in body:
                    if body["display_name"] is not None and not isinstance(body["display_name"], str):
                        err = _err("VALIDATION_ERROR", "body.display_name must be a string")
                    else:
                        dev_ent["display_name"] = body["display_name"]
                if not err and "enabled" in body:
                    if body["enabled"] is not None and not isinstance(body["enabled"], bool):
                        err = _err("VALIDATION_ERROR", "body.enabled must be a boolean")
                    else:
                        dev_ent["enabled"] = body["enabled"]
                if not err and "properties" in body:
                    if body["properties"] is not None and not isinstance(body["properties"], dict):
                        err = _err("VALIDATION_ERROR", "body.properties must be an object")
                    else:
                        # no-op detection
                        before = json.dumps(dev_ent.get("properties") or {}, sort_keys=True)
                        after = json.dumps(body["properties"] or {}, sort_keys=True)
                        dev_ent["properties"] = body["properties"] or {}
                        if before == after and "display_name" not in body and "enabled" not in body:
                            err = _err("CONFLICT", "no changes detected in update_device")
            if not err:
                dev_ent["updated_at"] = now
                _save("directory_entities.json", entities)
                result = {"device": dev_ent}
    elif action == "delete_device":
        if not dev_ent:
            err = _err("NOT_FOUND", "device not found", device_entity_id=device_entity_id, external_device_id=external_device_id)
        else:
            if dev_ent.get("status") == "deleted":
                err = _err("NOT_FOUND", "device already deleted", device_entity_id=dev_ent.get("id"))
            else:
                dev_ent["status"] = "deleted"
                dev_ent["updated_at"] = now
                _save("directory_entities.json", entities)
                result = {"deleted": True, "device": dev_ent}

    if err:
        op, _ = _record_op(ops, tenant, req_payload, "failed", 0, False, err["error"]["code"], err["error"]["message"], target_entity_id)
        return {**err, "operation": op, "latency_ms": int((time.time()-t0)*1000)}

    op, transitioned = _record_op(ops, tenant, req_payload, status, upstream_count, False, None, None, target_entity_id)
    latency_ms = int((time.time()-t0)*1000)
    if not transitioned:
        return {"error": {"code": "RATE_LIMIT", "message": "tenant rate limit exceeded; operation queued", "tenant_rate_limit_per_minute": tenant.get("rate_limit_per_minute")}, "operation": op, "latency_ms": latency_ms}
    op["response_payload"] = result
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", ops)
    return {"operation": op, "result": result, "latency_ms": latency_ms}

def manage_service_principals(tenant_id, action, service_principal_entity_id=None, external_service_principal_id=None, response_format=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(500):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                continue
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        return (used + max(0, int(new_upstream))) <= lim

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    allowed_actions = {
        "list_service_principals",
        "get_service_principal",
        "create_service_principal",
        "update_service_principal",
        "delete_service_principal",
        "add_password",
        "remove_password",
        "add_certificate",
        "remove_certificate",
        "set_app_role_assignments",
    }
    if action not in allowed_actions:
        return _err("VALIDATION_ERROR", "Invalid action", allowed=sorted(allowed_actions))
    if response_format is None:
        response_format = "json"
    if response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be >= 1")
        if limit > 200:
            limit = 200
    else:
        limit = 100
    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if service_principal_entity_id is not None and not re.match(r"^m365_ent_[0-9A-Z]{18,}$", str(service_principal_entity_id)):
        return _err("VALIDATION_ERROR", "service_principal_entity_id must match ^m365_ent_[0-9A-Z]{18,}$")

    tenants = _load("tenants.json")
    ents = _load("directory_entities.json")
    mems = _load("group_memberships.json")
    ops = _load("operations.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "Tenant not found")

    def _op_kind(act):
        if act == "list_service_principals":
            return "search"
        if act == "get_service_principal":
            return "read"
        if act == "create_service_principal":
            return "create"
        if act == "delete_service_principal":
            return "delete"
        return "update"

    op_id = _new_id("m365_opr_", ops)
    now = _now()
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_service_principals",
        "operation_kind": _op_kind(action),
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "service_principal_entity_id": service_principal_entity_id,
            "external_service_principal_id": external_service_principal_id,
            "response_format": response_format,
            "limit": limit,
            "cursor": cursor,
            "body": body,
        },
        "target_entity_id": service_principal_entity_id,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "microsoft_graph",
        "upstream_request_count": 0,
        "response_format": response_format,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if tenant.get("status") != "active":
        fin = _now()
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["status"] = "failed"
                o["attempt_count"] = 1
                o["started_at"] = fin
                o["finished_at"] = fin
                o["updated_at"] = fin
                o["error_code"] = "tenant_inactive"
                o["error_message"] = "Tenant is not active"
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Tenant is not active", operation_id=op_id)

    expected_upstream = 1 if action in ("get_service_principal", "update_service_principal", "delete_service_principal") else 2
    if action in ("add_password", "remove_password", "add_certificate", "remove_certificate", "set_app_role_assignments", "create_service_principal"):
        expected_upstream = 2

    if not _rate_limit_allows(tenant, ops, expected_upstream):
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["rate_limited"] = True
                o["updated_at"] = _now()
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "Tenant rate limit would be exceeded; operation delayed", operation_id=op_id)

    start = _now()
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op_id:
            o["status"] = "running"
            o["attempt_count"] = 1
            o["started_at"] = start
            o["updated_at"] = start
            o["upstream_request_count"] = expected_upstream
    _save("operations.json", ops)

    def _finish_success(payload):
        fin = _now()
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["status"] = "succeeded"
                o["response_payload"] = payload
                o["error_code"] = None
                o["error_message"] = None
                o["finished_at"] = fin
                o["updated_at"] = fin
        _save("operations.json", ops)
        return {"operation_id": op_id, "status": "succeeded", "data": payload, "latency_ms": int((time.time() - t0) * 1000)}

    def _finish_error(code, msg, norm=None):
        fin = _now()
        for o in ops:
            if isinstance(o, dict) and o.get("id") == op_id:
                o["status"] = "failed"
                o["response_payload"] = None
                o["error_code"] = norm or code
                o["error_message"] = msg
                o["finished_at"] = fin
                o["updated_at"] = fin
        _save("operations.json", ops)
        return _err(code, msg, operation_id=op_id)

    def _find_sp():
        if service_principal_entity_id:
            return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("id") == service_principal_entity_id and e.get("entity_type") == "service_principal"), None)
        if isinstance(external_service_principal_id, str) and external_service_principal_id.strip():
            return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "service_principal" and e.get("external_id") == external_service_principal_id), None)
        return None

    try:
        if action == "list_service_principals":
            rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "service_principal"]
            rows.sort(key=lambda r: _parse_dt(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)
            total = len(rows)
            page = rows[off: off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            return _finish_success({"items": page, "total": total, "limit": limit, "cursor": _encode_cursor(next_off) if has_more else None, "has_more": has_more})

        if action == "get_service_principal":
            sp = _find_sp()
            if not sp:
                return _finish_error("NOT_FOUND", "Service principal not found")
            return _finish_success(sp)

        if action == "create_service_principal":
            if body is None or not isinstance(body, dict) or not isinstance(body.get("app_id"), str) or not body.get("app_id").strip():
                return _finish_error("VALIDATION_ERROR", "body.app_id is required for create_service_principal")
            app_id = body["app_id"].strip()
            # unique(tenant, type, external_id): use app_id as external_id if no other external supplied
            ext_id = external_service_principal_id.strip() if isinstance(external_service_principal_id, str) and external_service_principal_id.strip() else f"spn:{app_id}"
            existing = next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "service_principal" and e.get("external_id") == ext_id), None)
            if existing:
                existing["principal_name"] = app_id
                if "display_name" in body:
                    existing["display_name"] = body.get("display_name")
                if "enabled" in body:
                    existing["enabled"] = body.get("enabled")
                props = existing.get("properties")
                if props is None or not isinstance(props, dict):
                    props = {}
                    existing["properties"] = props
                props["app_id"] = app_id
                existing["updated_at"] = _now()
                _save("directory_entities.json", ents)
                return _finish_success(existing)
            new_ent = {
                "id": _new_id("m365_ent_", ents),
                "tenant_id": tenant_id,
                "entity_type": "service_principal",
                "external_id": ext_id,
                "display_name": body.get("display_name"),
                "principal_name": app_id,
                "mail": None,
                "enabled": body.get("enabled"),
                "status": "active",
                "properties": {"app_id": app_id, "credentials": {"passwords": [], "certificates": []}, "app_role_assignments": []},
                "created_at": _now(),
                "updated_at": _now(),
            }
            ents.append(new_ent)
            _save("directory_entities.json", ents)
            return _finish_success(new_ent)

        if action == "update_service_principal":
            sp = _find_sp()
            if not sp:
                return _finish_error("NOT_FOUND", "Service principal not found")
            if body is None:
                body = {}
            changed = False
            if "display_name" in body:
                sp["display_name"] = body.get("display_name")
                changed = True
            if "enabled" in body:
                sp["enabled"] = body.get("enabled")
                changed = True
            if not changed:
                return _finish_error("VALIDATION_ERROR", "No updatable fields provided")
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success(sp)

        if action == "delete_service_principal":
            sp = _find_sp()
            if not sp:
                return _finish_error("NOT_FOUND", "Service principal not found")
            if sp.get("status") == "deleted":
                return _finish_success(sp)
            if sp.get("status") not in ("active", "pending", "error"):
                return _finish_error("INVALID_TRANSITION", f"Cannot delete from status '{sp.get('status')}'")
            sp["status"] = "deleted"
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success(sp)

        # credential and assignment management stored in properties
        sp = _find_sp()
        if not sp:
            return _finish_error("NOT_FOUND", "Service principal not found")
        props = sp.get("properties")
        if props is None or not isinstance(props, dict):
            props = {}
            sp["properties"] = props
        creds = props.get("credentials")
        if creds is None or not isinstance(creds, dict):
            creds = {"passwords": [], "certificates": []}
            props["credentials"] = creds

        if action == "add_password":
            pc = (body or {}).get("password_credential") or {}
            if not isinstance(pc, dict):
                return _finish_error("VALIDATION_ERROR", "body.password_credential must be an object")
            kid = pc.get("keyId") or pc.get("key_id") or f"pwd_{uuid.uuid4().hex}"
            creds["passwords"].append({"key_id": kid, "payload": pc, "added_at": _now()})
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success({"added_password": {"key_id": kid}})

        if action == "remove_password":
            kid = (body or {}).get("key_id")
            if not isinstance(kid, str) or not kid:
                return _finish_error("VALIDATION_ERROR", "body.key_id is required")
            before = len(creds.get("passwords", []))
            creds["passwords"] = [p for p in creds.get("passwords", []) if not (isinstance(p, dict) and p.get("key_id") == kid)]
            if len(creds["passwords"]) == before:
                return _finish_error("NOT_FOUND", "Password key_id not found")
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success({"removed_password": {"key_id": kid}})

        if action == "add_certificate":
            cert = (body or {}).get("certificate") or {}
            if not isinstance(cert, dict):
                return _finish_error("VALIDATION_ERROR", "body.certificate must be an object")
            kid = cert.get("keyId") or cert.get("key_id") or f"crt_{uuid.uuid4().hex}"
            creds["certificates"].append({"key_id": kid, "payload": cert, "added_at": _now()})
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success({"added_certificate": {"key_id": kid}})

        if action == "remove_certificate":
            kid = (body or {}).get("key_id")
            if not isinstance(kid, str) or not kid:
                return _finish_error("VALIDATION_ERROR", "body.key_id is required")
            before = len(creds.get("certificates", []))
            creds["certificates"] = [p for p in creds.get("certificates", []) if not (isinstance(p, dict) and p.get("key_id") == kid)]
            if len(creds["certificates"]) == before:
                return _finish_error("NOT_FOUND", "Certificate key_id not found")
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success({"removed_certificate": {"key_id": kid}})

        if action == "set_app_role_assignments":
            assigns = (body or {}).get("app_role_assignments")
            if not isinstance(assigns, list) or any(not isinstance(a, dict) for a in assigns):
                return _finish_error("VALIDATION_ERROR", "body.app_role_assignments must be an array of objects")
            props["app_role_assignments"] = assigns
            sp["updated_at"] = _now()
            _save("directory_entities.json", ents)
            return _finish_success({"app_role_assignments": assigns})

        return _finish_error("VALIDATION_ERROR", "Unsupported action")
    except Exception:
        return _finish_error("CONFLICT", "Internal error while processing request", norm="internal_error")

def dynamicendpoints_m365_assistant(tenant_id, provider, method, path, query=None, headers=None, body=None, select=None, response_format=None, max_retries=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    # validate
    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if provider not in ("microsoft_graph", "azure_resource_manager", "exchange_online", "intune", "purview", "sharepoint", "other"):
        return _err("VALIDATION_ERROR", "provider must be a supported value")
    if method not in ("GET", "POST", "PATCH", "PUT", "DELETE"):
        return _err("VALIDATION_ERROR", "method must be one of GET, POST, PATCH, PUT, DELETE")
    if not isinstance(path, str) or not path:
        return _err("VALIDATION_ERROR", "path must be a non-empty string")
    if query is not None:
        if not isinstance(query, dict) or any((not isinstance(k, str) or not isinstance(v, str)) for k, v in query.items()):
            return _err("VALIDATION_ERROR", "query must be an object of string:string")
    if headers is not None:
        if not isinstance(headers, dict) or any((not isinstance(k, str) or not isinstance(v, str)) for k, v in headers.items()):
            return _err("VALIDATION_ERROR", "headers must be an object of string:string")
    if select is not None:
        if not isinstance(select, list) or any((not isinstance(x, str)) for x in select):
            return _err("VALIDATION_ERROR", "select must be an array of strings")
    if response_format is None:
        response_format = "json"
    if response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "response_format must be one of json, text, table, raw")
    if max_retries is None:
        max_retries = 3
    if not isinstance(max_retries, int) or max_retries < 0 or max_retries > 10:
        return _err("VALIDATION_ERROR", "max_retries must be an integer between 0 and 10")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")

    # idempotency: if supplied, reuse latest succeeded op with same key+shape
    if idempotency_key:
        for o in reversed(ops):
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_id:
                continue
            if o.get("tool_name") != "dynamicendpoints m365 assistant":
                continue
            rp = o.get("request_payload")
            if not isinstance(rp, dict):
                continue
            if rp.get("idempotency_key") == idempotency_key and rp.get("provider") == provider and rp.get("method") == method and rp.get("path") == path:
                if o.get("status") == "succeeded":
                    # also log this call as a new operation (real systems do), but return same payload for idempotency
                    break

    upstream_cost = 1
    rate_limited = not _rate_limit_allows(tenant_row, ops, upstream_cost)

    op_id = _new_id("m365_opr_", ops)
    now = _now()
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "dynamicendpoints m365 assistant",
        "operation_kind": "workflow" if method in ("POST", "PATCH", "PUT", "DELETE") else "read",
        "request_payload": {
            "tenant_id": tenant_id,
            "provider": provider,
            "method": method,
            "path": path,
            "query": query,
            "headers": headers,
            "body": body,
            "select": select,
            "response_format": response_format,
            "max_retries": max_retries,
            "idempotency_key": idempotency_key,
        },
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": max_retries + 1 if isinstance(max_retries, int) else 1,
        "rate_limited": bool(rate_limited),
        "upstream_provider": provider,
        "upstream_request_count": 0,
        "response_format": response_format,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    # Offline simulation of upstream call: echo normalized request, apply select for json
    # This tool must not fabricate external resources; it returns a deterministic "upstream_response" describing what would be sent.
    normalized = {
        "provider": provider,
        "method": method,
        "path": path,
        "query": query or {},
        "headers": headers or {},
        "body": body,
    }

    resp_obj = {"upstream_request": normalized, "note": "Offline datastore server: upstream call simulated."}

    if response_format == "json":
        result = resp_obj
        if select:
            # selection over top-level keys of resp_obj
            result = {k: resp_obj.get(k) for k in select}
    elif response_format == "text":
        result = f"{method} {path} via {provider}"
    elif response_format == "table":
        result = {"columns": ["field", "value"], "rows": [[k, json.dumps(v, ensure_ascii=False)] for k, v in normalized.items()]}
    else:  # raw
        result = {"raw": resp_obj}

    op_row["status"] = "succeeded"
    op_row["upstream_request_count"] = 1
    op_row["response_payload"] = result
    op_row["finished_at"] = _now()
    op_row["updated_at"] = op_row["finished_at"]
    _save("operations.json", ops)

    return {"operation": op_row, "result": result}

def search_audit_log(tenant_id, start_time, end_time, user_principal_name=None, activity=None, workload=None, client_ip=None, resource_external_id=None, retrieved_by_operation_id=None, response_format=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    def _parse_required_dt(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]), None
            return datetime.datetime.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 date-time")
    st, e1 = _parse_required_dt(start_time, "start_time")
    if e1:
        return e1
    et, e2 = _parse_required_dt(end_time, "end_time")
    if e2:
        return e2
    if et <= st:
        return _err("VALIDATION_ERROR", "end_time must be after start_time")
    if retrieved_by_operation_id is not None:
        if not isinstance(retrieved_by_operation_id, str) or not re.match(r"^m365_opr_[0-9A-Z]{18,}$", retrieved_by_operation_id):
            return _err("VALIDATION_ERROR", "retrieved_by_operation_id must match ^m365_opr_[0-9A-Z]{18,}$")
    if response_format is None:
        response_format = "json"
    if response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 5000:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 5000")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    tenants = _load("tenants.json")
    operations = _load("operations.json")
    audit_events = _load("audit_log_events.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "Tenant not found")
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "Tenant is not active", tenant_status=tenant.get("status"))

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _sum_upstream_last_minute(tid):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        total = 0
        for op in operations:
            if op.get("tenant_id") != tid:
                continue
            started = _parse_dt(op.get("started_at")) or _parse_dt(op.get("created_at"))
            if started and started >= cutoff:
                cnt = op.get("upstream_request_count")
                if isinstance(cnt, int) and cnt >= 0:
                    total += cnt
        return total

    def _new_id(prefix):
        raw = f"{prefix}|{datetime.datetime.utcnow().isoformat()}|{os.getpid()}|{time.time()}".encode("utf-8")
        digest = hashlib.sha1(raw).digest()
        s = base64.b32encode(digest).decode("ascii").rstrip("=")
        return f"m365_{prefix}_{s}"

    # create operation row
    op_id = _new_id("opr")
    request_payload = {
        "tenant_id": tenant_id,
        "start_time": start_time,
        "end_time": end_time,
        "user_principal_name": user_principal_name,
        "activity": activity,
        "workload": workload,
        "client_ip": client_ip,
        "resource_external_id": resource_external_id,
        "retrieved_by_operation_id": retrieved_by_operation_id,
        "limit": limit,
        "cursor": cursor,
        "response_format": response_format,
    }
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "search_audit_log",
        "operation_kind": "search",
        "request_payload": request_payload,
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "purview",
        "upstream_request_count": 0,
        "response_format": response_format,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op)
    _save("operations.json", operations)

    def _finish_success(payload, upstream_count=1):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for o in operations:
            if o.get("id") == op_id:
                o["status"] = "succeeded"
                o["attempt_count"] = int(o.get("attempt_count") or 0) + 1
                o["started_at"] = o["started_at"] or now
                o["finished_at"] = finished
                o["updated_at"] = finished
                o["upstream_request_count"] = int(upstream_count)
                o["response_payload"] = payload
                o["error_code"] = None
                o["error_message"] = None
                break
        _save("operations.json", operations)
        return {"operation": next((o for o in operations if o.get("id") == op_id), op), "data": payload}

    def _finish_error(code, msg, upstream_count=0, extra=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for o in operations:
            if o.get("id") == op_id:
                o["status"] = "failed"
                o["attempt_count"] = int(o.get("attempt_count") or 0) + 1
                o["started_at"] = o["started_at"] or now
                o["finished_at"] = finished
                o["updated_at"] = finished
                o["upstream_request_count"] = int(upstream_count)
                o["response_payload"] = None
                o["error_code"] = code
                o["error_message"] = msg
                break
        _save("operations.json", operations)
        if extra:
            return _err(code, msg, operation_id=op_id, **extra)
        return _err(code, msg, operation_id=op_id)

    # rate limit
    projected = _sum_upstream_last_minute(tenant_id) + 1
    if projected > int(tenant.get("rate_limit_per_minute") or 60):
        for o in operations:
            if o.get("id") == op_id:
                o["rate_limited"] = True
                o["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("operations.json", operations)
        return _finish_error("RATE_LIMIT", "Tenant rate limit exceeded; search delayed", upstream_count=0, extra={"rate_limited": True, "retry_after_seconds": 60})

    # queued->running
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for o in operations:
        if o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = started
            o["updated_at"] = started
            break
    _save("operations.json", operations)

    # Search local persisted events (offline). Optionally filter by retrieved_by_operation_id.
    def _match(ev):
        if ev.get("tenant_id") != tenant_id:
            return False
        etime = _parse_dt(ev.get("event_time"))
        if not etime:
            return False
        if not (st <= etime < et):
            return False
        if retrieved_by_operation_id is not None and ev.get("retrieved_by_operation_id") != retrieved_by_operation_id:
            return False
        if user_principal_name is not None and ev.get("user_principal_name") != user_principal_name:
            return False
        if activity is not None and ev.get("activity") != activity:
            return False
        if workload is not None and ev.get("workload") != workload:
            return False
        if client_ip is not None and ev.get("client_ip") != client_ip:
            return False
        if resource_external_id is not None and ev.get("resource_external_id") != resource_external_id:
            return False
        return True

    matched = [ev for ev in audit_events if _match(ev)]
    matched.sort(key=lambda x: (x.get("event_time") or "", x.get("id") or ""))

    # pagination cursor: base64("o:<offset>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw.split(":", 1)[1])
        except Exception:
            return _finish_error("VALIDATION_ERROR", "Invalid cursor", upstream_count=1)

    lim = limit if limit is not None else 1000
    page = matched[offset: offset + lim]
    has_more = offset + lim < len(matched)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{offset+lim}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Persist returned events into audit_log_events linked to this operation; dedupe by unique constraint.
    # In offline mode, we treat "returned events" as those already known + any synthetic none (we do not invent events).
    # However, rule requires persistence of returned events: ensure all in page are linked to this op by creating clones
    # only if they were retrieved by another op; dedupe on unique key.
    def _uniq_key(ev, rid):
        return (
            ev.get("tenant_id"),
            rid,
            ev.get("event_time"),
            ev.get("activity"),
            ev.get("user_principal_name"),
            ev.get("client_ip"),
        )

    existing_keys = set()
    for ev in audit_events:
        existing_keys.add(_uniq_key(ev, ev.get("retrieved_by_operation_id")))

    inserted = 0
    for ev in page:
        # if already linked to this operation, skip; else create a new row with this retrieved_by_operation_id
        key = _uniq_key(ev, op_id)
        if key in existing_keys:
            continue
        new_ev = dict(ev)
        new_ev["id"] = _new_id("evt")
        new_ev["retrieved_by_operation_id"] = op_id
        new_ev["created_at"] = now
        new_ev["updated_at"] = now
        audit_events.append(new_ev)
        existing_keys.add(key)
        inserted += 1

    if inserted:
        _save("audit_log_events.json", audit_events)

    payload = {
        "items": page,
        "total": len(matched),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "persisted_event_copies": inserted,
    }
    return _finish_success(payload, upstream_count=1)

def manage_alerts(tenant_id, action, alert_entity_id=None, external_alert_id=None, status=None, severity=None, response_format=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "manage_alerts"
    if not isinstance(tenant_id, str) or re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id) is None:
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    if action not in ("list_alerts","get_alert","update_alert_status"):
        return _err("VALIDATION_ERROR", "action must be one of: list_alerts, get_alert, update_alert_status")
    if response_format is None:
        response_format = "json"
    if response_format not in ("json","text","table","raw"):
        return _err("VALIDATION_ERROR", "response_format is invalid")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if alert_entity_id is not None and not isinstance(alert_entity_id, str):
        return _err("VALIDATION_ERROR", "alert_entity_id must be a string")
    if status is not None and status not in ("active","pending","deleted","error"):
        return _err("VALIDATION_ERROR", "status is invalid")
    if severity is not None and severity not in ("low","medium","high","critical"):
        return _err("VALIDATION_ERROR", "severity is invalid")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00","Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _tenant_rate_ok(tenant_row, ops_rows, intended=1):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict): 
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) if o.get("started_at") else None
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return (used + max(0, intended)) <= lim

    def _decode_cursor(cur):
        if cur is None: return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", 0)
            return off if isinstance(off, int) and off >= 0 else None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",",":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    tenants = _load("tenants.json")
    ents = _load("directory_entities.json")
    ops = _load("operations.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id")==tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        # record op
        now = _now_iso()
        op_id = _new_id("m365_opr")
        ops.append({
            "id": op_id, "tenant_id": tenant_id, "tool_name": TOOL, "operation_kind": "read",
            "request_payload": {"tenant_id": tenant_id, "action": action, "alert_entity_id": alert_entity_id, "external_alert_id": external_alert_id, "status": status, "severity": severity, "response_format": response_format, "limit": limit, "cursor": cursor, "body": body},
            "target_entity_id": None, "status": "failed", "attempt_count": 1, "max_attempts": 1, "rate_limited": False,
            "upstream_provider": "purview", "upstream_request_count": 0, "response_format": response_format, "response_payload": None,
            "error_code": "tenant_inactive", "error_message": "tenant is not active",
            "started_at": now, "finished_at": now, "created_at": now, "updated_at": now,
        })
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "tenant is not active")

    # create op row
    now = _now_iso()
    kind = "search" if action=="list_alerts" else "update" if action=="update_alert_status" else "read"
    target_id = alert_entity_id if isinstance(alert_entity_id, str) and re.match(r"^m365_ent_[0-9A-Z]{18,}$", alert_entity_id) else None
    op = {
        "id": _new_id("m365_opr"),
        "tenant_id": tenant_id,
        "tool_name": TOOL,
        "operation_kind": kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "alert_entity_id": alert_entity_id, "external_alert_id": external_alert_id, "status": status, "severity": severity, "response_format": response_format, "limit": limit, "cursor": cursor, "body": body},
        "target_entity_id": target_id,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "purview",
        "upstream_request_count": 0,
        "response_format": response_format,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)

    intended = 0 if kind in ("read","search") else 1
    if not _tenant_rate_ok(tenant, ops, intended=intended):
        op["rate_limited"] = True
        op["updated_at"] = _now_iso()
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "tenant rate limit would be exceeded; operation delayed", operation_id=op["id"])

    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]

    def _final(st, payload=None, ecode=None, emsg=None, upstream_count=0):
        t = _now_iso()
        op["status"] = st
        op["updated_at"] = t
        if st not in ("queued","running"):
            op["finished_at"] = t
        op["upstream_request_count"] = int(upstream_count) if isinstance(upstream_count, int) and upstream_count >= 0 else 0
        if payload is not None:
            op["response_payload"] = payload
        op["error_code"] = ecode
        op["error_message"] = emsg
        _save("operations.json", ops)

    def _find_alert_by_external(exid):
        if not isinstance(exid, str) or not exid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="security_alert" and e.get("external_id")==exid), None)

    def _find_alert_by_id(eid):
        if not isinstance(eid, str): return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="security_alert" and e.get("id")==eid), None)

    try:
        if action == "list_alerts":
            items = [e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="security_alert" and e.get("status")!="deleted"]
            if severity is not None:
                # stored in properties.severity or properties.state sometimes; best-effort filter
                items = [e for e in items if (isinstance(e.get("properties"), dict) and str(e["properties"].get("severity","")).lower()==severity)]
            off = _decode_cursor(cursor)
            if off is None:
                _final("failed", ecode="validation", emsg="invalid cursor", upstream_count=0)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            lim = 200 if limit is None else min(200, int(limit))
            items.sort(key=lambda x: (x.get("created_at") or ""), reverse=True)
            page = items[off:off+lim]
            next_off = off + len(page)
            has_more = next_off < len(items)
            next_cur = _encode_cursor(next_off) if has_more else None
            payload = {"items": page, "total": len(items), "has_more": has_more, "next_cursor": next_cur}
            _final("succeeded", payload=payload, upstream_count=0)
            return {"operation_id": op["id"], **payload}

        if action == "get_alert":
            alert = _find_alert_by_id(alert_entity_id) if alert_entity_id else _find_alert_by_external(external_alert_id)
            if not alert:
                _final("failed", ecode="not_found", emsg="alert not found", upstream_count=0)
                return _err("NOT_FOUND", "alert not found")
            _final("succeeded", payload={"alert": alert}, upstream_count=0)
            return {"operation_id": op["id"], "alert": alert}

        if action == "update_alert_status":
            # BUSINESS RULE: status updates must be reflected in properties.state while directory_entities.status remains active unless deleted.
            alert = _find_alert_by_id(alert_entity_id) if alert_entity_id else _find_alert_by_external(external_alert_id)
            if not alert:
                _final("failed", ecode="not_found", emsg="alert not found", upstream_count=0)
                return _err("NOT_FOUND", "alert not found")
            if status is None:
                _final("failed", ecode="validation", emsg="status required", upstream_count=0)
                return _err("VALIDATION_ERROR", "status is required for update_alert_status")
            if alert.get("status") == "deleted" and status != "deleted":
                _final("failed", ecode="invalid_transition", emsg="cannot transition deleted alert", upstream_count=0)
                return _err("INVALID_TRANSITION", "cannot transition alert from deleted")
            props = alert.get("properties") if isinstance(alert.get("properties"), dict) else {}
            props["state"] = status
            if body and isinstance(body.get("properties"), dict):
                # merge additional properties
                for k, v in body["properties"].items():
                    props[k] = v
            alert["properties"] = props
            # keep directory_entities.status active unless deleting
            if status == "deleted":
                alert["status"] = "deleted"
            else:
                if alert.get("status") != "active":
                    # normalize to active for managed objects
                    alert["status"] = "active"
            alert["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"alert": alert}, upstream_count=1)
            return {"operation_id": op["id"], "alert": alert}

        _final("failed", ecode="validation", emsg="unsupported action", upstream_count=0)
        return _err("VALIDATION_ERROR", "unsupported action")
    except Exception as e:
        _final("failed", ecode="internal_error", emsg=str(e), upstream_count=0)
        return _err("CONFLICT", "internal error", detail=str(e))

def manage_dlp_policies(tenant_id, action, policy_id=None, external_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, uuid
