    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None and not isinstance(sort, dict):
        return _err("VALIDATION_ERROR", "sort must be an object")
    if sort is not None:
        if sort.get("field") not in ("created_at","updated_at","display_name","status") or sort.get("direction") not in ("asc","desc"):
            return _err("VALIDATION_ERROR", "sort is invalid")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00","Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _tenant_rate_ok(tenant_row, ops_rows, intended=1):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict): 
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) if o.get("started_at") else None
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return (used + max(0, intended)) <= lim

    def _decode_cursor(cur):
        if cur is None: return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", 0)
            return off if isinstance(off, int) and off >= 0 else None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",",":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    tenants = _load("tenants.json")
    ents = _load("directory_entities.json")
    ops = _load("operations.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id")==tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        # record and reject
        now = _now_iso()
        op_id = _new_id("m365_opr")
        ops.append({
            "id": op_id, "tenant_id": tenant_id, "tool_name": TOOL, "operation_kind": "read",
            "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
            "target_entity_id": None, "status": "failed", "attempt_count": 1, "max_attempts": 1, "rate_limited": False,
            "upstream_provider": "purview", "upstream_request_count": 0, "response_format": "json", "response_payload": None,
            "error_code": "tenant_inactive", "error_message": "tenant is not active",
            "started_at": now, "finished_at": now, "created_at": now, "updated_at": now,
        })
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "tenant is not active")

    kind = "search" if action=="list" else ("create" if action=="create" else ("delete" if action=="delete" else ("update" if action=="update" else "read")))
    now = _now_iso()
    target_id = policy_id if isinstance(policy_id, str) and re.match(r"^m365_ent_[0-9A-Z]{18,}$", policy_id) else None
    op = {
        "id": _new_id("m365_opr"),
        "tenant_id": tenant_id,
        "tool_name": TOOL,
        "operation_kind": kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
        "target_entity_id": target_id,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "purview",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)

    intended = 0 if kind in ("read","search") else 1
    if not _tenant_rate_ok(tenant, ops, intended=intended):
        op["rate_limited"] = True
        op["updated_at"] = _now_iso()
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "tenant rate limit would be exceeded; operation delayed", operation_id=op["id"])

    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]

    def _final(st, payload=None, ecode=None, emsg=None, upstream_count=0):
        t = _now_iso()
        op["status"] = st
        op["updated_at"] = t
        if st not in ("queued","running"):
            op["finished_at"] = t
        op["upstream_request_count"] = int(upstream_count) if isinstance(upstream_count, int) and upstream_count >= 0 else 0
        if payload is not None:
            op["response_payload"] = payload
        op["error_code"] = ecode
        op["error_message"] = emsg
        _save("operations.json", ops)

    def _find_by_id(eid):
        if not isinstance(eid, str): return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="purview_dlp_policy" and e.get("id")==eid), None)

    def _find_by_external(exid):
        if not isinstance(exid, str) or not exid: return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="purview_dlp_policy" and e.get("external_id")==exid), None)

    try:
        if action == "list":
            flt = filters or {}
            items = [e for e in ents if isinstance(e, dict) and e.get("tenant_id")==tenant_id and e.get("entity_type")=="purview_dlp_policy"]
            if flt.get("status"):
                items = [e for e in items if e.get("status")==flt["status"]]
            if flt.get("external_id"):
                items = [e for e in items if e.get("external_id")==flt["external_id"]]
            if flt.get("display_name_contains"):
                sub = str(flt["display_name_contains"]).lower()
                items = [e for e in items if sub in str(e.get("display_name","") or "").lower()]
            s = sort or {"field":"created_at","direction":"desc"}
            rev = (s["direction"] == "desc")
            key = s["field"]
            items.sort(key=lambda e: (e.get(key) or ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _final("failed", ecode="validation", emsg="invalid cursor", upstream_count=0)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            lim = 200 if limit is None else min(200, int(limit))
            page = items[off:off+lim]
            next_off = off + len(page)
            has_more = next_off < len(items)
            next_cur = _encode_cursor(next_off) if has_more else None
            payload = {"items": page, "total": len(items), "has_more": has_more, "next_cursor": next_cur}
            _final("succeeded", payload=payload, upstream_count=0)
            return {"operation_id": op["id"], **payload}

        if action == "get":
            ent = _find_by_id(policy_id) if policy_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="policy not found", upstream_count=0)
                return _err("NOT_FOUND", "policy not found")
            _final("succeeded", payload={"policy": ent}, upstream_count=0)
            return {"operation_id": op["id"], "policy": ent}

        if action == "create":
            if body is None or not isinstance(body, dict):
                _final("failed", ecode="validation", emsg="body is required for create", upstream_count=0)
                return _err("VALIDATION_ERROR", "body is required for create")
            if "display_name" in body and body["display_name"] is not None and not isinstance(body["display_name"], str):
                _final("failed", ecode="validation", emsg="display_name must be string", upstream_count=0)
                return _err("VALIDATION_ERROR", "body.display_name must be a string")
            if "enabled" in body and body["enabled"] is not None and not isinstance(body["enabled"], bool):
                _final("failed", ecode="validation", emsg="enabled must be boolean", upstream_count=0)
                return _err("VALIDATION_ERROR", "body.enabled must be a boolean")
            if "properties" in body and body["properties"] is not None and not isinstance(body["properties"], dict):
                _final("failed", ecode="validation", emsg="properties must be object", upstream_count=0)
                return _err("VALIDATION_ERROR", "body.properties must be an object")
            now2 = _now_iso()
            exid = external_id if isinstance(external_id, str) and external_id else f"purview.dlp.policy:{uuid.uuid4().hex}"
            existing = _find_by_external(exid)
            if existing:
                _final("failed", ecode="conflict", emsg="policy with external_id already exists", upstream_count=0)
                return _err("CONFLICT", "policy with this external_id already exists")
            ent = {
                "id": _new_id("m365_ent"),
                "tenant_id": tenant_id,
                "entity_type": "purview_dlp_policy",
                "external_id": exid,
                "display_name": body.get("display_name"),
                "principal_name": None,
                "mail": None,
                "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                "status": "active",
                "properties": dict(body.get("properties") or {}),
                "created_at": now2,
                "updated_at": now2,
            }
            # business rule: status updates go to properties.state; keep entity status active unless deleted
            ent["properties"].setdefault("state", "active")
            ents.append(ent)
            _save("directory_entities.json", ents)
            op["target_entity_id"] = ent["id"]
            _final("succeeded", payload={"policy": ent}, upstream_count=1)
            return {"operation_id": op["id"], "policy": ent}

        if action == "update":
            ent = _find_by_id(policy_id) if policy_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="policy not found", upstream_count=0)
                return _err("NOT_FOUND", "policy not found")
            if body is None or not isinstance(body, dict):
                _final("failed", ecode="validation", emsg="body is required for update", upstream_count=0)
                return _err("VALIDATION_ERROR", "body is required for update")
            if "display_name" in body and body["display_name"] is not None:
                if not isinstance(body["display_name"], str):
                    _final("failed", ecode="validation", emsg="display_name must be string", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.display_name must be a string")
                ent["display_name"] = body["display_name"]
            if "enabled" in body and body["enabled"] is not None:
                if not isinstance(body["enabled"], bool):
                    _final("failed", ecode="validation", emsg="enabled must be boolean", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.enabled must be a boolean")
                ent["enabled"] = body["enabled"]
                props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                props["state"] = "active" if body["enabled"] else "disabled"
                ent["properties"] = props
            if "properties" in body and body["properties"] is not None:
                if not isinstance(body["properties"], dict):
                    _final("failed", ecode="validation", emsg="properties must be object", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.properties must be an object")
                props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                for k, v in body["properties"].items():
                    props[k] = v
                ent["properties"] = props
            ent["status"] = "active" if ent.get("status") != "deleted" else "deleted"
            ent["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"policy": ent}, upstream_count=1)
            return {"operation_id": op["id"], "policy": ent}

        if action == "delete":
            ent = _find_by_id(policy_id) if policy_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="policy not found", upstream_count=0)
                return _err("NOT_FOUND", "policy not found")
            if ent.get("status") == "deleted":
                _final("succeeded", payload={"policy": ent}, upstream_count=0)
                return {"operation_id": op["id"], "policy": ent}
            if ent.get("status") not in ("active","pending","error"):
                _final("failed", ecode="invalid_transition", emsg="cannot delete from current status", upstream_count=0)
                return _err("INVALID_TRANSITION", f"cannot transition directory_entities.status from {ent.get('status')} to deleted")
            ent["status"] = "deleted"
            props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
            props["state"] = "deleted"
            ent["properties"] = props
            ent["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"policy": ent}, upstream_count=1)
            return {"operation_id": op["id"], "policy": ent}

        _final("failed", ecode="validation", emsg="unsupported action", upstream_count=0)
        return _err("VALIDATION_ERROR", "unsupported action")
    except Exception as e:
        _final("failed", ecode="internal_error", emsg=str(e), upstream_count=0)
        return _err("CONFLICT", "internal error", detail=str(e))

def manage_dlp_incidents(tenant_id, action, incident_id=None, external_id=None, status=None, body=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if dt is None or dt < cutoff:
                continue
            try:
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if action not in ("get", "list", "update_status", "add_remediation_note"):
        return _err("VALIDATION_ERROR", "action must be one of get, list, update_status, add_remediation_note")
    if status is not None and status not in ("active", "pending", "deleted", "error"):
        return _err("VALIDATION_ERROR", "status must be one of active, pending, deleted, error")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        for k in filters.keys():
            if k not in ("status", "display_name_contains", "external_id"):
                return _err("VALIDATION_ERROR", f"filters contains unknown field '{k}'")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("active", "pending", "deleted", "error"):
            return _err("VALIDATION_ERROR", "filters.status must be one of active, pending, deleted, error")
        if "display_name_contains" in filters and filters["display_name_contains"] is not None and not isinstance(filters["display_name_contains"], str):
            return _err("VALIDATION_ERROR", "filters.display_name_contains must be a string")
        if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
            return _err("VALIDATION_ERROR", "filters.external_id must be a string")
    if sort is not None:
        if not isinstance(sort, dict) or sort.get("field") not in ("created_at", "updated_at", "display_name", "status") or sort.get("direction") not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "sort must be {field, direction} with supported values")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")

    # create operation row
    op_id = _new_id("m365_opr_", ops)
    op_now = _now()
    kind = "read" if action == "get" else ("search" if action == "list" else "update")
    rate_limited = not _rate_limit_allows(tenant_row, ops, 1)
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_dlp_incidents",
        "operation_kind": kind,
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "incident_id": incident_id,
            "external_id": external_id,
            "status": status,
            "body": body,
            "filters": filters,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        },
        "target_entity_id": incident_id if isinstance(incident_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": bool(rate_limited),
        "upstream_provider": "purview",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": op_now,
        "updated_at": op_now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = 1
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(api_code, msg, err_code=None):
        op_row["status"] = "failed"
        op_row["error_code"] = err_code or api_code
        op_row["error_message"] = msg
        op_row["upstream_request_count"] = 1
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err(api_code, msg, operation_id=op_id)

    def _find_by_id(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("id") == eid and e.get("entity_type") == "purview_dlp_incident"), None)

    def _find_by_external(ext):
        if not isinstance(ext, str) or not ext:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "purview_dlp_incident" and e.get("external_id") == ext), None)

    if action == "list":
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "purview_dlp_incident"]
        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("display_name_contains") is not None:
            q = f.get("display_name_contains").lower()
            rows = [e for e in rows if isinstance(e.get("display_name"), str) and q in e["display_name"].lower()]
        if sort is None:
            sort = {"field": "created_at", "direction": "desc"}
        field = sort["field"]
        rev = sort["direction"] == "desc"
        rows.sort(key=lambda e: e.get(field) or "", reverse=rev)
        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        return _finish_success({"items": page, "total": total, "has_more": next_off < total, "next_cursor": _encode_cursor(next_off) if next_off < total else None})

    # get/update targets
    ent = None
    if incident_id:
        ent = _find_by_id(incident_id)
    if ent is None and external_id:
        ent = _find_by_external(external_id)

    if action == "get":
        if not ent:
            return _finish_error("NOT_FOUND", "DLP incident not found")
        return _finish_success({"incident": ent})

    if not ent:
        return _finish_error("NOT_FOUND", "DLP incident not found")

    # Business rule: status updates reflected in directory_entities.properties.state while directory_entities.status remains 'active' unless deleted.
    p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
    if action == "update_status":
        if status is None:
            return _finish_error("VALIDATION_ERROR", "status is required for update_status")
        p0["state"] = status
        ent["properties"] = p0
        # keep local entity status active unless deleted
        if status == "deleted":
            ent["status"] = "deleted"
        else:
            if ent.get("status") == "deleted":
                return _finish_error("INVALID_TRANSITION", "Cannot update a deleted incident")
            ent["status"] = "active"
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"incident": ent})

    if action == "add_remediation_note":
        details = (body or {}).get("details") if isinstance(body, dict) else None
        if details is None:
            details = {}
        if not isinstance(details, dict):
