        _finalize("succeeded", {"label": lab, "operation_id": op_id}, upstream_request_count=intended_upstream)
        return {"operation_id": op_id, "label": lab}

    _finalize("failed", None, "VALIDATION_ERROR", "Unsupported action", upstream_request_count=intended_upstream)
    return _err("VALIDATION_ERROR", "Unsupported action", operation_id=op_id)

