    ents = _load("directory_entities.json")

    op_id = _new_id("m365_opr_", ops)
    now = _now()
    kind = "read" if action == "get" else ("search" if action == "list" else ("delete" if action == "delete" else "update"))
    rate_limited = not _rate_limit_allows(tenant_row, ops, 1)
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_intune_macos_policies",
        "operation_kind": kind,
