            exid = external_id if isinstance(external_id, str) and external_id else f"intune.macos.app:{uuid.uuid4().hex}"
            if _find_by_external(exid):
                _final("failed", ecode="conflict", emsg="external_id already exists", upstream_count=0)
                return _err("CONFLICT", "app with this external_id already exists")
            ent = {
                "id": _new_id("m365_ent"),
                "tenant_id": tenant_id,
                "entity_type": "intune_app_macos",
                "external_id": exid,
                "display_name": body.get("display_name"),
                "principal_name": None,
                "mail": None,
                "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                "status": "active",
                "properties": dict(body.get("properties") or {}),
                "created_at": now2,
                "updated_at": now2,
            }
            ents.append(ent)
            _save("directory_entities.json", ents)
            op["target_entity_id"] = ent["id"]
            _final("succeeded", payload={"app": ent}, upstream_count=1)
            return {"operation_id": op["id"], "app": ent}

        if action == "update":
            ent = _find_by_id(app_id) if app_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="app not found", upstream_count=0)
                return _err("NOT_FOUND", "app not found")
            if body is None or not isinstance(body, dict):
                _final("failed", ecode="validation", emsg="body required", upstream_count=0)
                return _err("VALIDATION_ERROR", "body is required for update")
            if "display_name" in body and body["display_name"] is not None:
                if not isinstance(body["display_name"], str):
                    _final("failed", ecode="validation", emsg="display_name must be string", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.display_name must be a string")
                ent["display_name"] = body["display_name"]
            if "enabled" in body and body["enabled"] is not None:
                if not isinstance(body["enabled"], bool):
                    _final("failed", ecode="validation", emsg="enabled must be boolean", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.enabled must be a boolean")
                ent["enabled"] = body["enabled"]
            if "properties" in body and body["properties"] is not None:
                if not isinstance(body["properties"], dict):
                    _final("failed", ecode="validation", emsg="properties must be object", upstream_count=0)
                    return _err("VALIDATION_ERROR", "body.properties must be an object")
                props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                for k, v in body["properties"].items():
                    props[k] = v
                ent["properties"] = props
            ent["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"app": ent}, upstream_count=1)
            return {"operation_id": op["id"], "app": ent}

        if action == "delete":
            ent = _find_by_id(app_id) if app_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="app not found", upstream_count=0)
                return _err("NOT_FOUND", "app not found")
            if ent.get("status") == "deleted":
                _final("succeeded", payload={"app": ent}, upstream_count=0)
                return {"operation_id": op["id"], "app": ent}
            if ent.get("status") not in ("active","pending","error"):
                _final("failed", ecode="invalid_transition", emsg="cannot delete from current status", upstream_count=0)
                return _err("INVALID_TRANSITION", f"cannot transition directory_entities.status from {ent.get('status')} to deleted")
            ent["status"] = "deleted"
            ent["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"app": ent}, upstream_count=1)
            return {"operation_id": op["id"], "app": ent}

        if action in ("assign","remove_assignment"):
            ent = _find_by_id(app_id) if app_id else _find_by_external(external_id)
            if not ent:
                _final("failed", ecode="not_found", emsg="app not found", upstream_count=0)
                return _err("NOT_FOUND", "app not found")
            if assignments is None:
                _final("failed", ecode="validation", emsg="assignments required", upstream_count=0)
                return _err("VALIDATION_ERROR", "assignments is required for assignment actions")
            props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
            current = props.get("assignments")
            if not isinstance(current, list):
                current = []
            if action == "assign":
                # upsert by target_entity_id
                idx = {a.get("target_entity_id"): a for a in current if isinstance(a, dict) and isinstance(a.get("target_entity_id"), str)}
                for a in assignments:
                    idx[a["target_entity_id"]] = {"target_entity_id": a["target_entity_id"], "intent": a["intent"]}
                props["assignments"] = list(idx.values())
            else:
                remove_ids = {a["target_entity_id"] for a in assignments if isinstance(a, dict) and isinstance(a.get("target_entity_id"), str)}
                props["assignments"] = [a for a in current if not (isinstance(a, dict) and a.get("target_entity_id") in remove_ids)]
            ent["properties"] = props
            ent["updated_at"] = _now_iso()
            _save("directory_entities.json", ents)
            _final("succeeded", payload={"app": ent}, upstream_count=1)
            return {"operation_id": op["id"], "app": ent}

        _final("failed", ecode="validation", emsg="unsupported action", upstream_count=0)
        return _err("VALIDATION_ERROR", "unsupported action")
    except Exception as e:
        _final("failed", ecode="internal_error", emsg=str(e), upstream_count=0)
        return _err("CONFLICT", "internal error", detail=str(e))

def manage_intune_macos_compliance(tenant_id, action, compliance_policy_id=None, external_id=None, body=None, assignments=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 2000:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _new_id(prefix, rows):
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _rate_window_used(tenant_row, ops_rows):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        used = 0
        for o in ops_rows:
            if not isinstance(o, dict):
                continue
            if o.get("tenant_id") != tenant_row.get("id"):
                continue
            dt = o.get("started_at") or o.get("created_at")
            try:
                ss = dt[:-1] + "+00:00" if isinstance(dt, str) and dt.endswith("Z") else dt
                ddt = datetime.datetime.fromisoformat(ss) if isinstance(ss, str) else None
                if ddt and ddt.tzinfo is None:
                    ddt = ddt.replace(tzinfo=datetime.timezone.utc)
                if not ddt:
                    continue
                if ddt < cutoff:
                    continue
                used += max(0, int(o.get("upstream_request_count", 0)))
            except Exception:
                pass
        return used

    def _rate_limit_allows(tenant_row, ops_rows, new_upstream):
        try:
            lim = int(tenant_row.get("rate_limit_per_minute"))
        except Exception:
            lim = 60
        used = _rate_window_used(tenant_row, ops_rows)
        try:
            add = max(0, int(new_upstream))
        except Exception:
            add = 0
        return (used + add) <= lim

    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if action not in ("create", "update", "delete", "get", "list", "assign"):
        return _err("VALIDATION_ERROR", "action must be one of create, update, delete, get, list, assign")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if assignments is not None:
        if not isinstance(assignments, list):
            return _err("VALIDATION_ERROR", "assignments must be an array")
        for a in assignments:
            if not isinstance(a, dict) or "target_entity_id" not in a or "intent" not in a:
                return _err("VALIDATION_ERROR", "assignments items must include target_entity_id and intent")
            if not isinstance(a["target_entity_id"], str):
                return _err("VALIDATION_ERROR", "assignments.target_entity_id must be a string")
            if a["intent"] not in ("required", "not_applicable", "available", "uninstall"):
                return _err("VALIDATION_ERROR", "assignments.intent must be supported")

    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")

    if sort is not None:
        if not isinstance(sort, dict) or sort.get("field") not in ("created_at", "updated_at", "display_name", "status") or sort.get("direction") not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "sort must be {field, direction} with supported values")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")
    ents = _load("directory_entities.json")

    op_id = _new_id("m365_opr_", ops)
    now = _now()
    kind = "read" if action == "get" else ("search" if action == "list" else ("delete" if action == "delete" else "update"))
    rate_limited = not _rate_limit_allows(tenant_row, ops, 1)
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_intune_macos_compliance",
        "operation_kind": kind,
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "compliance_policy_id": compliance_policy_id,
            "external_id": external_id,
            "body": body,
            "assignments": assignments,
            "filters": filters,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        },
        "target_entity_id": compliance_policy_id if isinstance(compliance_policy_id, str) else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": bool(rate_limited),
        "upstream_provider": "intune",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = 1
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(api_code, msg, err_code=None):
        op_row["status"] = "failed"
        op_row["error_code"] = err_code or api_code
        op_row["error_message"] = msg
        op_row["upstream_request_count"] = 1
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err(api_code, msg, operation_id=op_id)

    def _find_by_id(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("id") == eid and e.get("entity_type") == "intune_compliance_macos"), None)

    def _find_by_external(ext):
        if not isinstance(ext, str) or not ext:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_compliance_macos" and e.get("external_id") == ext), None)

    if action == "list":
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_compliance_macos"]
        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("display_name_contains") is not None:
            q = f["display_name_contains"].lower()
            rows = [e for e in rows if isinstance(e.get("display_name"), str) and q in e["display_name"].lower()]
        if sort is None:
            sort = {"field": "created_at", "direction": "desc"}
        field = sort["field"]
        rev = sort["direction"] == "desc"
        rows.sort(key=lambda e: e.get(field) or "", reverse=rev)
        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        return _finish_success({"items": page, "total": total, "has_more": next_off < total, "next_cursor": _encode_cursor(next_off) if next_off < total else None})

    ent = None
    if compliance_policy_id:
        ent = _find_by_id(compliance_policy_id)
    if ent is None and external_id:
        ent = _find_by_external(external_id)

    if action == "get":
        if not ent:
            return _finish_error("NOT_FOUND", "Compliance policy not found")
        return _finish_success({"compliance_policy": ent})

    if action == "create":
        b = body or {}
        if not b:
            return _finish_error("VALIDATION_ERROR", "body is required for create")
        props = b.get("properties") if isinstance(b.get("properties"), dict) else {}
        ext = external_id if isinstance(external_id, str) and external_id else props.get("external_id")
        if not ext:
            ext = f"IntuneMacCompliance:{uuid.uuid4().hex}"
        existing = _find_by_external(ext)
        if existing:
            return _finish_success({"compliance_policy": existing, "idempotent": True})
        ent = {
            "id": _new_id("m365_ent_", ents),
            "tenant_id": tenant_id,
            "entity_type": "intune_compliance_macos",
            "external_id": ext,
            "display_name": b.get("display_name"),
            "principal_name": None,
            "mail": None,
            "enabled": None,
            "status": "active",
            "properties": props if props else None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        ents.append(ent)
        _save("directory_entities.json", ents)
        op_row["target_entity_id"] = ent["id"]
        _save("operations.json", ops)
        return _finish_success({"compliance_policy": ent})

    if not ent:
        return _finish_error("NOT_FOUND", "Compliance policy not found")

    if action == "update":
        b = body or {}
        if not b:
            return _finish_error("VALIDATION_ERROR", "body is required for update")
        if "display_name" in b:
            ent["display_name"] = b.get("display_name")
        if "properties" in b:
            p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
            p0.update(b.get("properties") or {})
            ent["properties"] = p0
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"compliance_policy": ent})

    if action == "delete":
        if ent.get("status") == "deleted":
            return _finish_success({"compliance_policy": ent, "idempotent": True})
        if ent.get("status") not in ("active", "pending", "error"):
            return _finish_error("INVALID_TRANSITION", "Invalid compliance policy status transition to deleted")
        ent["status"] = "deleted"
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"compliance_policy": ent})

    if action == "assign":
        if assignments is None:
            return _finish_error("VALIDATION_ERROR", "assignments is required for assign")
        p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
        p0["assignments"] = assignments
        ent["properties"] = p0
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"compliance_policy": ent, "assignments": assignments})

    return _finish_error("VALIDATION_ERROR", "Unhandled action")

