        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("operations.json", ops)

    if rate_limited:
        return {"operation": op_row, "rate_limited": True, "result": None}

    op_row["status"] = "running"
    op_row["attempt_count"] = 1
    op_row["started_at"] = _now()
    op_row["updated_at"] = op_row["started_at"]
    op_row["rate_limited"] = False
    _save("operations.json", ops)

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["upstream_request_count"] = 1
        op_row["response_payload"] = payload
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return {"operation": op_row, "result": payload}

    def _finish_error(api_code, msg, err_code=None):
        op_row["status"] = "failed"
        op_row["error_code"] = err_code or api_code
        op_row["error_message"] = msg
        op_row["upstream_request_count"] = 1
        op_row["finished_at"] = _now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err(api_code, msg, operation_id=op_id)

    def _find_by_id(eid):
        if not isinstance(eid, str) or not eid:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("id") == eid and e.get("entity_type") == "intune_device_windows"), None)

    def _find_by_external(ext):
        if not isinstance(ext, str) or not ext:
            return None
        return next((e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_device_windows" and e.get("external_id") == ext), None)

    if action == "list":
        rows = [e for e in ents if isinstance(e, dict) and e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_device_windows"]
        f = filters or {}
        if f.get("status") is not None:
            rows = [e for e in rows if e.get("status") == f.get("status")]
        if f.get("enabled") is not None:
            rows = [e for e in rows if e.get("enabled") == f.get("enabled")]
        if f.get("external_id") is not None:
            rows = [e for e in rows if e.get("external_id") == f.get("external_id")]
        if f.get("principal_name") is not None:
            rows = [e for e in rows if e.get("principal_name") == f.get("principal_name")]
        if f.get("display_name_contains") is not None:
            q = f["display_name_contains"].lower()
            rows = [e for e in rows if isinstance(e.get("display_name"), str) and q in e["display_name"].lower()]
        if sort is None:
            sort = {"field": "created_at", "direction": "desc"}
        field = sort["field"]
        rev = sort["direction"] == "desc"
        rows.sort(key=lambda e: e.get(field) or "", reverse=rev)
        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        return _finish_success({"items": page, "total": total, "has_more": next_off < total, "next_cursor": _encode_cursor(next_off) if next_off < total else None})

    ent = None
    if device_id:
        ent = _find_by_id(device_id)
    if ent is None and external_id:
        ent = _find_by_external(external_id)

    if action == "get":
        if not ent:
            return _finish_error("NOT_FOUND", "Device not found")
        return _finish_success({"device": ent})

    if not ent:
        return _finish_error("NOT_FOUND", "Device not found")

    if action == "update":
        b = body or {}
        if not b:
            return _finish_error("VALIDATION_ERROR", "body is required for update")
        if "display_name" in b:
            ent["display_name"] = b.get("display_name")
        if "enabled" in b:
            ent["enabled"] = b.get("enabled")
        if "properties" in b:
            p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
            p0.update(b.get("properties") or {})
            ent["properties"] = p0
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"device": ent})

    if action == "remote_action":
        if not remote_action:
            return _finish_error("VALIDATION_ERROR", "remote_action is required for remote_action")
        # remote actions recorded in properties.last_remote_action
        p0 = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
        p0["last_remote_action"] = {"action": remote_action, "at": _now(), "parameters": (body or {}).get("properties") if isinstance(body, dict) else None}
        ent["properties"] = p0
        ent["updated_at"] = _now()
        _save("directory_entities.json", ents)
        return _finish_success({"device": ent, "remote_action": p0["last_remote_action"]})

    return _finish_error("VALIDATION_ERROR", "Unhandled action")

def manage_intune_windows_policies(tenant_id, action, policy_id=None, external_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _make_id(prefix):
        # 18+ base32-ish uppercase
        raw = hashlib.sha1(f"{prefix}:{now}:{time.time_ns()}".encode("utf-8")).digest()
        token = base64.b32encode(raw).decode("ascii").rstrip("=").replace("=", "")
        token = re.sub(r"[^0-9A-Z]", "", token)
        if len(token) < 18:
            token = (token + "0" * 18)[:18]
        return f"{prefix}_{token[:22]}"

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            data = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(data)
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _validate():
        if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
            return _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
        if action not in {"list", "get", "create", "update", "delete"}:
            return _err("VALIDATION_ERROR", "action is invalid.", field="action")
        if policy_id is not None and (not isinstance(policy_id, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", policy_id)):
            return _err("VALIDATION_ERROR", "policy_id is invalid.", field="policy_id")
        if external_id is not None and not isinstance(external_id, str):
            return _err("VALIDATION_ERROR", "external_id must be a string.", field="external_id")
        if body is not None:
            if not isinstance(body, dict):
                return _err("VALIDATION_ERROR", "body must be an object.", field="body")
            allowed = {"display_name", "description", "settings", "enabled"}
            for k in body.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "body contains unknown field.", field=f"body.{k}")
            if "display_name" in body and body["display_name"] is not None and not isinstance(body["display_name"], str):
                return _err("VALIDATION_ERROR", "display_name must be a string.", field="body.display_name")
            if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
                return _err("VALIDATION_ERROR", "description must be a string.", field="body.description")
            if "settings" in body and body["settings"] is not None and not isinstance(body["settings"], dict):
                return _err("VALIDATION_ERROR", "settings must be an object.", field="body.settings")
            if "enabled" in body and body["enabled"] is not None and not isinstance(body["enabled"], bool):
                return _err("VALIDATION_ERROR", "enabled must be boolean.", field="body.enabled")
        if filters is not None:
            if not isinstance(filters, dict):
                return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")
            allowed = {"status", "display_name", "external_id"}
            for k in filters.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "filters contains unknown field.", field=f"filters.{k}")
            if "status" in filters and filters["status"] is not None and filters["status"] not in {"active", "pending", "deleted", "error"}:
                return _err("VALIDATION_ERROR", "filters.status is invalid.", field="filters.status")
            if "display_name" in filters and filters["display_name"] is not None and not isinstance(filters["display_name"], str):
                return _err("VALIDATION_ERROR", "filters.display_name must be a string.", field="filters.display_name")
            if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
                return _err("VALIDATION_ERROR", "filters.external_id must be a string.", field="filters.external_id")
        if sort is not None and sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"}:
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if response_format is not None and response_format not in {"json", "text", "table", "raw"}:
            return _err("VALIDATION_ERROR", "response_format is invalid.", field="response_format")
        return None

    # Load datastore
    tenants = _load("tenants.json")
    directory_entities = _load("directory_entities.json")
    operations = _load("operations.json")

    def _tenant_row():
        for t in tenants:
            if t.get("id") == tenant_id:
                return t
        return None

    tenant = _tenant_row()
    if tenant is None:
        # still record operation attempt
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_policies",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": policy_id if policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "NOT_FOUND",
            "error_message": "Tenant not found.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)

    v = _validate()
    if v is not None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_policies",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": policy_id if policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": v["error"]["code"],
            "error_message": v["error"]["message"],
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return v

    if tenant.get("status") != "active":
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_policies",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": policy_id if policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant is not active.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("UNAUTHORIZED", "Tenant is not active.", tenant_status=tenant.get("status"))

    operation_kind = "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    op_id = _make_id("m365_opr")
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_intune_windows_policies",
        "operation_kind": operation_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "policy_id": policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
        "target_entity_id": policy_id if policy_id else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "intune",
        "upstream_request_count": 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op)

    # Rate limit enforcement for queued->running (only for operations that would hit upstream)
    def _upstream_cost():
        if action in {"list", "get"}:
            return 1
        if action in {"create", "update"}:
            return 2
        if action == "delete":
            return 1
        return 1

    def _count_upstream_last_minute():
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        total = 0
        for r in operations:
            if r.get("tenant_id") != tenant_id:
                continue
            started_at = r.get("started_at")
            if not started_at:
                continue
            try:
                ts = datetime.datetime.fromisoformat(started_at.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ts >= cutoff and isinstance(r.get("upstream_request_count"), int):
                total += r.get("upstream_request_count")
        return total

    intended = _upstream_cost()
    used = _count_upstream_last_minute()
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int):
        rl = 60
    if used + intended > rl:
        op["status"] = "queued"
        op["rate_limited"] = True
        op["attempt_count"] = 0
        op["updated_at"] = now
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued.", tenant_id=tenant_id, rate_limit_per_minute=rl, upstream_requests_last_minute=used, upstream_requests_needed=intended, operation_id=op_id)

    # Transition to running
    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = now
    op["updated_at"] = now

    def _find_policy_entity():
        ent = None
        if policy_id:
            for e in directory_entities:
                if e.get("id") == policy_id and e.get("tenant_id") == tenant_id:
                    ent = e
                    break
            if ent and ent.get("entity_type") != "intune_policy_windows":
                return "wrong_type", ent
            return None, ent
        if external_id:
            for e in directory_entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_policy_windows" and e.get("external_id") == external_id:
                    return None, e
            return None, None
        return None, None

    def _canonical_policy_doc(b):
        # Must be valid JSON object stored in properties.policy_document
        if not isinstance(b, dict):
            return None
        settings = b.get("settings")
        if settings is not None and not isinstance(settings, dict):
            return None
        doc = {
            "platform": "windows",
            "displayName": b.get("display_name"),
            "description": b.get("description"),
            "settings": settings or {},
            "enabled": b.get("enabled") if isinstance(b.get("enabled"), bool) else True,
            "generatedAt": now,
        }
        # Validate serializable
        json.dumps(doc, ensure_ascii=False)
        return doc

    result = None
    err = None

    try:
        if action == "list":
            rows = [e for e in directory_entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_policy_windows"]
            if filters:
                if filters.get("status") is not None:
                    rows = [e for e in rows if e.get("status") == filters.get("status")]
                if filters.get("display_name") is not None:
                    q = filters.get("display_name")
                    rows = [e for e in rows if (e.get("display_name") or "") == q or (q.lower() in (e.get("display_name") or "").lower())]
                if filters.get("external_id") is not None:
                    rows = [e for e in rows if e.get("external_id") == filters.get("external_id")]
            total = len(rows)
            s = sort or "created_at"
            rev = s.startswith("-")
            key = s[1:] if rev else s
            def _k(e):
                v = e.get(key)
                return "" if v is None else v
            if key in {"created_at", "updated_at", "display_name"}:
                rows.sort(key=_k, reverse=rev)
            off = _parse_cursor(cursor)
            if off is None:
                err = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            else:
                lim = limit or 50
                page = rows[off:off+lim]
                next_off = off + lim
                has_more = next_off < total
                result = {
                    "operation_id": op_id,
                    "items": page,
                    "meta": {"total": total, "limit": lim, "cursor": cursor, "next_cursor": _make_cursor(next_off) if has_more else None, "has_more": has_more},
                }
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"count": len(page), "total": total}
        elif action == "get":
            code, ent = _find_policy_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "policy_id does not reference an intune_policy_windows entity.", field="policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Policy not found.", policy_id=policy_id, external_id=external_id)
            else:
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id")}
        elif action == "create":
            if not body or not isinstance(body, dict) or not body.get("display_name"):
                err = _err("VALIDATION_ERROR", "body.display_name is required for create.", field="body.display_name")
            else:
                # Unique(tenant_id, entity_type, external_id). If external_id provided, enforce uniqueness.
                if external_id:
                    for e in directory_entities:
                        if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_policy_windows" and e.get("external_id") == external_id:
                            err = _err("CONFLICT", "A policy with this external_id already exists.", external_id=external_id)
                            break
                if err is None:
                    doc = _canonical_policy_doc(body)
                    if doc is None:
                        err = _err("VALIDATION_ERROR", "Invalid policy document (settings must be an object).", field="body.settings")
                    else:
                        ent_id = _make_id("m365_ent")
                        ext_id = external_id or f"intune-pol-{ent_id[-10:]}"
                        created = {
                            "id": ent_id,
                            "tenant_id": tenant_id,
                            "entity_type": "intune_policy_windows",
                            "external_id": ext_id,
                            "display_name": body.get("display_name"),
                            "principal_name": None,
                            "mail": None,
                            "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                            "status": "active",
                            "properties": {"description": body.get("description"), "settings": body.get("settings") or {}, "policy_document": doc},
                            "created_at": now,
                            "updated_at": now,
                        }
                        directory_entities.append(created)
                        _save("directory_entities.json", directory_entities)
                        result = {"operation_id": op_id, "item": created}
                        op["target_entity_id"] = ent_id
                        op["upstream_request_count"] = intended
                        op["status"] = "succeeded"
                        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        op["response_payload"] = {"id": ent_id, "external_id": ext_id}
        elif action == "update":
            code, ent = _find_policy_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "policy_id does not reference an intune_policy_windows entity.", field="policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Policy not found.", policy_id=policy_id, external_id=external_id)
            elif not body:
                err = _err("VALIDATION_ERROR", "body is required for update.", field="body")
            elif ent.get("status") == "deleted":
                err = _err("INVALID_TRANSITION", "Cannot update a deleted policy.", from_status="deleted", to_status="active")
            else:
                # apply updates
                if body.get("display_name") is not None:
                    ent["display_name"] = body.get("display_name")
                if body.get("enabled") is not None:
                    ent["enabled"] = body.get("enabled")
                props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                if body.get("description") is not None:
                    props["description"] = body.get("description")
                if body.get("settings") is not None:
                    props["settings"] = body.get("settings")
                # refresh canonical document (required for succeed)
                doc = _canonical_policy_doc({"display_name": ent.get("display_name"), "description": props.get("description"), "settings": props.get("settings"), "enabled": ent.get("enabled")})
                if doc is None:
                    err = _err("VALIDATION_ERROR", "Invalid policy document after update.", field="body")
                else:
                    props["policy_document"] = doc
                    ent["properties"] = props
                    ent["updated_at"] = now
                    _save("directory_entities.json", directory_entities)
                    result = {"operation_id": op_id, "item": ent}
                    op["target_entity_id"] = ent.get("id")
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent.get("id")}
        elif action == "delete":
            code, ent = _find_policy_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "policy_id does not reference an intune_policy_windows entity.", field="policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Policy not found.", policy_id=policy_id, external_id=external_id)
            elif ent.get("status") == "deleted":
                # idempotent delete
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id"), "deleted": True}
            else:
                # lifecycle active/pending/error -> deleted allowed; deleted -> none
                if ent.get("status") in {"active", "pending", "error"}:
                    ent["status"] = "deleted"
                    ent["updated_at"] = now
                    _save("directory_entities.json", directory_entities)
                    result = {"operation_id": op_id, "item": ent}
                    op["target_entity_id"] = ent.get("id")
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent.get("id"), "deleted": True}
                else:
                    err = _err("INVALID_TRANSITION", "Illegal status transition for delete.", from_status=ent.get("status"), to_status="deleted")
        else:
            err = _err("VALIDATION_ERROR", "Unsupported action.", field="action")
    except Exception as e:
        err = _err("CONFLICT", "Unexpected error during operation.", detail=str(e))

    if err is not None:
        op["status"] = "failed"
        op["error_code"] = err["error"]["code"]
        op["error_message"] = err["error"]["message"]
        op["upstream_request_count"] = op.get("upstream_request_count") or 0
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", operations)
        return err

    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", operations)
    return result

def manage_intune_windows_apps(tenant_id, action, app_id=None, external_id=None, body=None, assignment=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _make_id(prefix):
        raw = hashlib.sha1(f"{prefix}:{now}:{time.time_ns()}".encode("utf-8")).digest()
        token = base64.b32encode(raw).decode("ascii").rstrip("=")
        token = re.sub(r"[^0-9A-Z]", "", token)
        if len(token) < 18:
            token = (token + "0" * 18)[:18]
        return f"{prefix}_{token[:22]}"

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            data = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(data)
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _validate():
        if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
            return _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
        if action not in {"list", "get", "create", "update", "delete", "assign", "unassign"}:
            return _err("VALIDATION_ERROR", "action is invalid.", field="action")
        if app_id is not None and (not isinstance(app_id, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", app_id)):
            return _err("VALIDATION_ERROR", "app_id is invalid.", field="app_id")
        if external_id is not None and not isinstance(external_id, str):
            return _err("VALIDATION_ERROR", "external_id must be a string.", field="external_id")
        if body is not None:
            if not isinstance(body, dict):
                return _err("VALIDATION_ERROR", "body must be an object.", field="body")
            allowed = {"display_name", "description", "properties", "enabled"}
            for k in body.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "body contains unknown field.", field=f"body.{k}")
            if "display_name" in body and body["display_name"] is not None and not isinstance(body["display_name"], str):
                return _err("VALIDATION_ERROR", "display_name must be a string.", field="body.display_name")
            if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
                return _err("VALIDATION_ERROR", "description must be a string.", field="body.description")
            if "properties" in body and body["properties"] is not None and not isinstance(body["properties"], dict):
                return _err("VALIDATION_ERROR", "properties must be an object.", field="body.properties")
            if "enabled" in body and body["enabled"] is not None and not isinstance(body["enabled"], bool):
                return _err("VALIDATION_ERROR", "enabled must be boolean.", field="body.enabled")
        if assignment is not None:
            if not isinstance(assignment, dict):
                return _err("VALIDATION_ERROR", "assignment must be an object.", field="assignment")
            allowed = {"target_entity_id", "target_external_id", "intent"}
            for k in assignment.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "assignment contains unknown field.", field=f"assignment.{k}")
            te = assignment.get("target_entity_id")
            tx = assignment.get("target_external_id")
            if te is not None and (not isinstance(te, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", te)):
                return _err("VALIDATION_ERROR", "assignment.target_entity_id is invalid.", field="assignment.target_entity_id")
            if tx is not None and not isinstance(tx, str):
                return _err("VALIDATION_ERROR", "assignment.target_external_id must be a string.", field="assignment.target_external_id")
            if assignment.get("intent") is not None and assignment.get("intent") not in {"required", "available", "uninstall"}:
                return _err("VALIDATION_ERROR", "assignment.intent is invalid.", field="assignment.intent")
        if filters is not None:
            if not isinstance(filters, dict):
                return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")
            allowed = {"status", "display_name", "external_id"}
            for k in filters.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "filters contains unknown field.", field=f"filters.{k}")
            if "status" in filters and filters["status"] is not None and filters["status"] not in {"active", "pending", "deleted", "error"}:
                return _err("VALIDATION_ERROR", "filters.status is invalid.", field="filters.status")
            if "display_name" in filters and filters["display_name"] is not None and not isinstance(filters["display_name"], str):
                return _err("VALIDATION_ERROR", "filters.display_name must be a string.", field="filters.display_name")
            if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
                return _err("VALIDATION_ERROR", "filters.external_id must be a string.", field="filters.external_id")
        if sort is not None and sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"}:
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if response_format is not None and response_format not in {"json", "text", "table", "raw"}:
            return _err("VALIDATION_ERROR", "response_format is invalid.", field="response_format")
        return None

    tenants = _load("tenants.json")
    directory_entities = _load("directory_entities.json")
    group_memberships = _load("group_memberships.json")
    operations = _load("operations.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if tenant is None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_apps",
            "operation_kind": "read" if action in {"list", "get"} else ("delete" if action == "delete" else ("create" if action == "create" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "app_id": app_id, "external_id": external_id, "assignment": assignment, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": app_id if app_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "NOT_FOUND",
            "error_message": "Tenant not found.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)

    v = _validate()
    if v is not None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_apps",
            "operation_kind": "read" if action in {"list", "get"} else ("delete" if action == "delete" else ("create" if action == "create" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "app_id": app_id, "external_id": external_id, "body": body, "assignment": assignment, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": app_id if app_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": v["error"]["code"],
            "error_message": v["error"]["message"],
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return v

    if tenant.get("status") != "active":
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_apps",
            "operation_kind": "read" if action in {"list", "get"} else ("delete" if action == "delete" else ("create" if action == "create" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "app_id": app_id, "external_id": external_id, "body": body, "assignment": assignment, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": app_id if app_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant is not active.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("UNAUTHORIZED", "Tenant is not active.", tenant_status=tenant.get("status"))

    operation_kind = "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    op_id = _make_id("m365_opr")
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_intune_windows_apps",
        "operation_kind": operation_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "app_id": app_id, "external_id": external_id, "body": body, "assignment": assignment, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
        "target_entity_id": app_id if app_id else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "intune",
        "upstream_request_count": 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op)

    def _upstream_cost():
        if action in {"list", "get"}:
            return 1
        if action in {"create", "update"}:
            return 2
        if action in {"assign", "unassign"}:
            return 1
        if action == "delete":
            return 1
        return 1

    def _count_upstream_last_minute():
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        total = 0
        for r in operations:
            if r.get("tenant_id") != tenant_id:
                continue
            started_at = r.get("started_at")
            if not started_at:
                continue
            try:
                ts = datetime.datetime.fromisoformat(started_at.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ts >= cutoff and isinstance(r.get("upstream_request_count"), int):
                total += r.get("upstream_request_count")
        return total

    intended = _upstream_cost()
    used = _count_upstream_last_minute()
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int):
        rl = 60
    if used + intended > rl:
        op["status"] = "queued"
        op["rate_limited"] = True
        op["updated_at"] = now
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued.", tenant_id=tenant_id, rate_limit_per_minute=rl, upstream_requests_last_minute=used, upstream_requests_needed=intended, operation_id=op_id)

    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = now
    op["updated_at"] = now

    def _find_app_entity():
        ent = None
        if app_id:
            for e in directory_entities:
                if e.get("id") == app_id and e.get("tenant_id") == tenant_id:
                    ent = e
                    break
            if ent and ent.get("entity_type") != "intune_app_windows":
                return "wrong_type", ent
            return None, ent
        if external_id:
            for e in directory_entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_app_windows" and e.get("external_id") == external_id:
                    return None, e
            return None, None
        return None, None

    def _resolve_target_entity(assign_obj):
        if not assign_obj:
            return None, None, None
        tid = assign_obj.get("target_entity_id")
        tex = assign_obj.get("target_external_id")
        if tid:
            trow = next((e for e in directory_entities if e.get("id") == tid and e.get("tenant_id") == tenant_id), None)
            if not trow:
                return _err("NOT_FOUND", "Assignment target_entity_id not found.", target_entity_id=tid), None, None
            return None, trow, tid
        if tex:
            trow = next((e for e in directory_entities if e.get("tenant_id") == tenant_id and e.get("external_id") == tex), None)
            if not trow:
                return _err("NOT_FOUND", "Assignment target_external_id not found in directory_entities.", target_external_id=tex), None, None
            return None, trow, trow.get("id")
        return _err("VALIDATION_ERROR", "Assignment requires target_entity_id or target_external_id.", field="assignment"), None, None

    result = None
    err = None

    try:
        if action == "list":
            rows = [e for e in directory_entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_app_windows"]
            if filters:
                if filters.get("status") is not None:
                    rows = [e for e in rows if e.get("status") == filters.get("status")]
                if filters.get("display_name") is not None:
                    q = filters.get("display_name")
                    rows = [e for e in rows if (e.get("display_name") or "") == q or (q.lower() in (e.get("display_name") or "").lower())]
                if filters.get("external_id") is not None:
                    rows = [e for e in rows if e.get("external_id") == filters.get("external_id")]
            total = len(rows)
            s = sort or "created_at"
            rev = s.startswith("-")
            key = s[1:] if rev else s
            def _k(e):
                v = e.get(key)
                return "" if v is None else v
            if key in {"created_at", "updated_at", "display_name"}:
                rows.sort(key=_k, reverse=rev)
            off = _parse_cursor(cursor)
            if off is None:
                err = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            else:
                lim = limit or 50
                page = rows[off:off+lim]
                next_off = off + lim
                has_more = next_off < total
                result = {
                    "operation_id": op_id,
                    "items": page,
                    "meta": {"total": total, "limit": lim, "cursor": cursor, "next_cursor": _make_cursor(next_off) if has_more else None, "has_more": has_more},
                }
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"count": len(page), "total": total}
        elif action == "get":
            code, ent = _find_app_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "app_id does not reference an intune_app_windows entity.", field="app_id")
            elif ent is None:
                err = _err("NOT_FOUND", "App not found.", app_id=app_id, external_id=external_id)
            else:
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id")}
        elif action == "create":
            if not body or not isinstance(body, dict) or not body.get("display_name"):
                err = _err("VALIDATION_ERROR", "body.display_name is required for create.", field="body.display_name")
            else:
                if external_id:
                    for e in directory_entities:
                        if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_app_windows" and e.get("external_id") == external_id:
                            err = _err("CONFLICT", "An app with this external_id already exists.", external_id=external_id)
                            break
                if err is None:
                    ent_id = _make_id("m365_ent")
                    ext_id = external_id or f"intune-app-{ent_id[-10:]}"
                    created = {
                        "id": ent_id,
                        "tenant_id": tenant_id,
                        "entity_type": "intune_app_windows",
                        "external_id": ext_id,
                        "display_name": body.get("display_name"),
                        "principal_name": None,
                        "mail": None,
                        "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                        "status": "active",
                        "properties": {"description": body.get("description"), "app_properties": body.get("properties") or {}, "assignments": []},
                        "created_at": now,
