                    result = {"operation_id": op_id, "item": created}
                    op["target_entity_id"] = ent_id
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent_id, "external_id": ext_id}
        elif action == "update":
            code, ent = _find_app_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "app_id does not reference an intune_app_windows entity.", field="app_id")
            elif ent is None:
                err = _err("NOT_FOUND", "App not found.", app_id=app_id, external_id=external_id)
            elif not body:
                err = _err("VALIDATION_ERROR", "body is required for update.", field="body")
            elif ent.get("status") == "deleted":
