            elif ent.get("status") == "deleted":
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id"), "deleted": True}
            else:
                if ent.get("status") in {"active", "pending", "error"}:
                    ent["status"] = "deleted"
                    ent["updated_at"] = now
                    _save("directory_entities.json", directory_entities)
                    result = {"operation_id": op_id, "item": ent}
                    op["target_entity_id"] = ent.get("id")
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent.get("id"), "deleted": True}
                else:
                    err = _err("INVALID_TRANSITION", "Illegal status transition for delete.", from_status=ent.get("status"), to_status="deleted")
        elif action in {"assign", "unassign"}:
            code, ent = _find_app_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "app_id does not reference an intune_app_windows entity.", field="app_id")
            elif ent is None:
                err = _err("NOT_FOUND", "App not found.", app_id=app_id, external_id=external_id)
            elif ent.get("status") == "deleted":
                err = _err("INVALID_TRANSITION", "Cannot change assignments for a deleted app.", from_status="deleted")
            else:
                if not assignment or not isinstance(assignment, dict):
                    err = _err("VALIDATION_ERROR", "assignment is required for assign/unassign.", field="assignment")
                else:
                    terr, target_row, target_id = _resolve_target_entity(assignment)
                    if terr:
                        err = terr
                    else:
                        intent = assignment.get("intent")
                        if action == "assign" and not intent:
                            err = _err("VALIDATION_ERROR", "assignment.intent is required for assign.", field="assignment.intent")
                        else:
                            props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                            assns = props.get("assignments")
                            if not isinstance(assns, list):
                                assns = []
                            # store assignment record
                            found = None
                            for a in assns:
                                if isinstance(a, dict) and a.get("target_entity_id") == target_id:
                                    found = a
                                    break
                            if action == "assign":
                                if found:
                                    # idempotent update intent
                                    found["intent"] = intent
                                    found["updated_at"] = now
                                else:
                                    assns.append({"target_entity_id": target_id, "target_external_id": target_row.get("external_id"), "intent": intent, "created_at": now, "updated_at": now})
                                props["assignments"] = assns
                                ent["properties"] = props
                                ent["updated_at"] = now
                                _save("directory_entities.json", directory_entities)
                                result = {"operation_id": op_id, "item": ent, "assignment": {"target_entity_id": target_id, "intent": intent}}
                                op["target_entity_id"] = ent.get("id")
                                op["upstream_request_count"] = intended
                                op["status"] = "succeeded"
                                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                                op["response_payload"] = {"id": ent.get("id"), "assigned_to": target_id, "intent": intent}
                            else:
                                if not found:
                                    err = _err("NOT_FOUND", "Assignment not found to unassign.", target_entity_id=target_id)
                                else:
                                    assns = [a for a in assns if not (isinstance(a, dict) and a.get("target_entity_id") == target_id)]
                                    props["assignments"] = assns
                                    ent["properties"] = props
                                    ent["updated_at"] = now
                                    _save("directory_entities.json", directory_entities)
                                    result = {"operation_id": op_id, "item": ent, "unassigned": {"target_entity_id": target_id}}
                                    op["target_entity_id"] = ent.get("id")
                                    op["upstream_request_count"] = intended
                                    op["status"] = "succeeded"
                                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                                    op["response_payload"] = {"id": ent.get("id"), "unassigned_from": target_id}
        else:
            err = _err("VALIDATION_ERROR", "Unsupported action.", field="action")
    except Exception as e:
        err = _err("CONFLICT", "Unexpected error during operation.", detail=str(e))

    if err is not None:
        op["status"] = "failed"
        op["error_code"] = err["error"]["code"]
        op["error_message"] = err["error"]["message"]
        op["upstream_request_count"] = op.get("upstream_request_count") or 0
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", operations)
        return err

    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", operations)
    return result

def manage_intune_windows_compliance(tenant_id, action, compliance_policy_id=None, external_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _make_id(prefix):
        raw = hashlib.sha1(f"{prefix}:{now}:{time.time_ns()}".encode("utf-8")).digest()
        token = base64.b32encode(raw).decode("ascii").rstrip("=")
        token = re.sub(r"[^0-9A-Z]", "", token)
        if len(token) < 18:
            token = (token + "0" * 18)[:18]
        return f"{prefix}_{token[:22]}"

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            data = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(data)
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _validate():
        if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
            return _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
        if action not in {"list", "get", "create", "update", "delete"}:
            return _err("VALIDATION_ERROR", "action is invalid.", field="action")
        if compliance_policy_id is not None and (not isinstance(compliance_policy_id, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", compliance_policy_id)):
            return _err("VALIDATION_ERROR", "compliance_policy_id is invalid.", field="compliance_policy_id")
        if external_id is not None and not isinstance(external_id, str):
            return _err("VALIDATION_ERROR", "external_id must be a string.", field="external_id")
        if body is not None:
            if not isinstance(body, dict):
                return _err("VALIDATION_ERROR", "body must be an object.", field="body")
            allowed = {"display_name", "description", "requirements", "actions", "enabled"}
            for k in body.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "body contains unknown field.", field=f"body.{k}")
            if "display_name" in body and body["display_name"] is not None and not isinstance(body["display_name"], str):
                return _err("VALIDATION_ERROR", "display_name must be a string.", field="body.display_name")
            if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
                return _err("VALIDATION_ERROR", "description must be a string.", field="body.description")
            if "requirements" in body and body["requirements"] is not None and not isinstance(body["requirements"], dict):
                return _err("VALIDATION_ERROR", "requirements must be an object.", field="body.requirements")
            if "actions" in body and body["actions"] is not None and not isinstance(body["actions"], dict):
                return _err("VALIDATION_ERROR", "actions must be an object.", field="body.actions")
            if "enabled" in body and body["enabled"] is not None and not isinstance(body["enabled"], bool):
                return _err("VALIDATION_ERROR", "enabled must be boolean.", field="body.enabled")
        if filters is not None:
            if not isinstance(filters, dict):
                return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")
            allowed = {"status", "display_name", "external_id"}
            for k in filters.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "filters contains unknown field.", field=f"filters.{k}")
            if "status" in filters and filters["status"] is not None and filters["status"] not in {"active", "pending", "deleted", "error"}:
                return _err("VALIDATION_ERROR", "filters.status is invalid.", field="filters.status")
            if "display_name" in filters and filters["display_name"] is not None and not isinstance(filters["display_name"], str):
                return _err("VALIDATION_ERROR", "filters.display_name must be a string.", field="filters.display_name")
            if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
                return _err("VALIDATION_ERROR", "filters.external_id must be a string.", field="filters.external_id")
        if sort is not None and sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "display_name", "-display_name"}:
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if response_format is not None and response_format not in {"json", "text", "table", "raw"}:
            return _err("VALIDATION_ERROR", "response_format is invalid.", field="response_format")
        return None

    tenants = _load("tenants.json")
    directory_entities = _load("directory_entities.json")
    operations = _load("operations.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if tenant is None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_compliance",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "compliance_policy_id": compliance_policy_id, "external_id": external_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": compliance_policy_id if compliance_policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "NOT_FOUND",
            "error_message": "Tenant not found.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)

    v = _validate()
    if v is not None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_compliance",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "compliance_policy_id": compliance_policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": compliance_policy_id if compliance_policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": v["error"]["code"],
            "error_message": v["error"]["message"],
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return v

    if tenant.get("status") != "active":
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_intune_windows_compliance",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "compliance_policy_id": compliance_policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": compliance_policy_id if compliance_policy_id else None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "intune",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant is not active.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("UNAUTHORIZED", "Tenant is not active.", tenant_status=tenant.get("status"))

    operation_kind = "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    op_id = _make_id("m365_opr")
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_intune_windows_compliance",
        "operation_kind": operation_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "compliance_policy_id": compliance_policy_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
        "target_entity_id": compliance_policy_id if compliance_policy_id else None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "intune",
        "upstream_request_count": 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op)

    def _upstream_cost():
        if action in {"list", "get"}:
            return 1
        if action in {"create", "update"}:
            return 2
        if action == "delete":
            return 1
        return 1

    def _count_upstream_last_minute():
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        total = 0
        for r in operations:
            if r.get("tenant_id") != tenant_id:
                continue
            started_at = r.get("started_at")
            if not started_at:
                continue
            try:
                ts = datetime.datetime.fromisoformat(started_at.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ts >= cutoff and isinstance(r.get("upstream_request_count"), int):
                total += r.get("upstream_request_count")
        return total

    intended = _upstream_cost()
    used = _count_upstream_last_minute()
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int):
        rl = 60
    if used + intended > rl:
        op["status"] = "queued"
        op["rate_limited"] = True
        op["updated_at"] = now
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued.", tenant_id=tenant_id, rate_limit_per_minute=rl, upstream_requests_last_minute=used, upstream_requests_needed=intended, operation_id=op_id)

    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = now
    op["updated_at"] = now

    def _find_entity():
        ent = None
        if compliance_policy_id:
            for e in directory_entities:
                if e.get("id") == compliance_policy_id and e.get("tenant_id") == tenant_id:
                    ent = e
                    break
            if ent and ent.get("entity_type") != "intune_compliance_windows":
                return "wrong_type", ent
            return None, ent
        if external_id:
            for e in directory_entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_compliance_windows" and e.get("external_id") == external_id:
                    return None, e
            return None, None
        return None, None

    result = None
    err = None

    try:
        if action == "list":
            rows = [e for e in directory_entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_compliance_windows"]
            if filters:
                if filters.get("status") is not None:
                    rows = [e for e in rows if e.get("status") == filters.get("status")]
                if filters.get("display_name") is not None:
                    q = filters.get("display_name")
                    rows = [e for e in rows if (e.get("display_name") or "") == q or (q.lower() in (e.get("display_name") or "").lower())]
                if filters.get("external_id") is not None:
                    rows = [e for e in rows if e.get("external_id") == filters.get("external_id")]
            total = len(rows)
            s = sort or "created_at"
            rev = s.startswith("-")
            key = s[1:] if rev else s
            def _k(e):
                v = e.get(key)
                return "" if v is None else v
            if key in {"created_at", "updated_at", "display_name"}:
                rows.sort(key=_k, reverse=rev)
            off = _parse_cursor(cursor)
            if off is None:
                err = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            else:
                lim = limit or 50
                page = rows[off:off+lim]
                next_off = off + lim
                has_more = next_off < total
                result = {"operation_id": op_id, "items": page, "meta": {"total": total, "limit": lim, "cursor": cursor, "next_cursor": _make_cursor(next_off) if has_more else None, "has_more": has_more}}
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"count": len(page), "total": total}
        elif action == "get":
            code, ent = _find_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "compliance_policy_id does not reference an intune_compliance_windows entity.", field="compliance_policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Compliance policy not found.", compliance_policy_id=compliance_policy_id, external_id=external_id)
            else:
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id")}
        elif action == "create":
            if not body or not isinstance(body, dict) or not body.get("display_name"):
                err = _err("VALIDATION_ERROR", "body.display_name is required for create.", field="body.display_name")
            else:
                if external_id:
                    for e in directory_entities:
                        if e.get("tenant_id") == tenant_id and e.get("entity_type") == "intune_compliance_windows" and e.get("external_id") == external_id:
                            err = _err("CONFLICT", "A compliance policy with this external_id already exists.", external_id=external_id)
                            break
                if err is None:
                    ent_id = _make_id("m365_ent")
                    ext_id = external_id or f"intune-cmp-{ent_id[-10:]}"
                    created = {
                        "id": ent_id,
                        "tenant_id": tenant_id,
                        "entity_type": "intune_compliance_windows",
                        "external_id": ext_id,
                        "display_name": body.get("display_name"),
                        "principal_name": None,
                        "mail": None,
                        "enabled": body.get("enabled") if isinstance(body.get("enabled"), bool) else None,
                        "status": "active",
                        "properties": {
                            "description": body.get("description"),
                            "requirements": body.get("requirements") or {},
                            "actions": body.get("actions") or {},
                        },
                        "created_at": now,
                        "updated_at": now,
                    }
                    directory_entities.append(created)
                    _save("directory_entities.json", directory_entities)
                    result = {"operation_id": op_id, "item": created}
                    op["target_entity_id"] = ent_id
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent_id, "external_id": ext_id}
        elif action == "update":
            code, ent = _find_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "compliance_policy_id does not reference an intune_compliance_windows entity.", field="compliance_policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Compliance policy not found.", compliance_policy_id=compliance_policy_id, external_id=external_id)
            elif not body:
                err = _err("VALIDATION_ERROR", "body is required for update.", field="body")
            elif ent.get("status") == "deleted":
                err = _err("INVALID_TRANSITION", "Cannot update a deleted compliance policy.", from_status="deleted")
            else:
                if body.get("display_name") is not None:
                    ent["display_name"] = body.get("display_name")
                if body.get("enabled") is not None:
                    ent["enabled"] = body.get("enabled")
                props = ent.get("properties") if isinstance(ent.get("properties"), dict) else {}
                if body.get("description") is not None:
                    props["description"] = body.get("description")
                if body.get("requirements") is not None:
                    props["requirements"] = body.get("requirements")
                if body.get("actions") is not None:
                    props["actions"] = body.get("actions")
                ent["properties"] = props
                ent["updated_at"] = now
                _save("directory_entities.json", directory_entities)
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id")}
        elif action == "delete":
            code, ent = _find_entity()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "compliance_policy_id does not reference an intune_compliance_windows entity.", field="compliance_policy_id")
            elif ent is None:
                err = _err("NOT_FOUND", "Compliance policy not found.", compliance_policy_id=compliance_policy_id, external_id=external_id)
            elif ent.get("status") == "deleted":
                result = {"operation_id": op_id, "item": ent}
                op["target_entity_id"] = ent.get("id")
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": ent.get("id"), "deleted": True}
            else:
                if ent.get("status") in {"active", "pending", "error"}:
                    ent["status"] = "deleted"
                    ent["updated_at"] = now
                    _save("directory_entities.json", directory_entities)
                    result = {"operation_id": op_id, "item": ent}
                    op["target_entity_id"] = ent.get("id")
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": ent.get("id"), "deleted": True}
                else:
                    err = _err("INVALID_TRANSITION", "Illegal status transition for delete.", from_status=ent.get("status"), to_status="deleted")
        else:
            err = _err("VALIDATION_ERROR", "Unsupported action.", field="action")
    except Exception as e:
        err = _err("CONFLICT", "Unexpected error during operation.", detail=str(e))

    if err is not None:
        op["status"] = "failed"
        op["error_code"] = err["error"]["code"]
        op["error_message"] = err["error"]["message"]
        op["upstream_request_count"] = op.get("upstream_request_count") or 0
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", operations)
        return err

    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", operations)
    return result

def manage_compliance_frameworks(tenant_id, action, framework_id=None, external_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _make_id(prefix):
        raw = hashlib.sha1(f"{prefix}:{now}:{time.time_ns()}".encode("utf-8")).digest()
        token = base64.b32encode(raw).decode("ascii").rstrip("=")
        token = re.sub(r"[^0-9A-Z]", "", token)
        if len(token) < 18:
            token = (token + "0" * 18)[:18]
        return f"{prefix}_{token[:22]}"

    def _parse_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            data = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(data)
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _validate():
        if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
            return _err("VALIDATION_ERROR", "tenant_id is invalid.", field="tenant_id")
        if action not in {"list", "get", "create", "update", "delete"}:
            return _err("VALIDATION_ERROR", "action is invalid.", field="action")
        if framework_id is not None and (not isinstance(framework_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", framework_id)):
            return _err("VALIDATION_ERROR", "framework_id is invalid.", field="framework_id")
        if external_id is not None and not isinstance(external_id, str):
            return _err("VALIDATION_ERROR", "external_id must be a string.", field="external_id")
        if body is not None:
            if not isinstance(body, dict):
                return _err("VALIDATION_ERROR", "body must be an object.", field="body")
            allowed = {"name", "status", "details"}
            for k in body.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "body contains unknown field.", field=f"body.{k}")
            if "name" in body and body["name"] is not None and not isinstance(body["name"], str):
                return _err("VALIDATION_ERROR", "name must be a string.", field="body.name")
            if "status" in body and body["status"] is not None and body["status"] not in {"draft", "active", "running", "completed", "archived", "failed"}:
                return _err("VALIDATION_ERROR", "status is invalid.", field="body.status")
            if "details" in body and body["details"] is not None and not isinstance(body["details"], dict):
                return _err("VALIDATION_ERROR", "details must be an object.", field="body.details")
        if filters is not None:
            if not isinstance(filters, dict):
                return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")
            allowed = {"status", "name", "external_id"}
            for k in filters.keys():
                if k not in allowed:
                    return _err("VALIDATION_ERROR", "filters contains unknown field.", field=f"filters.{k}")
            if "status" in filters and filters["status"] is not None and filters["status"] not in {"draft", "active", "running", "completed", "archived", "failed"}:
                return _err("VALIDATION_ERROR", "filters.status is invalid.", field="filters.status")
            if "name" in filters and filters["name"] is not None and not isinstance(filters["name"], str):
                return _err("VALIDATION_ERROR", "filters.name must be a string.", field="filters.name")
            if "external_id" in filters and filters["external_id"] is not None and not isinstance(filters["external_id"], str):
                return _err("VALIDATION_ERROR", "filters.external_id must be a string.", field="filters.external_id")
        if sort is not None and sort not in {"created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"}:
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if response_format is not None and response_format not in {"json", "text", "table", "raw"}:
            return _err("VALIDATION_ERROR", "response_format is invalid.", field="response_format")
        return None

    tenants = _load("tenants.json")
    compliance_records = _load("compliance_records.json")
    operations = _load("operations.json")

    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if tenant is None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_compliance_frameworks",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "framework_id": framework_id, "external_id": external_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "other",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "NOT_FOUND",
            "error_message": "Tenant not found.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Tenant not found.", tenant_id=tenant_id)

    v = _validate()
    if v is not None:
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_compliance_frameworks",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "framework_id": framework_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "other",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": v["error"]["code"],
            "error_message": v["error"]["message"],
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return v

    if tenant.get("status") != "active":
        op = {
            "id": _make_id("m365_opr"),
            "tenant_id": tenant_id,
            "tool_name": "manage_compliance_frameworks",
            "operation_kind": "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update")),
            "request_payload": {"tenant_id": tenant_id, "action": action, "framework_id": framework_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
            "target_entity_id": None,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "rate_limited": False,
            "upstream_provider": "other",
            "upstream_request_count": 0,
            "response_format": response_format or "json",
            "response_payload": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant is not active.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return _err("UNAUTHORIZED", "Tenant is not active.", tenant_status=tenant.get("status"))

    operation_kind = "read" if action in {"list", "get"} else ("create" if action == "create" else ("delete" if action == "delete" else "update"))
    op_id = _make_id("m365_opr")
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_compliance_frameworks",
        "operation_kind": operation_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "framework_id": framework_id, "external_id": external_id, "body": body, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op)

    # Rate limiting uses tenant.rate_limit_per_minute against upstream_request_count across operations
    def _upstream_cost():
        if action in {"list", "get"}:
            return 0
        if action in {"create", "update", "delete"}:
            return 0
        return 0

    def _count_upstream_last_minute():
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        total = 0
        for r in operations:
            if r.get("tenant_id") != tenant_id:
                continue
            started_at = r.get("started_at")
            if not started_at:
                continue
            try:
                ts = datetime.datetime.fromisoformat(started_at.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if ts >= cutoff and isinstance(r.get("upstream_request_count"), int):
                total += r.get("upstream_request_count")
        return total

    intended = _upstream_cost()
    used = _count_upstream_last_minute()
    rl = tenant.get("rate_limit_per_minute")
    if not isinstance(rl, int):
        rl = 60
    if used + intended > rl:
        op["status"] = "queued"
        op["rate_limited"] = True
        op["updated_at"] = now
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; operation queued.", tenant_id=tenant_id, rate_limit_per_minute=rl, upstream_requests_last_minute=used, upstream_requests_needed=intended, operation_id=op_id)

    op["status"] = "running"
    op["attempt_count"] = 1
    op["started_at"] = now
    op["updated_at"] = now

    def _find_framework():
        rec = None
        if framework_id:
            for r in compliance_records:
                if r.get("id") == framework_id and r.get("tenant_id") == tenant_id:
                    rec = r
                    break
            if rec and rec.get("record_type") != "framework":
                return "wrong_type", rec
            return None, rec
        if external_id:
            for r in compliance_records:
                if r.get("tenant_id") == tenant_id and r.get("record_type") == "framework" and r.get("external_id") == external_id:
                    return None, r
            return None, None
        return None, None

    transitions = {
        "draft": {"active", "archived"},
        "active": {"running", "archived"},
        "running": {"completed", "failed", "archived"},
        "completed": {"archived"},
        "failed": {"running", "archived"},
        "archived": set(),
    }

    result = None
    err = None

    try:
        if action == "list":
            rows = [r for r in compliance_records if r.get("tenant_id") == tenant_id and r.get("record_type") == "framework"]
            if filters:
                if filters.get("status") is not None:
                    rows = [r for r in rows if r.get("status") == filters.get("status")]
                if filters.get("name") is not None:
                    q = filters.get("name")
                    rows = [r for r in rows if (r.get("name") or "") == q or (q.lower() in (r.get("name") or "").lower())]
                if filters.get("external_id") is not None:
                    rows = [r for r in rows if r.get("external_id") == filters.get("external_id")]
            total = len(rows)
            s = sort or "created_at"
            rev = s.startswith("-")
            key = s[1:] if rev else s
            def _k(r):
                v = r.get(key)
                return "" if v is None else v
            if key in {"created_at", "updated_at", "name"}:
                rows.sort(key=_k, reverse=rev)
            off = _parse_cursor(cursor)
            if off is None:
                err = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            else:
                lim = limit or 50
                page = rows[off:off+lim]
                next_off = off + lim
                has_more = next_off < total
                result = {"operation_id": op_id, "items": page, "meta": {"total": total, "limit": lim, "cursor": cursor, "next_cursor": _make_cursor(next_off) if has_more else None, "has_more": has_more}}
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"count": len(page), "total": total}
        elif action == "get":
            code, rec = _find_framework()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "framework_id does not reference a framework record.", field="framework_id")
            elif rec is None:
                err = _err("NOT_FOUND", "Framework not found.", framework_id=framework_id, external_id=external_id)
            else:
                result = {"operation_id": op_id, "item": rec}
                op["upstream_request_count"] = intended
                op["status"] = "succeeded"
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["response_payload"] = {"id": rec.get("id")}
        elif action == "create":
            if not body or not isinstance(body, dict) or not body.get("name"):
                err = _err("VALIDATION_ERROR", "body.name is required for create.", field="body.name")
            else:
                # unique(tenant_id, record_type, external_id) where external_id not null
                if external_id:
                    for r in compliance_records:
                        if r.get("tenant_id") == tenant_id and r.get("record_type") == "framework" and r.get("external_id") == external_id:
                            err = _err("CONFLICT", "A framework with this external_id already exists.", external_id=external_id)
                            break
                if err is None:
                    rec_id = _make_id("m365_cmp")
                    created = {
                        "id": rec_id,
                        "tenant_id": tenant_id,
                        "record_type": "framework",
                        "external_id": external_id,
                        "name": body.get("name"),
                        "status": body.get("status") or "draft",
                        "parent_record_id": None,
                        "related_operation_id": op_id,
                        "score": None,
                        "severity": None,
                        "details": body.get("details") or {},
                        "created_at": now,
                        "updated_at": now,
                    }
                    compliance_records.append(created)
                    _save("compliance_records.json", compliance_records)
                    result = {"operation_id": op_id, "item": created}
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": rec_id}
        elif action == "update":
            code, rec = _find_framework()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "framework_id does not reference a framework record.", field="framework_id")
            elif rec is None:
                err = _err("NOT_FOUND", "Framework not found.", framework_id=framework_id, external_id=external_id)
            elif not body:
                err = _err("VALIDATION_ERROR", "body is required for update.", field="body")
            else:
                # status lifecycle transition if provided
                if body.get("status") is not None:
                    cur = rec.get("status")
                    nxt = body.get("status")
                    if cur not in transitions or nxt not in transitions:
                        err = _err("VALIDATION_ERROR", "Invalid status value.", field="body.status")
                    elif nxt != cur and nxt not in transitions.get(cur, set()):
                        err = _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=nxt)
                if err is None:
                    if body.get("name") is not None:
                        rec["name"] = body.get("name")
                    if body.get("details") is not None:
                        rec["details"] = body.get("details")
                    if body.get("status") is not None:
                        rec["status"] = body.get("status")
                    rec["related_operation_id"] = op_id
                    rec["updated_at"] = now
                    _save("compliance_records.json", compliance_records)
                    result = {"operation_id": op_id, "item": rec}
                    op["upstream_request_count"] = intended
                    op["status"] = "succeeded"
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": rec.get("id")}
        elif action == "delete":
            code, rec = _find_framework()
            if code == "wrong_type":
                err = _err("VALIDATION_ERROR", "framework_id does not reference a framework record.", field="framework_id")
            elif rec is None:
                err = _err("NOT_FOUND", "Framework not found.", framework_id=framework_id, external_id=external_id)
            else:
                # Treat delete as transition to archived (idempotent if already archived)
                cur = rec.get("status")
                if cur == "archived":
                    result = {"operation_id": op_id, "item": rec}
                    op["status"] = "succeeded"
                    op["upstream_request_count"] = intended
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["response_payload"] = {"id": rec.get("id"), "archived": True}
                else:
                    if "archived" not in transitions.get(cur, set()):
                        err = _err("INVALID_TRANSITION", "Cannot delete (archive) framework from current status.", from_status=cur, to_status="archived")
                    else:
                        rec["status"] = "archived"
                        rec["related_operation_id"] = op_id
                        rec["updated_at"] = now
                        _save("compliance_records.json", compliance_records)
                        result = {"operation_id": op_id, "item": rec}
                        op["status"] = "succeeded"
                        op["upstream_request_count"] = intended
                        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        op["response_payload"] = {"id": rec.get("id"), "archived": True}
        else:
            err = _err("VALIDATION_ERROR", "Unsupported action.", field="action")
    except Exception as e:
        err = _err("CONFLICT", "Unexpected error during operation.", detail=str(e))

    if err is not None:
        op["status"] = "failed"
        op["error_code"] = err["error"]["code"]
        op["error_message"] = err["error"]["message"]
        op["upstream_request_count"] = op.get("upstream_request_count") or 0
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _save("operations.json", operations)
        return err

    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", operations)
    return result

def manage_compliance_assessments(tenant_id, action, assessment_id=None, framework_id=None, body=None, run=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int(time.time() * 1000)
        s = ""
        while x > 0 and len(s) < 18:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(18, "0")
        return f"{prefix}_{s}"

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _fmt(rec, fmt):
        if fmt in (None, "json", "raw"):
            return rec
        if fmt == "text":
            return (
                f"id={rec.get('id')}\n"
                f"tenant_id={rec.get('tenant_id')}\n"
                f"record_type={rec.get('record_type')}\n"
                f"name={rec.get('name')}\n"
                f"status={rec.get('status')}\n"
                f"score={rec.get('score')}\n"
                f"parent_record_id={rec.get('parent_record_id')}\n"
                f"related_operation_id={rec.get('related_operation_id')}\n"
                f"created_at={rec.get('created_at')}\n"
                f"updated_at={rec.get('updated_at')}"
            )
        if fmt == "table":
            return [{
                "id": rec.get("id"),
                "name": rec.get("name"),
                "status": rec.get("status"),
                "score": rec.get("score"),
                "framework_id": rec.get("parent_record_id"),
                "updated_at": rec.get("updated_at"),
            }]
        return rec

    def _log_operation(operations, tenants, op_row):
        # Rate limit against operations that are transitioning queued->running (we simulate transition here).
        tenant = next((t for t in tenants if t.get("id") == op_row.get("tenant_id")), None)
        if not tenant:
            return None, _err("NOT_FOUND", "Tenant not found", tenant_id=op_row.get("tenant_id"))

        # Even if tenant suspended, allow read/list/get but block mutations/workflows
        if tenant.get("status") != "active" and op_row.get("operation_kind") in ("create", "update", "delete", "workflow", "report"):
            return None, _err("UNAUTHORIZED", "Tenant is not active for mutating operations", tenant_status=tenant.get("status"))

        # simulate queued->running check
        rl = int(tenant.get("rate_limit_per_minute") or 60)
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        recent = 0
        for o in operations:
            if o.get("tenant_id") != tenant["id"]:
                continue
            sa = o.get("started_at")
            if not sa:
                continue
            try:
                dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                try:
                    recent += int(o.get("upstream_request_count") or 0)
                except Exception:
                    pass
        projected = recent + int(op_row.get("upstream_request_count") or 0)
        if projected > rl:
            op_row["rate_limited"] = True
            # keep queued; do not start
            op_row["status"] = "queued"
            op_row["started_at"] = None
            op_row["finished_at"] = None
        else:
            op_row["rate_limited"] = False
            op_row["status"] = "running"
            op_row["started_at"] = now
            op_row["finished_at"] = None

        operations.append(op_row)
        return tenant, None

    # Validate required params
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id")
    if action not in ("list", "get", "create", "update", "delete", "run"):
        return _err("VALIDATION_ERROR", "Invalid action")
    if response_format is not None and response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "Invalid limit")
    if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name", "score", "-score"):
        return _err("VALIDATION_ERROR", "Invalid sort")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor")

    if assessment_id is not None:
        if not isinstance(assessment_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", assessment_id):
            return _err("VALIDATION_ERROR", "Invalid assessment_id")
    if framework_id is not None:
        if not isinstance(framework_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", framework_id):
            return _err("VALIDATION_ERROR", "Invalid framework_id")

    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "Invalid body")
    if run is not None and not isinstance(run, dict):
        return _err("VALIDATION_ERROR", "Invalid run")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "Invalid filters")

    # Validate body keys strictly (additionalProperties false)
    if isinstance(body, dict):
        for k in body.keys():
            if k not in ("name", "status", "details"):
                return _err("VALIDATION_ERROR", f"Unknown field in body: {k}")
        if "status" in body and body["status"] is not None and body["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid body.status")
        if "name" in body and body["name"] is not None and not isinstance(body["name"], str):
            return _err("VALIDATION_ERROR", "Invalid body.name")
        if "details" in body and body["details"] is not None and not isinstance(body["details"], dict):
            return _err("VALIDATION_ERROR", "Invalid body.details")

    if isinstance(run, dict):
        for k in run.keys():
            if k not in ("assessment_run_name", "details"):
                return _err("VALIDATION_ERROR", f"Unknown field in run: {k}")
        if "assessment_run_name" in run and run["assessment_run_name"] is not None and not isinstance(run["assessment_run_name"], str):
            return _err("VALIDATION_ERROR", "Invalid run.assessment_run_name")
        if "details" in run and run["details"] is not None and not isinstance(run["details"], dict):
            return _err("VALIDATION_ERROR", "Invalid run.details")

    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in ("status", "name", "framework_id"):
                return _err("VALIDATION_ERROR", f"Unknown field in filters: {k}")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid filters.status")
        if "name" in filters and filters["name"] is not None and not isinstance(filters["name"], str):
            return _err("VALIDATION_ERROR", "Invalid filters.name")
        if "framework_id" in filters and filters["framework_id"] is not None:
            if not isinstance(filters["framework_id"], str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", filters["framework_id"]):
                return _err("VALIDATION_ERROR", "Invalid filters.framework_id")

    tenants = _load("tenants.json")
    operations = _load("operations.json")
    compliance = _load("compliance_records.json")

    # Create operation row for every call
    op_id = _new_id("m365_opr")
    op_kind = "read" if action in ("list", "get") else ("workflow" if action == "run" else ("create" if action == "create" else ("update" if action == "update" else "delete")))
    req_payload = {
        "tenant_id": tenant_id,
        "action": action,
        "assessment_id": assessment_id,
        "framework_id": framework_id,
        "filters": filters,
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
        "response_format": response_format,
        "body": body,
        "run": run,
    }
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_compliance_assessments",
        "operation_kind": op_kind,
        "request_payload": req_payload,
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 1 if action in ("create", "update", "delete", "run") else 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    tenant, auth_err = _log_operation(operations, tenants, op_row)
    if auth_err:
        # persist log
        _save("operations.json", operations)
        return auth_err

    # If rate limited, persist queued op and return rate limit error
    if op_row["status"] == "queued" and op_row.get("rate_limited"):
        op_row["error_code"] = "RATE_LIMIT"
        op_row["error_message"] = "Tenant rate limit exceeded; operation queued"
        op_row["updated_at"] = now
        op_row["response_payload"] = {"queued": True}
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; try again later", operation_id=op_id)

    # Proceed "running"
    op_row["attempt_count"] = 1
    op_row["updated_at"] = now

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = payload
        _save("operations.json", operations)

    def _finish_failure(code, msg, **extra):
        op_row["status"] = "failed"
        op_row["error_code"] = code
        op_row["error_message"] = msg
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = {"error": {"code": code, "message": msg, **extra}}
        _save("operations.json", operations)
        return {"error": {"code": code, "message": msg, **extra}}

    # Helper for compliance record transitions
    transitions = {
        "draft": ["active", "archived"],
        "active": ["running", "archived"],
        "running": ["completed", "failed", "archived"],
        "completed": ["archived"],
        "failed": ["running", "archived"],
        "archived": [],
    }

    def _sort_key(rec, field):
        v = rec.get(field)
        if v is None:
            return ""
        return v

    # Action handlers
    if action == "list":
        rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"]
        if filters:
            if filters.get("status") is not None:
                rows = [r for r in rows if r.get("status") == filters["status"]]
            if filters.get("name") is not None:
                q = filters["name"].lower()
                rows = [r for r in rows if (r.get("name") or "").lower().find(q) != -1]
            if filters.get("framework_id") is not None:
                rows = [r for r in rows if r.get("parent_record_id") == filters["framework_id"]]
        total = len(rows)
        if sort:
            desc = sort.startswith("-")
            key = sort[1:] if desc else sort
            if key in ("created_at", "updated_at", "name"):
                rows.sort(key=lambda r: _sort_key(r, key), reverse=desc)
            elif key == "score":
                rows.sort(key=lambda r: (r.get("score") is None, r.get("score") if r.get("score") is not None else 0), reverse=desc)
        off = _parse_cursor(cursor)
        if off is None:
            return _finish_failure("VALIDATION_ERROR", "Invalid cursor") or _err("VALIDATION_ERROR", "Invalid cursor")
        lim = limit or 50
        page = rows[off:off + lim]
        next_off = off + len(page)
        has_more = next_off < total
        out_rows = [_fmt(r, response_format) for r in page]
        payload = {"data": out_rows, "meta": {"total": total, "limit": lim, "cursor": cursor, "has_more": has_more, "next_cursor": _make_cursor(next_off) if has_more else None}, "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "get":
        if not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "assessment_id is required for get") or _err("VALIDATION_ERROR", "assessment_id is required for get")
        rec = next((r for r in compliance if r.get("id") == assessment_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "create":
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for create") or _err("VALIDATION_ERROR", "body is required for create")
        if not framework_id:
            return _finish_failure("VALIDATION_ERROR", "framework_id is required for create") or _err("VALIDATION_ERROR", "framework_id is required for create")
        fw = next((r for r in compliance if r.get("id") == framework_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "framework"), None)
        if not fw:
            return _finish_failure("NOT_FOUND", "Framework not found", framework_id=framework_id) or _err("NOT_FOUND", "Framework not found", framework_id=framework_id)

        rec_id = _new_id("m365_cmp")
        rec = {
            "id": rec_id,
            "tenant_id": tenant_id,
            "record_type": "assessment",
            "external_id": None,
            "name": body.get("name"),
            "status": body.get("status") or "draft",
            "parent_record_id": framework_id,
            "related_operation_id": op_id,
            "score": None,
            "severity": None,
            "details": body.get("details"),
            "created_at": now,
            "updated_at": now,
        }
        compliance.append(rec)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "update":
        if not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "assessment_id is required for update") or _err("VALIDATION_ERROR", "assessment_id is required for update")
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for update") or _err("VALIDATION_ERROR", "body is required for update")
        rec = next((r for r in compliance if r.get("id") == assessment_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)

        # optional framework change
        if framework_id is not None:
            fw = next((r for r in compliance if r.get("id") == framework_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "framework"), None)
            if not fw:
                return _finish_failure("NOT_FOUND", "Framework not found", framework_id=framework_id) or _err("NOT_FOUND", "Framework not found", framework_id=framework_id)
            rec["parent_record_id"] = framework_id

        if "status" in body and body["status"] is not None:
            cur = rec.get("status")
            nxt = body["status"]
            if nxt != cur:
                allowed = transitions.get(cur, [])
                if nxt not in allowed:
                    return _finish_failure("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt) or _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt)
                rec["status"] = nxt
        if "name" in body and body["name"] is not None:
            rec["name"] = body["name"]
        if "details" in body:
            rec["details"] = body.get("details")

        rec["related_operation_id"] = op_id
        rec["updated_at"] = now
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "delete":
        if not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "assessment_id is required for delete") or _err("VALIDATION_ERROR", "assessment_id is required for delete")
        idx = None
        for i, r in enumerate(compliance):
            if r.get("id") == assessment_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment":
                idx = i
                break
        if idx is None:
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
        deleted = compliance.pop(idx)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(deleted, response_format), "deleted": True, "operation_id": op_id}
        _finish_success(payload)
        return payload

    # run
    if action == "run":
        if not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "assessment_id is required for run") or _err("VALIDATION_ERROR", "assessment_id is required for run")
        assess = next((r for r in compliance if r.get("id") == assessment_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"), None)
        if not assess:
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
        if assess.get("status") not in ("active", "failed", "completed"):
            return _finish_failure("INVALID_TRANSITION", "Assessment must be active/failed/completed to start a run", status=assess.get("status")) or _err("INVALID_TRANSITION", "Assessment must be active/failed/completed to start a run", status=assess.get("status"))

        # Create assessment_run record (requires related_operation_id not null)
        run_id = _new_id("m365_cmp")
        run_name = None
        run_details = None
        if isinstance(run, dict):
            run_name = run.get("assessment_run_name")
            run_details = run.get("details")
        run_rec = {
            "id": run_id,
            "tenant_id": tenant_id,
            "record_type": "assessment_run",
            "external_id": None,
            "name": run_name or f"Run of {assess.get('name') or assessment_id}",
            "status": "running",
            "parent_record_id": assessment_id,
            "related_operation_id": op_id,
            "score": None,
            "severity": None,
            "details": run_details or {},
            "created_at": now,
            "updated_at": now,
        }

        # Update assessment status to running if legal
        cur = assess.get("status")
        if cur != "running":
            allowed = transitions.get(cur, [])
            if "running" not in allowed:
                return _finish_failure("INVALID_TRANSITION", f"Illegal status transition {cur} -> running", from_status=cur, to_status="running") or _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> running", from_status=cur, to_status="running")
            assess["status"] = "running"
            assess["related_operation_id"] = op_id
            assess["updated_at"] = now

        # Simulate scoring deterministically from record content (no upstream).
        # Compute score 0..100 based on presence of details keys.
        det = assess.get("details") if isinstance(assess.get("details"), dict) else {}
        kcount = len(det.keys())
        score = float(min(100, kcount * 10))
        run_rec["score"] = score
        run_rec["status"] = "completed"
        run_rec["updated_at"] = now

        assess["score"] = score
        # running -> completed transition must be legal
        if "completed" not in transitions.get("running", []):
            return _finish_failure("INVALID_TRANSITION", "Internal transition invalid for assessment completion") or _err("INVALID_TRANSITION", "Internal transition invalid for assessment completion")
        assess["status"] = "completed"
        assess["updated_at"] = now

        compliance.append(run_rec)
        _save("compliance_records.json", compliance)
        payload = {"data": {"assessment": _fmt(assess, response_format), "assessment_run": _fmt(run_rec, response_format)}, "operation_id": op_id}
        _finish_success(payload)
        return payload

    return _finish_failure("VALIDATION_ERROR", "Unsupported action") or _err("VALIDATION_ERROR", "Unsupported action")

def manage_compliance_monitoring(tenant_id, action, monitor_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int(time.time() * 1000)
        s = ""
        while x > 0 and len(s) < 18:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(18, "0")
        return f"{prefix}_{s}"

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _fmt(rec, fmt):
        if fmt in (None, "json", "raw"):
            return rec
        if fmt == "text":
            return (
                f"id={rec.get('id')}\n"
                f"tenant_id={rec.get('tenant_id')}\n"
                f"record_type={rec.get('record_type')}\n"
                f"name={rec.get('name')}\n"
                f"status={rec.get('status')}\n"
                f"severity={rec.get('severity')}\n"
                f"created_at={rec.get('created_at')}\n"
                f"updated_at={rec.get('updated_at')}"
            )
        if fmt == "table":
            return [{
                "id": rec.get("id"),
                "name": rec.get("name"),
                "status": rec.get("status"),
                "severity": rec.get("severity"),
                "updated_at": rec.get("updated_at"),
            }]
        return rec

    def _rate_and_log(operations, tenants, op_row):
        tenant = next((t for t in tenants if t.get("id") == op_row.get("tenant_id")), None)
        if not tenant:
            return None, _err("NOT_FOUND", "Tenant not found", tenant_id=op_row.get("tenant_id"))
        if tenant.get("status") != "active" and op_row.get("operation_kind") in ("create", "update", "delete", "workflow", "report"):
            return None, _err("UNAUTHORIZED", "Tenant is not active for mutating operations", tenant_status=tenant.get("status"))

        rl = int(tenant.get("rate_limit_per_minute") or 60)
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        recent = 0
        for o in operations:
            if o.get("tenant_id") != tenant["id"]:
                continue
            sa = o.get("started_at")
            if not sa:
                continue
            try:
                dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += int(o.get("upstream_request_count") or 0)
        if recent + int(op_row.get("upstream_request_count") or 0) > rl:
            op_row["rate_limited"] = True
            op_row["status"] = "queued"
            op_row["started_at"] = None
            op_row["finished_at"] = None
        else:
            op_row["rate_limited"] = False
            op_row["status"] = "running"
            op_row["started_at"] = now
            op_row["finished_at"] = None
        operations.append(op_row)
        return tenant, None

    # Validate
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id")
    if action not in ("list", "get", "create", "update", "delete"):
        return _err("VALIDATION_ERROR", "Invalid action")
    if response_format is not None and response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "Invalid limit")
    if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name", "severity", "-severity"):
        return _err("VALIDATION_ERROR", "Invalid sort")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if monitor_id is not None and (not isinstance(monitor_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", monitor_id)):
        return _err("VALIDATION_ERROR", "Invalid monitor_id")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "Invalid body")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "Invalid filters")

    if isinstance(body, dict):
        for k in body.keys():
            if k not in ("name", "status", "severity", "details"):
                return _err("VALIDATION_ERROR", f"Unknown field in body: {k}")
        if "status" in body and body["status"] is not None and body["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid body.status")
        if "severity" in body and body["severity"] is not None and body["severity"] not in ("low", "medium", "high", "critical"):
            return _err("VALIDATION_ERROR", "Invalid body.severity")
        if "name" in body and body["name"] is not None and not isinstance(body["name"], str):
            return _err("VALIDATION_ERROR", "Invalid body.name")
        if "details" in body and body["details"] is not None and not isinstance(body["details"], dict):
            return _err("VALIDATION_ERROR", "Invalid body.details")

    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in ("status", "severity", "name"):
                return _err("VALIDATION_ERROR", f"Unknown field in filters: {k}")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid filters.status")
        if "severity" in filters and filters["severity"] is not None and filters["severity"] not in ("low", "medium", "high", "critical"):
            return _err("VALIDATION_ERROR", "Invalid filters.severity")
        if "name" in filters and filters["name"] is not None and not isinstance(filters["name"], str):
            return _err("VALIDATION_ERROR", "Invalid filters.name")

    tenants = _load("tenants.json")
    operations = _load("operations.json")
    compliance = _load("compliance_records.json")

    op_id = _new_id("m365_opr")
    op_kind = "read" if action in ("list", "get") else ("create" if action == "create" else ("update" if action == "update" else "delete"))
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_compliance_monitoring",
        "operation_kind": op_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "monitor_id": monitor_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format, "body": body},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 1 if action in ("create", "update", "delete") else 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tenant, auth_err = _rate_and_log(operations, tenants, op_row)
    if auth_err:
        _save("operations.json", operations)
        return auth_err
    if op_row["status"] == "queued" and op_row.get("rate_limited"):
        op_row["error_code"] = "RATE_LIMIT"
        op_row["error_message"] = "Tenant rate limit exceeded; operation queued"
        op_row["updated_at"] = now
        op_row["response_payload"] = {"queued": True}
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; try again later", operation_id=op_id)

    op_row["attempt_count"] = 1
    op_row["updated_at"] = now

    transitions = {
        "draft": ["active", "archived"],
        "active": ["running", "archived"],
        "running": ["completed", "failed", "archived"],
        "completed": ["archived"],
        "failed": ["running", "archived"],
        "archived": [],
    }

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = payload
        _save("operations.json", operations)

    def _finish_failure(code, msg, **extra):
        op_row["status"] = "failed"
        op_row["error_code"] = code
        op_row["error_message"] = msg
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = {"error": {"code": code, "message": msg, **extra}}
        _save("operations.json", operations)
        return {"error": {"code": code, "message": msg, **extra}}

    if action == "list":
        rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "monitor"]
        if filters:
            if filters.get("status") is not None:
                rows = [r for r in rows if r.get("status") == filters["status"]]
            if filters.get("severity") is not None:
                rows = [r for r in rows if r.get("severity") == filters["severity"]]
            if filters.get("name") is not None:
                q = filters["name"].lower()
                rows = [r for r in rows if (r.get("name") or "").lower().find(q) != -1]
        total = len(rows)
        if sort:
            desc = sort.startswith("-")
            key = sort[1:] if desc else sort
            if key in ("created_at", "updated_at", "name", "severity"):
                rows.sort(key=lambda r: (r.get(key) is None, r.get(key) or ""), reverse=desc)
        off = _parse_cursor(cursor)
        if off is None:
            return _finish_failure("VALIDATION_ERROR", "Invalid cursor") or _err("VALIDATION_ERROR", "Invalid cursor")
        lim = limit or 50
        page = rows[off:off + lim]
        next_off = off + len(page)
        has_more = next_off < total
        payload = {"data": [_fmt(r, response_format) for r in page], "meta": {"total": total, "limit": lim, "cursor": cursor, "has_more": has_more, "next_cursor": _make_cursor(next_off) if has_more else None}, "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "get":
        if not monitor_id:
            return _finish_failure("VALIDATION_ERROR", "monitor_id is required for get") or _err("VALIDATION_ERROR", "monitor_id is required for get")
        rec = next((r for r in compliance if r.get("id") == monitor_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "monitor"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Monitor not found", monitor_id=monitor_id) or _err("NOT_FOUND", "Monitor not found", monitor_id=monitor_id)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "create":
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for create") or _err("VALIDATION_ERROR", "body is required for create")
        rec_id = _new_id("m365_cmp")
        rec = {
            "id": rec_id,
            "tenant_id": tenant_id,
            "record_type": "monitor",
            "external_id": None,
            "name": body.get("name"),
            "status": body.get("status") or "draft",
            "parent_record_id": None,
            "related_operation_id": op_id,
            "score": None,
            "severity": body.get("severity"),
            "details": body.get("details"),
            "created_at": now,
            "updated_at": now,
        }
        compliance.append(rec)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "update":
        if not monitor_id:
            return _finish_failure("VALIDATION_ERROR", "monitor_id is required for update") or _err("VALIDATION_ERROR", "monitor_id is required for update")
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for update") or _err("VALIDATION_ERROR", "body is required for update")
        rec = next((r for r in compliance if r.get("id") == monitor_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "monitor"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Monitor not found", monitor_id=monitor_id) or _err("NOT_FOUND", "Monitor not found", monitor_id=monitor_id)

        if "status" in body and body["status"] is not None:
            cur = rec.get("status")
            nxt = body["status"]
            if nxt != cur:
                if nxt not in transitions.get(cur, []):
                    return _finish_failure("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt) or _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt)
                rec["status"] = nxt
        if "name" in body and body["name"] is not None:
            rec["name"] = body["name"]
        if "severity" in body:
            rec["severity"] = body.get("severity")
        if "details" in body:
            rec["details"] = body.get("details")

        rec["related_operation_id"] = op_id
        rec["updated_at"] = now
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "delete":
        if not monitor_id:
            return _finish_failure("VALIDATION_ERROR", "monitor_id is required for delete") or _err("VALIDATION_ERROR", "monitor_id is required for delete")
        idx = None
        for i, r in enumerate(compliance):
            if r.get("id") == monitor_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "monitor":
                idx = i
                break
        if idx is None:
            return _finish_failure("NOT_FOUND", "Monitor not found", monitor_id=monitor_id) or _err("NOT_FOUND", "Monitor not found", monitor_id=monitor_id)
        deleted = compliance.pop(idx)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(deleted, response_format), "deleted": True, "operation_id": op_id}
        _finish_success(payload)
        return payload

    return _finish_failure("VALIDATION_ERROR", "Unsupported action") or _err("VALIDATION_ERROR", "Unsupported action")

def manage_evidence_collection(tenant_id, action, evidence_id=None, assessment_id=None, related_operation_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int(time.time() * 1000)
        s = ""
        while x > 0 and len(s) < 18:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(18, "0")
        return f"{prefix}_{s}"

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _fmt(rec, fmt):
        if fmt in (None, "json", "raw"):
            return rec
        if fmt == "text":
            return (
                f"id={rec.get('id')}\n"
                f"tenant_id={rec.get('tenant_id')}\n"
                f"record_type={rec.get('record_type')}\n"
                f"name={rec.get('name')}\n"
                f"status={rec.get('status')}\n"
                f"severity={rec.get('severity')}\n"
                f"parent_record_id={rec.get('parent_record_id')}\n"
                f"related_operation_id={rec.get('related_operation_id')}\n"
                f"created_at={rec.get('created_at')}\n"
                f"updated_at={rec.get('updated_at')}"
            )
        if fmt == "table":
            return [{
                "id": rec.get("id"),
                "name": rec.get("name"),
                "status": rec.get("status"),
                "assessment_id": rec.get("parent_record_id"),
                "related_operation_id": rec.get("related_operation_id"),
                "updated_at": rec.get("updated_at"),
            }]
        return rec

    def _rate_and_log(operations, tenants, op_row):
        tenant = next((t for t in tenants if t.get("id") == op_row.get("tenant_id")), None)
        if not tenant:
            return None, _err("NOT_FOUND", "Tenant not found", tenant_id=op_row.get("tenant_id"))
        if tenant.get("status") != "active" and op_row.get("operation_kind") in ("create", "update", "delete", "workflow", "report"):
            return None, _err("UNAUTHORIZED", "Tenant is not active for mutating operations", tenant_status=tenant.get("status"))

        rl = int(tenant.get("rate_limit_per_minute") or 60)
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        recent = 0
        for o in operations:
            if o.get("tenant_id") != tenant["id"]:
                continue
            sa = o.get("started_at")
            if not sa:
                continue
            try:
                dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += int(o.get("upstream_request_count") or 0)
        if recent + int(op_row.get("upstream_request_count") or 0) > rl:
            op_row["rate_limited"] = True
            op_row["status"] = "queued"
            op_row["started_at"] = None
            op_row["finished_at"] = None
        else:
            op_row["rate_limited"] = False
            op_row["status"] = "running"
            op_row["started_at"] = now
            op_row["finished_at"] = None
        operations.append(op_row)
        return tenant, None

    # Validate
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id")
    if action not in ("list", "get", "create", "update", "delete", "validate"):
        return _err("VALIDATION_ERROR", "Invalid action")
    if response_format is not None and response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "Invalid limit")
    if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
        return _err("VALIDATION_ERROR", "Invalid sort")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if evidence_id is not None and (not isinstance(evidence_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", evidence_id)):
        return _err("VALIDATION_ERROR", "Invalid evidence_id")
    if assessment_id is not None and (not isinstance(assessment_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", assessment_id)):
        return _err("VALIDATION_ERROR", "Invalid assessment_id")
    if related_operation_id is not None and (not isinstance(related_operation_id, str) or not re.match(r"^m365_opr_[0-9A-Z]{18,}$", related_operation_id)):
        return _err("VALIDATION_ERROR", "Invalid related_operation_id")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "Invalid body")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "Invalid filters")

    if isinstance(body, dict):
        for k in body.keys():
            if k not in ("name", "status", "details", "severity"):
                return _err("VALIDATION_ERROR", f"Unknown field in body: {k}")
        if "status" in body and body["status"] is not None and body["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid body.status")
        if "severity" in body and body["severity"] is not None and body["severity"] not in ("low", "medium", "high", "critical"):
            return _err("VALIDATION_ERROR", "Invalid body.severity")
        if "name" in body and body["name"] is not None and not isinstance(body["name"], str):
            return _err("VALIDATION_ERROR", "Invalid body.name")
        if "details" in body and body["details"] is not None and not isinstance(body["details"], dict):
            return _err("VALIDATION_ERROR", "Invalid body.details")

    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in ("status", "name", "assessment_id", "related_operation_id"):
                return _err("VALIDATION_ERROR", f"Unknown field in filters: {k}")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid filters.status")
        if "name" in filters and filters["name"] is not None and not isinstance(filters["name"], str):
            return _err("VALIDATION_ERROR", "Invalid filters.name")
        if "assessment_id" in filters and filters["assessment_id"] is not None:
            if not isinstance(filters["assessment_id"], str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", filters["assessment_id"]):
                return _err("VALIDATION_ERROR", "Invalid filters.assessment_id")
        if "related_operation_id" in filters and filters["related_operation_id"] is not None:
            if not isinstance(filters["related_operation_id"], str) or not re.match(r"^m365_opr_[0-9A-Z]{18,}$", filters["related_operation_id"]):
                return _err("VALIDATION_ERROR", "Invalid filters.related_operation_id")

    tenants = _load("tenants.json")
    operations = _load("operations.json")
    compliance = _load("compliance_records.json")

    op_id = _new_id("m365_opr")
    op_kind = "read" if action in ("list", "get") else ("update" if action == "validate" else ("create" if action == "create" else ("update" if action == "update" else "delete")))
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_evidence_collection",
        "operation_kind": op_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "evidence_id": evidence_id, "assessment_id": assessment_id, "related_operation_id": related_operation_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format, "body": body},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 1 if action in ("create", "update", "delete", "validate") else 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tenant, auth_err = _rate_and_log(operations, tenants, op_row)
    if auth_err:
        _save("operations.json", operations)
        return auth_err
    if op_row["status"] == "queued" and op_row.get("rate_limited"):
        op_row["error_code"] = "RATE_LIMIT"
        op_row["error_message"] = "Tenant rate limit exceeded; operation queued"
        op_row["updated_at"] = now
        op_row["response_payload"] = {"queued": True}
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; try again later", operation_id=op_id)

    op_row["attempt_count"] = 1
    op_row["updated_at"] = now

    transitions = {
        "draft": ["active", "archived"],
        "active": ["running", "archived"],
        "running": ["completed", "failed", "archived"],
        "completed": ["archived"],
        "failed": ["running", "archived"],
        "archived": [],
    }

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = payload
        _save("operations.json", operations)

    def _finish_failure(code, msg, **extra):
        op_row["status"] = "failed"
        op_row["error_code"] = code
        op_row["error_message"] = msg
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = {"error": {"code": code, "message": msg, **extra}}
        _save("operations.json", operations)
        return {"error": {"code": code, "message": msg, **extra}}

    def _find_op(opid):
        return next((o for o in operations if o.get("id") == opid and o.get("tenant_id") == tenant_id), None)

    def _find_assessment(aid):
        return next((r for r in compliance if r.get("id") == aid and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"), None)

    if action == "list":
        rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "evidence"]
        if filters:
            if filters.get("status") is not None:
                rows = [r for r in rows if r.get("status") == filters["status"]]
            if filters.get("name") is not None:
                q = filters["name"].lower()
                rows = [r for r in rows if (r.get("name") or "").lower().find(q) != -1]
            if filters.get("assessment_id") is not None:
                rows = [r for r in rows if r.get("parent_record_id") == filters["assessment_id"]]
            if filters.get("related_operation_id") is not None:
                rows = [r for r in rows if r.get("related_operation_id") == filters["related_operation_id"]]
        total = len(rows)
        if sort:
            desc = sort.startswith("-")
            key = sort[1:] if desc else sort
            rows.sort(key=lambda r: (r.get(key) is None, r.get(key) or ""), reverse=desc)
        off = _parse_cursor(cursor)
        if off is None:
            return _finish_failure("VALIDATION_ERROR", "Invalid cursor") or _err("VALIDATION_ERROR", "Invalid cursor")
        lim = limit or 50
        page = rows[off:off + lim]
        next_off = off + len(page)
        has_more = next_off < total
        payload = {"data": [_fmt(r, response_format) for r in page], "meta": {"total": total, "limit": lim, "cursor": cursor, "has_more": has_more, "next_cursor": _make_cursor(next_off) if has_more else None}, "operation_id": op_id}
        _finish_success(payload)
