        if not rec:
            return _finish_failure("NOT_FOUND", "Evidence not found", evidence_id=evidence_id) or _err("NOT_FOUND", "Evidence not found", evidence_id=evidence_id)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "create":
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for create") or _err("VALIDATION_ERROR", "body is required for create")
        if not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "assessment_id is required for create") or _err("VALIDATION_ERROR", "assessment_id is required for create")
        parent = _find_assessment(assessment_id)
        if not parent:
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
        if related_operation_id is not None and not _find_op(related_operation_id):
            return _finish_failure("NOT_FOUND", "related_operation_id not found", related_operation_id=related_operation_id) or _err("NOT_FOUND", "related_operation_id not found", related_operation_id=related_operation_id)

        rec_id = _new_id("m365_cmp")
        rec = {
            "id": rec_id,
            "tenant_id": tenant_id,
            "record_type": "evidence",
            "external_id": None,
            "name": body.get("name"),
            "status": body.get("status") or "draft",
            "parent_record_id": assessment_id,
            "related_operation_id": related_operation_id or op_id,
            "score": None,
            "severity": body.get("severity"),
            "details": body.get("details"),
            "created_at": now,
            "updated_at": now,
        }
        compliance.append(rec)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "update":
        if not evidence_id:
            return _finish_failure("VALIDATION_ERROR", "evidence_id is required for update") or _err("VALIDATION_ERROR", "evidence_id is required for update")
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for update") or _err("VALIDATION_ERROR", "body is required for update")
        rec = next((r for r in compliance if r.get("id") == evidence_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "evidence"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Evidence not found", evidence_id=evidence_id) or _err("NOT_FOUND", "Evidence not found", evidence_id=evidence_id)
        if assessment_id is not None:
            parent = _find_assessment(assessment_id)
            if not parent:
                return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
            rec["parent_record_id"] = assessment_id
        if related_operation_id is not None:
            if not _find_op(related_operation_id):
                return _finish_failure("NOT_FOUND", "related_operation_id not found", related_operation_id=related_operation_id) or _err("NOT_FOUND", "related_operation_id not found", related_operation_id=related_operation_id)
            rec["related_operation_id"] = related_operation_id

        if "status" in body and body["status"] is not None:
            cur = rec.get("status")
            nxt = body["status"]
            if nxt != cur:
                if nxt not in transitions.get(cur, []):
                    return _finish_failure("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt) or _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt)
                rec["status"] = nxt
        if "name" in body and body["name"] is not None:
            rec["name"] = body["name"]
        if "severity" in body:
            rec["severity"] = body.get("severity")
        if "details" in body:
            rec["details"] = body.get("details")

        rec["updated_at"] = now
        rec["related_operation_id"] = rec.get("related_operation_id") or op_id
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "delete":
        if not evidence_id:
            return _finish_failure("VALIDATION_ERROR", "evidence_id is required for delete") or _err("VALIDATION_ERROR", "evidence_id is required for delete")
        idx = None
        for i, r in enumerate(compliance):
            if r.get("id") == evidence_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "evidence":
                idx = i
                break
        if idx is None:
            return _finish_failure("NOT_FOUND", "Evidence not found", evidence_id=evidence_id) or _err("NOT_FOUND", "Evidence not found", evidence_id=evidence_id)
        deleted = compliance.pop(idx)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(deleted, response_format), "deleted": True, "operation_id": op_id}
        _finish_success(payload)
        return payload

    # validate
    if action == "validate":
        if not evidence_id:
            return _finish_failure("VALIDATION_ERROR", "evidence_id is required for validate") or _err("VALIDATION_ERROR", "evidence_id is required for validate")
        rec = next((r for r in compliance if r.get("id") == evidence_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "evidence"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Evidence not found", evidence_id=evidence_id) or _err("NOT_FOUND", "Evidence not found", evidence_id=evidence_id)

        details = rec.get("details")
        ok = isinstance(details, dict) and (("source" in details) or ("links" in details) or ("artifacts" in details))
        # Store validation notes in details.validation
        if not isinstance(details, dict):
            details = {}
        v = details.get("validation")
        if not isinstance(v, dict):
            v = {}
        v["validated_at"] = now
        v["validated_by_operation_id"] = op_id
        v["result"] = "pass" if ok else "fail"
        v["reason"] = None if ok else "Evidence details missing expected keys: one of source/links/artifacts"
        details["validation"] = v
        rec["details"] = details

        # If pass and currently draft/running, mark active or completed accordingly (legal transitions only)
        if ok:
            cur = rec.get("status")
            if cur == "draft" and "active" in transitions.get("draft", []):
                rec["status"] = "active"
            elif cur == "running" and "completed" in transitions.get("running", []):
                rec["status"] = "completed"
        else:
            cur = rec.get("status")
            if cur == "running" and "failed" in transitions.get("running", []):
                rec["status"] = "failed"

        rec["related_operation_id"] = rec.get("related_operation_id") or op_id
        rec["updated_at"] = now
        _save("compliance_records.json", compliance)
        payload = {"data": {"evidence": _fmt(rec, response_format), "validation": v}, "operation_id": op_id}
        _finish_success(payload)
        return payload

    return _finish_failure("VALIDATION_ERROR", "Unsupported action") or _err("VALIDATION_ERROR", "Unsupported action")

def manage_gap_analysis(tenant_id, action, gap_item_id=None, framework_id=None, assessment_id=None, body=None, filters=None, sort=None, limit=None, cursor=None, response_format=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int(time.time() * 1000)
        s = ""
        while x > 0 and len(s) < 18:
            x, r = divmod(x, 36)
            s = alphabet[r] + s
        s = (s or "0").rjust(18, "0")
        return f"{prefix}_{s}"

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _fmt(rec, fmt):
        if fmt in (None, "json", "raw"):
            return rec
        if fmt == "text":
            return (
                f"id={rec.get('id')}\n"
                f"tenant_id={rec.get('tenant_id')}\n"
                f"record_type={rec.get('record_type')}\n"
                f"name={rec.get('name')}\n"
                f"status={rec.get('status')}\n"
                f"severity={rec.get('severity')}\n"
                f"score={rec.get('score')}\n"
                f"parent_record_id={rec.get('parent_record_id')}\n"
                f"created_at={rec.get('created_at')}\n"
                f"updated_at={rec.get('updated_at')}"
            )
        if fmt == "table":
            return [{
                "id": rec.get("id"),
                "name": rec.get("name"),
                "status": rec.get("status"),
                "severity": rec.get("severity"),
                "score": rec.get("score"),
                "framework_id": rec.get("parent_record_id"),
                "updated_at": rec.get("updated_at"),
            }]
        return rec

    def _rate_and_log(operations, tenants, op_row):
        tenant = next((t for t in tenants if t.get("id") == op_row.get("tenant_id")), None)
        if not tenant:
            return None, _err("NOT_FOUND", "Tenant not found", tenant_id=op_row.get("tenant_id"))
        if tenant.get("status") != "active" and op_row.get("operation_kind") in ("create", "update", "delete", "workflow", "report"):
            return None, _err("UNAUTHORIZED", "Tenant is not active for mutating operations", tenant_status=tenant.get("status"))

        rl = int(tenant.get("rate_limit_per_minute") or 60)
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        recent = 0
        for o in operations:
            if o.get("tenant_id") != tenant["id"]:
                continue
            sa = o.get("started_at")
            if not sa:
                continue
            try:
                dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += int(o.get("upstream_request_count") or 0)
        if recent + int(op_row.get("upstream_request_count") or 0) > rl:
            op_row["rate_limited"] = True
            op_row["status"] = "queued"
            op_row["started_at"] = None
            op_row["finished_at"] = None
        else:
            op_row["rate_limited"] = False
            op_row["status"] = "running"
            op_row["started_at"] = now
            op_row["finished_at"] = None
        operations.append(op_row)
        return tenant, None

    # Validate base
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id")
    if action not in ("list", "get", "create", "update", "delete"):
        return _err("VALIDATION_ERROR", "Invalid action")
    if response_format is not None and response_format not in ("json", "text", "table", "raw"):
        return _err("VALIDATION_ERROR", "Invalid response_format")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "Invalid limit")
    if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "severity", "-severity", "score", "-score", "name", "-name"):
        return _err("VALIDATION_ERROR", "Invalid sort")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if gap_item_id is not None and (not isinstance(gap_item_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", gap_item_id)):
        return _err("VALIDATION_ERROR", "Invalid gap_item_id")
    if framework_id is not None and (not isinstance(framework_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", framework_id)):
        return _err("VALIDATION_ERROR", "Invalid framework_id")
    if assessment_id is not None and (not isinstance(assessment_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", assessment_id)):
        return _err("VALIDATION_ERROR", "Invalid assessment_id")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "Invalid body")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "Invalid filters")

    if isinstance(body, dict):
        for k in body.keys():
            if k not in ("name", "status", "severity", "score", "details"):
                return _err("VALIDATION_ERROR", f"Unknown field in body: {k}")
        if "status" in body and body["status"] is not None and body["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid body.status")
        if "severity" in body and body["severity"] is not None and body["severity"] not in ("low", "medium", "high", "critical"):
            return _err("VALIDATION_ERROR", "Invalid body.severity")
        if "score" in body and body["score"] is not None and not isinstance(body["score"], (int, float)):
            return _err("VALIDATION_ERROR", "Invalid body.score")
        if "score" in body and isinstance(body.get("score"), (int, float)) and (body["score"] < 0 or body["score"] > 100):
            return _err("VALIDATION_ERROR", "body.score must be between 0 and 100")
        if "name" in body and body["name"] is not None and not isinstance(body["name"], str):
            return _err("VALIDATION_ERROR", "Invalid body.name")
        if "details" in body and body["details"] is not None and not isinstance(body["details"], dict):
            return _err("VALIDATION_ERROR", "Invalid body.details")

    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in ("status", "severity", "framework_id", "assessment_id"):
                return _err("VALIDATION_ERROR", f"Unknown field in filters: {k}")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("draft", "active", "running", "completed", "archived", "failed"):
            return _err("VALIDATION_ERROR", "Invalid filters.status")
        if "severity" in filters and filters["severity"] is not None and filters["severity"] not in ("low", "medium", "high", "critical"):
            return _err("VALIDATION_ERROR", "Invalid filters.severity")
        if "framework_id" in filters and filters["framework_id"] is not None:
            if not isinstance(filters["framework_id"], str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", filters["framework_id"]):
                return _err("VALIDATION_ERROR", "Invalid filters.framework_id")
        if "assessment_id" in filters and filters["assessment_id"] is not None:
            if not isinstance(filters["assessment_id"], str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", filters["assessment_id"]):
                return _err("VALIDATION_ERROR", "Invalid filters.assessment_id")

    tenants = _load("tenants.json")
    operations = _load("operations.json")
    compliance = _load("compliance_records.json")

    op_id = _new_id("m365_opr")
    op_kind = "read" if action in ("list", "get") else ("create" if action == "create" else ("update" if action == "update" else "delete"))
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_gap_analysis",
        "operation_kind": op_kind,
        "request_payload": {"tenant_id": tenant_id, "action": action, "gap_item_id": gap_item_id, "framework_id": framework_id, "assessment_id": assessment_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor, "response_format": response_format, "body": body},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 1 if action in ("create", "update", "delete") else 0,
        "response_format": response_format or "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tenant, auth_err = _rate_and_log(operations, tenants, op_row)
    if auth_err:
        _save("operations.json", operations)
        return auth_err
    if op_row["status"] == "queued" and op_row.get("rate_limited"):
        op_row["error_code"] = "RATE_LIMIT"
        op_row["error_message"] = "Tenant rate limit exceeded; operation queued"
        op_row["updated_at"] = now
        op_row["response_payload"] = {"queued": True}
        _save("operations.json", operations)
        return _err("RATE_LIMIT", "Tenant rate limit exceeded; try again later", operation_id=op_id)

    op_row["attempt_count"] = 1
    op_row["updated_at"] = now

    transitions = {
        "draft": ["active", "archived"],
        "active": ["running", "archived"],
        "running": ["completed", "failed", "archived"],
        "completed": ["archived"],
        "failed": ["running", "archived"],
        "archived": [],
    }

    def _finish_success(payload):
        op_row["status"] = "succeeded"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = payload
        _save("operations.json", operations)

    def _finish_failure(code, msg, **extra):
        op_row["status"] = "failed"
        op_row["error_code"] = code
        op_row["error_message"] = msg
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        op_row["response_payload"] = {"error": {"code": code, "message": msg, **extra}}
        _save("operations.json", operations)
        return {"error": {"code": code, "message": msg, **extra}}

    def _framework_exists(fid):
        return next((r for r in compliance if r.get("id") == fid and r.get("tenant_id") == tenant_id and r.get("record_type") == "framework"), None)

    def _assessment_exists(aid):
        return next((r for r in compliance if r.get("id") == aid and r.get("tenant_id") == tenant_id and r.get("record_type") == "assessment"), None)

    if action == "list":
        rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "gap_item"]
        if filters:
            if filters.get("status") is not None:
                rows = [r for r in rows if r.get("status") == filters["status"]]
            if filters.get("severity") is not None:
                rows = [r for r in rows if r.get("severity") == filters["severity"]]
            if filters.get("framework_id") is not None:
                fid = filters["framework_id"]
                rows = [r for r in rows if r.get("parent_record_id") == fid or (isinstance(r.get("details"), dict) and r["details"].get("framework_id") == fid)]
            if filters.get("assessment_id") is not None:
                aid = filters["assessment_id"]
                rows = [r for r in rows if (isinstance(r.get("details"), dict) and r["details"].get("assessment_id") == aid)]
        total = len(rows)
        if sort:
            desc = sort.startswith("-")
            key = sort[1:] if desc else sort
            if key in ("created_at", "updated_at", "name", "severity"):
                rows.sort(key=lambda r: (r.get(key) is None, r.get(key) or ""), reverse=desc)
            elif key == "score":
                rows.sort(key=lambda r: (r.get("score") is None, r.get("score") if r.get("score") is not None else 0), reverse=desc)

        off = _parse_cursor(cursor)
        if off is None:
            return _finish_failure("VALIDATION_ERROR", "Invalid cursor") or _err("VALIDATION_ERROR", "Invalid cursor")
        lim = limit or 50
        page = rows[off:off + lim]
        next_off = off + len(page)
        has_more = next_off < total
        payload = {"data": [_fmt(r, response_format) for r in page], "meta": {"total": total, "limit": lim, "cursor": cursor, "has_more": has_more, "next_cursor": _make_cursor(next_off) if has_more else None}, "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "get":
        if not gap_item_id:
            return _finish_failure("VALIDATION_ERROR", "gap_item_id is required for get") or _err("VALIDATION_ERROR", "gap_item_id is required for get")
        rec = next((r for r in compliance if r.get("id") == gap_item_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "gap_item"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id) or _err("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "create":
        # Per tool description: raise VALIDATION_ERROR when required identifiers missing.
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for create") or _err("VALIDATION_ERROR", "body is required for create")
        if not framework_id and not assessment_id:
            return _finish_failure("VALIDATION_ERROR", "framework_id or assessment_id is required for create") or _err("VALIDATION_ERROR", "framework_id or assessment_id is required for create")
        if framework_id and not _framework_exists(framework_id):
            return _finish_failure("NOT_FOUND", "Framework not found", framework_id=framework_id) or _err("NOT_FOUND", "Framework not found", framework_id=framework_id)
        if assessment_id and not _assessment_exists(assessment_id):
            return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)

        rec_id = _new_id("m365_cmp")
        details = body.get("details") if isinstance(body.get("details"), dict) else (body.get("details") if body.get("details") is None else None)
        if details is None and body.get("details") is not None:
            return _finish_failure("VALIDATION_ERROR", "body.details must be an object") or _err("VALIDATION_ERROR", "body.details must be an object")
        if details is None:
            details = {}
        if framework_id:
            details.setdefault("framework_id", framework_id)
        if assessment_id:
            details.setdefault("assessment_id", assessment_id)

        rec = {
            "id": rec_id,
            "tenant_id": tenant_id,
            "record_type": "gap_item",
            "external_id": None,
            "name": body.get("name"),
            "status": body.get("status") or "draft",
            "parent_record_id": framework_id,
            "related_operation_id": op_id,
            "score": body.get("score"),
            "severity": body.get("severity"),
            "details": details,
            "created_at": now,
            "updated_at": now,
        }
        compliance.append(rec)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "update":
        if not gap_item_id:
            return _finish_failure("VALIDATION_ERROR", "gap_item_id is required for update") or _err("VALIDATION_ERROR", "gap_item_id is required for update")
        if body is None:
            return _finish_failure("VALIDATION_ERROR", "body is required for update") or _err("VALIDATION_ERROR", "body is required for update")
        rec = next((r for r in compliance if r.get("id") == gap_item_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "gap_item"), None)
        if not rec:
            return _finish_failure("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id) or _err("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id)

        if framework_id is not None:
            if not _framework_exists(framework_id):
                return _finish_failure("NOT_FOUND", "Framework not found", framework_id=framework_id) or _err("NOT_FOUND", "Framework not found", framework_id=framework_id)
            rec["parent_record_id"] = framework_id
            if isinstance(rec.get("details"), dict):
                rec["details"]["framework_id"] = framework_id
        if assessment_id is not None:
            if not _assessment_exists(assessment_id):
                return _finish_failure("NOT_FOUND", "Assessment not found", assessment_id=assessment_id) or _err("NOT_FOUND", "Assessment not found", assessment_id=assessment_id)
            if not isinstance(rec.get("details"), dict) or rec.get("details") is None:
                rec["details"] = {}
            rec["details"]["assessment_id"] = assessment_id

        if "status" in body and body["status"] is not None:
            cur = rec.get("status")
            nxt = body["status"]
            if nxt != cur:
                if nxt not in transitions.get(cur, []):
                    return _finish_failure("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt) or _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {nxt}", from_status=cur, to_status=nxt)
                rec["status"] = nxt
        if "name" in body and body["name"] is not None:
            rec["name"] = body["name"]
        if "severity" in body:
            rec["severity"] = body.get("severity")
        if "score" in body:
            sc = body.get("score")
            if sc is not None and (sc < 0 or sc > 100):
                return _finish_failure("VALIDATION_ERROR", "score must be between 0 and 100") or _err("VALIDATION_ERROR", "score must be between 0 and 100")
            rec["score"] = sc
        if "details" in body:
            if body.get("details") is not None and not isinstance(body.get("details"), dict):
                return _finish_failure("VALIDATION_ERROR", "body.details must be an object") or _err("VALIDATION_ERROR", "body.details must be an object")
            rec["details"] = body.get("details")

        rec["related_operation_id"] = op_id
        rec["updated_at"] = now
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(rec, response_format), "operation_id": op_id}
        _finish_success(payload)
        return payload

    if action == "delete":
        if not gap_item_id:
            return _finish_failure("VALIDATION_ERROR", "gap_item_id is required for delete") or _err("VALIDATION_ERROR", "gap_item_id is required for delete")
        idx = None
        for i, r in enumerate(compliance):
            if r.get("id") == gap_item_id and r.get("tenant_id") == tenant_id and r.get("record_type") == "gap_item":
                idx = i
                break
        if idx is None:
            return _finish_failure("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id) or _err("NOT_FOUND", "Gap item not found", gap_item_id=gap_item_id)
        deleted = compliance.pop(idx)
        _save("compliance_records.json", compliance)
        payload = {"data": _fmt(deleted, response_format), "deleted": True, "operation_id": op_id}
        _finish_success(payload)
        return payload

    return _finish_failure("VALIDATION_ERROR", "Unsupported action") or _err("VALIDATION_ERROR", "Unsupported action")

def generate_audit_reports(tenant_id, report_type, start_time, end_time, filters=None, format=None, include_raw_event=None, limit=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        raw = f"{prefix}|{time.time_ns()}|{os.getpid()}|{os.urandom(8).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z0-9]", "", token)
        return f"{prefix}_{token[:22]}"

    def _record_op(ops, op_row):
        ops.append(op_row)
        _save("operations.json", ops)

    def _finalize_op(ops, op_id, **updates):
        for r in ops:
            if r.get("id") == op_id:
                r.update(updates)
                r["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
                break
        _save("operations.json", ops)

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    if report_type != "audit_log_search":
        return _err("VALIDATION_ERROR", "report_type must be 'audit_log_search'")
    st = _parse_rfc3339(start_time)
    et = _parse_rfc3339(end_time)
    if st is None or et is None:
        return _err("VALIDATION_ERROR", "start_time and end_time must be RFC3339 date-times with timezone")
    if not (et > st):
        return _err("VALIDATION_ERROR", "end_time must be after start_time")
    if format is None:
        format = "json"
    if format not in ("json", "table"):
        return _err("VALIDATION_ERROR", "format must be one of: json, table")
    if include_raw_event is None:
        include_raw_event = False
    if not isinstance(include_raw_event, bool):
        return _err("VALIDATION_ERROR", "include_raw_event must be boolean")
    if limit is None:
        limit = 1000
    if not isinstance(limit, int) or limit < 1 or limit > 5000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 5000")

    allowed_filter_keys = {"workload", "activity", "user_principal_name", "client_ip", "resource_external_id", "retrieved_by_operation_id"}
    if filters is None:
        filters = {}
    if not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    for k in filters.keys():
        if k not in allowed_filter_keys:
            return _err("VALIDATION_ERROR", f"filters contains unsupported field '{k}'")
    if "retrieved_by_operation_id" in filters:
        v = filters.get("retrieved_by_operation_id")
        if not isinstance(v, str) or not re.match(r"^m365_opr_[0-9A-Z]{18,}$", v):
            return _err("VALIDATION_ERROR", "filters.retrieved_by_operation_id must match ^m365_opr_[0-9A-Z]{18,}$")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active")

    # Create operation row (must always happen)
    ops = _load("operations.json")
    op_id = _new_id("m365_opr")
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "generate_audit_reports",
        "operation_kind": "report",
        "request_payload": {
            "tenant_id": tenant_id,
            "report_type": report_type,
            "start_time": start_time,
            "end_time": end_time,
            "filters": filters,
            "format": format,
            "include_raw_event": include_raw_event,
            "limit": limit
        },
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": format,
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    _record_op(ops, op_row)

    # Rate limiting gate for queued->running based on upstream requests in last rolling minute.
    # This tool itself performs no upstream requests (0), so it will always pass, but we still implement the rule.
    try:
        rpm = int(tenant.get("rate_limit_per_minute", 60))
    except Exception:
        rpm = 60
    one_min_ago = now - datetime.timedelta(minutes=1)
    recent_upstream = 0
    for r in ops:
        if r.get("tenant_id") != tenant_id:
            continue
        try:
            sa = _parse_rfc3339(r.get("started_at")) if r.get("started_at") else None
        except Exception:
            sa = None
        if sa and sa >= one_min_ago:
            try:
                recent_upstream += int(r.get("upstream_request_count") or 0)
            except Exception:
                pass
    would_be = recent_upstream + 0
    if would_be > rpm:
        _finalize_op(ops, op_id, rate_limited=True)
        _finalize_op(ops, op_id, status="failed", attempt_count=1, error_code="RATE_LIMIT", error_message="Tenant rate limit would be exceeded; operation delayed",
                     started_at=now_iso, finished_at=now_iso)
        return _err("RATE_LIMIT", "Tenant rate limit would be exceeded")

    # Transition to running
    _finalize_op(ops, op_id, status="running", started_at=now_iso, attempt_count=1)

    # Generate report from stored audit_log_events
    events = _load("audit_log_events.json")

    def _event_in_window(ev):
        ev_time = _parse_rfc3339(ev.get("event_time"))
        if ev_time is None:
            return False
        return (ev_time >= st) and (ev_time < et)

    def _match_filters(ev):
        for k, v in filters.items():
            if v is None:
                continue
            if not isinstance(v, str):
                return False
            if ev.get(k) != v:
                return False
        return True

    selected = []
    for ev in events:
        if ev.get("tenant_id") != tenant_id:
            continue
        if not _event_in_window(ev):
            continue
        if not _match_filters(ev):
            continue
        row = {
            "id": ev.get("id"),
            "event_time": ev.get("event_time"),
            "workload": ev.get("workload"),
            "activity": ev.get("activity"),
            "user_principal_name": ev.get("user_principal_name"),
            "client_ip": ev.get("client_ip"),
            "resource_external_id": ev.get("resource_external_id"),
            "retrieved_by_operation_id": ev.get("retrieved_by_operation_id"),
        }
        if include_raw_event:
            row["raw_event"] = ev.get("raw_event")
        selected.append(row)

    # Sort by event_time asc then id
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("event_time")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    selected.sort(key=_sort_key)
    selected = selected[:limit]

    # Create compliance report record
    compliance = _load("compliance_records.json")
    cmp_id = _new_id("m365_cmp")
    report_record = {
        "id": cmp_id,
        "tenant_id": tenant_id,
        "record_type": "report",
        "external_id": None,
        "name": f"Audit report ({start_time} to {end_time})",
        "status": "completed",
        "parent_record_id": None,
        "related_operation_id": op_id,
        "score": None,
        "severity": None,
        "details": {
            "report_type": report_type,
            "time_window": {"start_time": start_time, "end_time": end_time},
            "filters": filters,
            "format": format,
            "include_raw_event": include_raw_event,
            "event_count": len(selected),
            "source_operation_ids": sorted({ev.get("retrieved_by_operation_id") for ev in events
                                           if ev.get("tenant_id") == tenant_id and _event_in_window(ev) and _match_filters(ev) and ev.get("retrieved_by_operation_id")})
        },
        "created_at": now_iso,
        "updated_at": now_iso
    }
    compliance.append(report_record)
    _save("compliance_records.json", compliance)

    latency_ms = int((time.time() - t0) * 1000)
    response_payload = {
        "report_id": cmp_id,
        "tenant_id": tenant_id,
        "report_type": report_type,
        "start_time": start_time,
        "end_time": end_time,
        "filters": filters,
        "format": format,
        "include_raw_event": include_raw_event,
        "rows": selected,
        "meta": {
            "row_count": len(selected),
            "limit": limit,
            "latency_ms": latency_ms
        }
    }

    _finalize_op(ops, op_id, status="succeeded", finished_at=now_iso, upstream_request_count=0, response_payload=response_payload)
    if format == "table":
        cols = ["event_time", "workload", "activity", "user_principal_name", "client_ip", "resource_external_id", "retrieved_by_operation_id", "id"]
        if include_raw_event:
            cols.append("raw_event")
        table = {"columns": cols, "rows": [[r.get(c) for c in cols] for r in selected]}
        response_payload = {k: v for k, v in response_payload.items() if k != "rows"}
        response_payload["table"] = table
    return response_payload

def manage_cis_compliance(tenant_id, action, record_id=None, benchmark_id=None, target=None, body=None, filters=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        raw = f"{prefix}|{time.time_ns()}|{os.getpid()}|{os.urandom(8).hex()}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = re.sub(r"[^A-Z0-9]", "", token)
        return f"{prefix}_{token[:22]}"

    # Validate top-level inputs
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    allowed_actions = {"list_benchmarks", "run_assessment", "get_assessment", "list_findings", "create_evidence", "generate_report", "update_record_status"}
    if action not in allowed_actions:
        return _err("VALIDATION_ERROR", "action is invalid")

    if record_id is not None:
        if not isinstance(record_id, str) or not re.match(r"^m365_cmp_[0-9A-Z]{18,}$", record_id):
            return _err("VALIDATION_ERROR", "record_id must match ^m365_cmp_[0-9A-Z]{18,}$")
    if filters is None:
        filters = {}
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if body is None:
        body = {}
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if limit is None:
        limit = 50 if action.startswith("list_") else None
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None and action.startswith("list_"):
        sort = "-created_at"
    if sort is not None:
        allowed_sort = {"created_at", "-created_at", "updated_at", "-updated_at", "score", "-score", "severity", "-severity", "name", "-name"}
        if sort not in allowed_sort:
            return _err("VALIDATION_ERROR", "sort is invalid")

    # Tenant check
    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active")

    # Always create operations row
    ops = _load("operations.json")
    op_id = _new_id("m365_opr")
    operation_kind = "read" if action in {"list_benchmarks", "get_assessment", "list_findings"} else ("create" if action in {"run_assessment", "create_evidence", "generate_report"} else "update")
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "manage_cis_compliance",
        "operation_kind": operation_kind,
        "request_payload": {
            "tenant_id": tenant_id,
            "action": action,
            "record_id": record_id,
            "benchmark_id": benchmark_id,
            "target": target,
            "body": body,
            "filters": filters,
            "limit": limit,
            "cursor": cursor,
            "sort": sort
        },
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    ops.append(op_row)
    _save("operations.json", ops)

    def _finalize(**updates):
        for r in ops:
            if r.get("id") == op_id:
                r.update(updates)
                r["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
                break
        _save("operations.json", ops)

    # Rate-limit gate (0 upstream reqs for these local ops; still implement)
    try:
        rpm = int(tenant.get("rate_limit_per_minute", 60))
    except Exception:
        rpm = 60
    one_min_ago = now - datetime.timedelta(minutes=1)
    recent_upstream = 0
    for r in ops:
        if r.get("tenant_id") != tenant_id:
            continue
        sa = _parse_rfc3339(r.get("started_at")) if r.get("started_at") else None
        if sa and sa >= one_min_ago:
            try:
                recent_upstream += int(r.get("upstream_request_count") or 0)
            except Exception:
                pass
    if recent_upstream + 0 > rpm:
        _finalize(rate_limited=True, status="failed", attempt_count=1, error_code="RATE_LIMIT", error_message="Tenant rate limit would be exceeded; operation delayed",
                  started_at=now_iso, finished_at=now_iso)
        return _err("RATE_LIMIT", "Tenant rate limit would be exceeded")

    _finalize(status="running", started_at=now_iso, attempt_count=1)

    compliance = _load("compliance_records.json")

    # Helpers: lifecycle transitions
    transitions = {
        "draft": {"active", "archived"},
        "active": {"running", "archived"},
        "running": {"completed", "failed", "archived"},
        "completed": {"archived"},
        "failed": {"running", "archived"},
        "archived": set(),
    }
    def _can_transition(old, new):
        return new in transitions.get(old, set())

    def _apply_list_sort(rows):
        reverse = False
        key = sort
        if key and key.startswith("-"):
            reverse = True
            key = key[1:]
        def kf(r):
            v = r.get(key)
            if key in ("created_at", "updated_at"):
                dt = _parse_rfc3339(v) if isinstance(v, str) else None
                return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if key == "score":
                return (v if isinstance(v, (int, float)) else -1)
            if key == "severity":
                order = {"low": 1, "medium": 2, "high": 3, "critical": 4}
                return order.get(v, 0)
            if key == "name":
                return (v or "")
            return v
        rows.sort(key=kf, reverse=reverse)
        return rows

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        try:
            pad = "=" * (-len(c) % 4)
            return int(base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8"))
        except Exception:
            return None

    # Action implementations
    try:
        if action == "list_benchmarks":
            # Return cis_benchmark records; optionally filter by benchmark_id -> external_id or name contains
            rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "cis_benchmark"]
            if benchmark_id is not None:
                if not isinstance(benchmark_id, str) or not benchmark_id:
                    _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="benchmark_id must be a non-empty string")
                    return _err("VALIDATION_ERROR", "benchmark_id must be a non-empty string")
                rows = [r for r in rows if r.get("external_id") == benchmark_id or (isinstance(r.get("name"), str) and benchmark_id.lower() in r.get("name").lower())]
            # Additional filters supported here: status
            f_status = filters.get("status") if isinstance(filters, dict) else None
            if f_status is not None:
                rows = [r for r in rows if r.get("status") == f_status]
            _apply_list_sort(rows)
            start = 0
            if cursor:
                start = _decode_cursor(cursor)
                if start is None or start < 0:
                    _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="cursor is invalid")
                    return _err("VALIDATION_ERROR", "cursor is invalid")
            page = rows[start:start + (limit or 50)]
            next_i = start + len(page)
            has_more = next_i < len(rows)
            resp = {"data": page, "meta": {"total": len(rows), "limit": (limit or 50), "has_more": has_more, "next_cursor": _encode_cursor(next_i) if has_more else None}}
            _finalize(status="succeeded", finished_at=now_iso, response_payload=resp)
            return resp

        if action == "run_assessment":
            # Validate target
            if not isinstance(target, dict) or target.get("scope") != "tenant":
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="target.scope must be 'tenant'")
                return _err("VALIDATION_ERROR", "target.scope must be 'tenant'")
            if benchmark_id is None or not isinstance(benchmark_id, str) or not benchmark_id:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="benchmark_id is required for run_assessment")
                return _err("VALIDATION_ERROR", "benchmark_id is required for run_assessment")

            # Ensure benchmark exists (cis_benchmark with external_id=benchmark_id)
            bench = next((r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "cis_benchmark" and r.get("external_id") == benchmark_id), None)
            if not bench:
                _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="benchmark not found")
                return _err("NOT_FOUND", "benchmark not found")

            name = body.get("name") if isinstance(body, dict) else None
            score = body.get("score") if isinstance(body, dict) else None
            details = body.get("details") if isinstance(body, dict) else None

            if score is not None and not isinstance(score, (int, float)):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="score must be a number")
                return _err("VALIDATION_ERROR", "score must be a number")
            if score is not None and not (0 <= float(score) <= 100):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="score must be between 0 and 100")
                return _err("VALIDATION_ERROR", "score must be between 0 and 100")
            if details is not None and not isinstance(details, dict):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="details must be an object")
                return _err("VALIDATION_ERROR", "details must be an object")

            # Create assessment record + assessment_run record linked to this operation
            assessment_id = _new_id("m365_cmp")
            assessment = {
                "id": assessment_id,
                "tenant_id": tenant_id,
                "record_type": "assessment",
                "external_id": None,
                "name": name or f"CIS Assessment for {benchmark_id}",
                "status": "active",
                "parent_record_id": bench.get("id"),
                "related_operation_id": None,
                "score": score if score is None else float(score),
                "severity": None,
                "details": {"benchmark_external_id": benchmark_id, "target": target, **(details or {})},
                "created_at": now_iso,
                "updated_at": now_iso
            }
            run_id = _new_id("m365_cmp")
            run = {
                "id": run_id,
                "tenant_id": tenant_id,
                "record_type": "assessment_run",
                "external_id": None,
                "name": (name or f"Assessment run for {benchmark_id}"),
                "status": "running",
                "parent_record_id": assessment_id,
                "related_operation_id": op_id,  # required by business rule
                "score": score if score is None else float(score),
                "severity": None,
                "details": {"benchmark_external_id": benchmark_id, "started_at": now_iso, "target": target, **(details or {})},
                "created_at": now_iso,
                "updated_at": now_iso
            }
            compliance.extend([assessment, run])
            _save("compliance_records.json", compliance)
            resp = {"assessment": assessment, "assessment_run": run}
            _finalize(status="succeeded", finished_at=now_iso, response_payload=resp)
            return resp

        if action == "get_assessment":
            if not record_id:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="record_id is required for get_assessment")
                return _err("VALIDATION_ERROR", "record_id is required for get_assessment")
            rec = next((r for r in compliance if r.get("id") == record_id and r.get("tenant_id") == tenant_id), None)
            if not rec:
                _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="record not found")
                return _err("NOT_FOUND", "record not found")
            _finalize(status="succeeded", finished_at=now_iso, response_payload=rec)
            return rec

        if action == "list_findings":
            # List findings (record_type='finding') with optional filters + pagination
            rows = [r for r in compliance if r.get("tenant_id") == tenant_id and r.get("record_type") == "finding"]
            if isinstance(filters, dict):
                for fk in ("status", "severity", "parent_record_id"):
                    if filters.get(fk) is not None:
                        rows = [r for r in rows if r.get(fk) == filters.get(fk)]
            _apply_list_sort(rows)
            start = 0
            if cursor:
                start = _decode_cursor(cursor)
                if start is None or start < 0:
                    _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="cursor is invalid")
                    return _err("VALIDATION_ERROR", "cursor is invalid")
            page = rows[start:start + (limit or 50)]
            next_i = start + len(page)
            has_more = next_i < len(rows)
            resp = {"data": page, "meta": {"total": len(rows), "limit": (limit or 50), "has_more": has_more, "next_cursor": _encode_cursor(next_i) if has_more else None}}
            _finalize(status="succeeded", finished_at=now_iso, response_payload=resp)
            return resp

        if action == "create_evidence":
            if not record_id:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="record_id is required for create_evidence")
                return _err("VALIDATION_ERROR", "record_id is required for create_evidence")
            parent = next((r for r in compliance if r.get("id") == record_id and r.get("tenant_id") == tenant_id), None)
            if not parent:
                _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="parent record not found")
                return _err("NOT_FOUND", "parent record not found")

            name = body.get("name")
            if name is not None and not isinstance(name, str):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.name must be a string")
                return _err("VALIDATION_ERROR", "body.name must be a string")
            details = body.get("details")
            if details is not None and not isinstance(details, dict):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.details must be an object")
                return _err("VALIDATION_ERROR", "body.details must be an object")
            related_operation_id = body.get("related_operation_id")
            if related_operation_id is not None:
                if not isinstance(related_operation_id, str) or not re.match(r"^m365_opr_[0-9A-Z]{18,}$", related_operation_id):
                    _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.related_operation_id is invalid")
                    return _err("VALIDATION_ERROR", "body.related_operation_id is invalid")
                # must exist
                ops_all = _load("operations.json")
                if not any(o.get("id") == related_operation_id and o.get("tenant_id") == tenant_id for o in ops_all):
                    _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="related_operation_id not found")
                    return _err("NOT_FOUND", "related_operation_id not found")

            ev_id = _new_id("m365_cmp")
            evidence = {
                "id": ev_id,
                "tenant_id": tenant_id,
                "record_type": "evidence",
                "external_id": None,
                "name": name or f"Evidence for {parent.get('record_type')}:{parent.get('id')}",
                "status": "active",
                "parent_record_id": parent.get("id"),
                "related_operation_id": related_operation_id,
                "score": None,
                "severity": None,
                "details": details or {},
                "created_at": now_iso,
                "updated_at": now_iso
            }
            compliance.append(evidence)
            _save("compliance_records.json", compliance)
            _finalize(status="succeeded", finished_at=now_iso, response_payload=evidence)
            return evidence

        if action == "generate_report":
            if not record_id:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="record_id is required for generate_report")
                return _err("VALIDATION_ERROR", "record_id is required for generate_report")
            src = next((r for r in compliance if r.get("id") == record_id and r.get("tenant_id") == tenant_id), None)
            if not src:
                _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="source record not found")
                return _err("NOT_FOUND", "source record not found")

            name = body.get("name")
            if name is not None and not isinstance(name, str):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.name must be a string")
                return _err("VALIDATION_ERROR", "body.name must be a string")
            score = body.get("score")
            if score is not None and not isinstance(score, (int, float)):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.score must be a number")
                return _err("VALIDATION_ERROR", "body.score must be a number")
            if score is not None and not (0 <= float(score) <= 100):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.score must be between 0 and 100")
                return _err("VALIDATION_ERROR", "body.score must be between 0 and 100")
            details = body.get("details")
            if details is not None and not isinstance(details, dict):
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.details must be an object")
                return _err("VALIDATION_ERROR", "body.details must be an object")

            rep_id = _new_id("m365_cmp")
            report = {
                "id": rep_id,
                "tenant_id": tenant_id,
                "record_type": "report",
                "external_id": None,
                "name": name or f"CIS Report for {src.get('record_type')}:{src.get('id')}",
                "status": "completed",
                "parent_record_id": src.get("id"),
                "related_operation_id": op_id,
                "score": score if score is None else float(score),
                "severity": None,
                "details": {"source_record_id": src.get("id"), **(details or {})},
                "created_at": now_iso,
                "updated_at": now_iso
            }
            compliance.append(report)
            _save("compliance_records.json", compliance)
            _finalize(status="succeeded", finished_at=now_iso, response_payload=report)
            return report

        if action == "update_record_status":
            if not record_id:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="record_id is required for update_record_status")
                return _err("VALIDATION_ERROR", "record_id is required for update_record_status")
            new_status = body.get("status")
            if new_status is None:
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.status is required")
                return _err("VALIDATION_ERROR", "body.status is required")
            if new_status not in transitions.keys():
                _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="body.status is invalid")
                return _err("VALIDATION_ERROR", "body.status is invalid")

            idx = None
            for i, r in enumerate(compliance):
                if r.get("id") == record_id and r.get("tenant_id") == tenant_id:
                    idx = i
                    break
            if idx is None:
                _finalize(status="failed", finished_at=now_iso, error_code="NOT_FOUND", error_message="record not found")
                return _err("NOT_FOUND", "record not found")

            old_status = compliance[idx].get("status")
            if old_status == new_status:
                # idempotent
                _finalize(status="succeeded", finished_at=now_iso, response_payload=compliance[idx])
                return compliance[idx]
            if not _can_transition(old_status, new_status):
                _finalize(status="failed", finished_at=now_iso, error_code="INVALID_TRANSITION", error_message=f"cannot transition {old_status} -> {new_status}")
                return _err("INVALID_TRANSITION", f"cannot transition {old_status} -> {new_status}")

            compliance[idx]["status"] = new_status
            compliance[idx]["updated_at"] = now_iso
            _save("compliance_records.json", compliance)
            _finalize(status="succeeded", finished_at=now_iso, response_payload=compliance[idx])
            return compliance[idx]

        _finalize(status="failed", finished_at=now_iso, error_code="VALIDATION_ERROR", error_message="Unsupported action")
        return _err("VALIDATION_ERROR", "Unsupported action")
    except Exception as e:
        _finalize(status="failed", finished_at=now_iso, error_code="FAILED", error_message=str(e))
        return _err("CONFLICT", "Unexpected server error", detail=str(e), latency_ms=int((time.time() - t0) * 1000))

def create_intune_policy(tenant_id, platform, policy_type, body, **_extra):
    import json, os, datetime, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "create_intune_policy"
    if not isinstance(tenant_id, str) or re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id) is None:
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    if platform not in ("windows","macos"):
        return _err("VALIDATION_ERROR", "platform must be one of: windows, macos")
    if policy_type not in ("configuration","compliance"):
        return _err("VALIDATION_ERROR", "policy_type must be one of: configuration, compliance")
    if not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if not isinstance(body.get("display_name"), str) or not body.get("display_name"):
        return _err("VALIDATION_ERROR", "body.display_name is required")
    if not isinstance(body.get("settings"), dict):
        return _err("VALIDATION_ERROR", "body.settings must be an object")
    if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
        return _err("VALIDATION_ERROR", "body.description must be a string")

    tenants = _load("tenants.json")
    ents = _load("directory_entities.json")
    ops = _load("operations.json")

    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id")==tenant_id), None)
    if not tenant:
        return _err("NOT_FOUND", "tenant not found")
    if tenant.get("status") != "active":
        return _err("UNAUTHORIZED", "tenant is not active")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00","Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    # Build canonical policy document and validate required fields
    now = _now_iso()
    policy_doc = {
        "platform": platform,
        "policyType": policy_type,
        "displayName": body["display_name"],
        "description": body.get("description"),
        "settings": body["settings"],
    }
    # minimal canonical validation
    # require a stable identifier for Intune-style policies
    policy_doc.setdefault("payloadIdentifier", f"com.m365.policy.{uuid.uuid4().hex}")
    if not isinstance(policy_doc.get("payloadIdentifier"), str) or not policy_doc["payloadIdentifier"]:
        return _err("VALIDATION_ERROR", "Generated policy JSON failed validation: missing 'payloadIdentifier'")

    # create operation row
    op_id = _new_id("m365_opr")
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": TOOL,
        "operation_kind": "create",
        "request_payload": {"tenant_id": tenant_id, "platform": platform, "policy_type": policy_type, "body": body},
        "target_entity_id": None,
        "status": "running",
        "attempt_count": 1,
        "max_attempts": 3,
        "rate_limited": False,
        "upstream_provider": "intune",
        "upstream_request_count": 1,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)

    entity_type = "intune_policy_windows" if platform=="windows" else "intune_policy_macos"
    ent = {
        "id": _new_id("m365_ent"),
        "tenant_id": tenant_id,
        "entity_type": entity_type,
        "external_id": f"intune.policy:{uuid.uuid4().hex}",
        "display_name": body["display_name"],
        "principal_name": None,
        "mail": None,
        "enabled": True,
        "status": "active",
        "properties": {"policy_document": policy_doc},
        "created_at": now,
        "updated_at": now,
    }
    ents.append(ent)
    op["target_entity_id"] = ent["id"]
    op["status"] = "succeeded"
    op["finished_at"] = _now_iso()
    op["updated_at"] = op["finished_at"]
    op["response_payload"] = {"policy_entity": ent}

    _save("directory_entities.json", ents)
    _save("operations.json", ops)
    return {"operation_id": op_id, "policy_entity": ent}

