    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created_at","-created_at","updated_at","-updated_at","display_name","-display_name"):
            return _err("VALIDATION_ERROR", "sort is invalid")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if filters is not None:
        allowed = {"status","tenant_domain","azure_tenant_id","q"}
        for k in filters.keys():
            if k not in allowed:
                return _err("VALIDATION_ERROR", f"filters.{k} is not allowed")
        if "status" in filters and filters["status"] is not None and filters["status"] not in ("active","suspended","deprovisioned"):
            return _err("VALIDATION_ERROR", "filters.status is invalid")
        for k in ("tenant_domain","azure_tenant_id","q"):
            if k in filters and filters[k] is not None and not isinstance(filters[k], str):
                filters = dict(filters)
                filters[k] = str(filters[k])

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00","Z")
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"
    def _decode_cursor(cur):
        if cur is None: return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", 0)
            return off if isinstance(off, int) and off >= 0 else None
        except Exception:
            return None
    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",",":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    tenants = _load("tenants.json")
    ops = _load("operations.json")

    # record operation row (choose any active tenant for ledger context if available; otherwise use first tenant)
    ledger_tenant = next((t for t in tenants if isinstance(t, dict) and t.get("status")=="active"), None) or (tenants[0] if tenants else None)
    if ledger_tenant is None:
        return _err("UNAUTHORIZED", "no tenant context available")

    now = _now_iso()
    op = {
        "id": _new_id("m365_opr"),
        "tenant_id": ledger_tenant.get("id"),
        "tool_name": TOOL,
        "operation_kind": "read",
        "request_payload": {"filters": filters, "sort": sort, "limit": limit, "cursor": cursor},
        "target_entity_id": None,
        "status": "running",
        "attempt_count": 1,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)

    try:
        items = [t for t in tenants if isinstance(t, dict)]
        flt = filters or {}
        if flt.get("status"):
            items = [t for t in items if t.get("status")==flt["status"]]
        if flt.get("tenant_domain"):
            items = [t for t in items if t.get("tenant_domain")==flt["tenant_domain"]]
        if flt.get("azure_tenant_id"):
            items = [t for t in items if t.get("azure_tenant_id")==flt["azure_tenant_id"]]
        if flt.get("q"):
            ql = str(flt["q"]).lower()
            items = [t for t in items if ql in (str(t.get("display_name","") or "") + " " + str(t.get("tenant_domain","") or "")).lower()]
        s = sort or "created_at"
        rev = s.startswith("-")
        key = s[1:] if rev else s
        items.sort(key=lambda t: (t.get(key) or ""), reverse=rev)
        off = _decode_cursor(cursor)
        if off is None:
            op["status"] = "failed"
            op["error_code"] = "validation"
            op["error_message"] = "invalid cursor"
            op["finished_at"] = _now_iso()
            op["updated_at"] = op["finished_at"]
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is invalid")
        lim = 200 if limit is None else min(200, int(limit))
        page = items[off:off+lim]
        next_off = off + len(page)
        has_more = next_off < len(items)
        next_cur = _encode_cursor(next_off) if has_more else None
        payload = {"items": page, "total": len(items), "has_more": has_more, "next_cursor": next_cur}
        op["status"] = "succeeded"
        op["response_payload"] = payload
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
        _save("operations.json", ops)
        return {"operation_id": op["id"], **payload}
    except Exception as e:
        op["status"] = "failed"
        op["error_code"] = "internal_error"
        op["error_message"] = str(e)
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
        _save("operations.json", ops)
        return _err("CONFLICT", "internal error", detail=str(e))

def get_tenant(tenant_id, **_extra):
