    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    TOOL_NAME = "get_tenant"

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _ops_transition_allowed(frm, to):
        transitions = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "partial", "cancelled"],
            "partial": ["running", "succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": ["queued"],
            "cancelled": []
        }
        return to in transitions.get(frm, [])

    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id is invalid")

    tenants = _load("tenants.json")
    ops = _load("operations.json")

    tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)

    # Ambient auth context: if any tenant exists, assume caller can read (no explicit ACLs in schema).
    caller_tenant = next((t for t in tenants if t.get("status") == "active"), None) or (tenants[0] if tenants else None)
    if caller_tenant is None:
        return _err("UNAUTHORIZED", "No tenant context available to authorize this request")

    # record operation (even if NOT_FOUND)
    op = {
        "id": _new_id("m365_op"),
        "tenant_id": caller_tenant["id"],
        "tool_name": TOOL_NAME,
        "operation_kind": "read",
        "request_payload": {"tenant_id": tenant_id},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("operations.json", ops)

    # run and finish
    if _ops_transition_allowed(op["status"], "running"):
        op["status"] = "running"
        op["attempt_count"] = 1
        op["started_at"] = now
        op["updated_at"] = now

    if tenant_row is None:
        if _ops_transition_allowed(op["status"], "failed"):
            op["status"] = "failed"
            op["error_code"] = "NOT_FOUND"
            op["error_message"] = "Tenant not found"
            op["finished_at"] = now
            op["updated_at"] = now
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Tenant not found", tenant_id=tenant_id)

    if _ops_transition_allowed(op["status"], "succeeded"):
        op["status"] = "succeeded"
        op["response_payload"] = {"tenant_id": tenant_id}
        op["finished_at"] = now
        op["updated_at"] = now
    _save("operations.json", ops)

    return {"data": tenant_row, "operation": op}

def update_tenant(tenant_id, body, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    TOOL_NAME = "update_tenant"

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _ops_transition_allowed(frm, to):
        transitions = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "partial", "cancelled"],
            "partial": ["running", "succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": ["queued"],
            "cancelled": []
        }
        return to in transitions.get(frm, [])

    def _tenant_transition_allowed(frm, to):
        transitions = {
            "active": ["suspended", "deprovisioned"],
            "suspended": ["active", "deprovisioned"],
            "deprovisioned": []
        }
        return to in transitions.get(frm, [])

    # ---- validate inputs ----
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id is invalid")
    if not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")

    allowed_fields = {"display_name", "default_region", "rate_limit_per_minute", "status"}
    extra = set(body.keys()) - allowed_fields
    if extra:
        return _err("VALIDATION_ERROR", "body contains unsupported fields", fields=sorted(extra))

    if "display_name" in body and (not isinstance(body["display_name"], str) or not body["display_name"].strip()):
        return _err("VALIDATION_ERROR", "body.display_name must be a non-empty string")
    if "default_region" in body:
        if body["default_region"] not in ("nam", "emea", "apac"):
            return _err("VALIDATION_ERROR", "body.default_region must be one of: nam, emea, apac")
    if "rate_limit_per_minute" in body:
        if not isinstance(body["rate_limit_per_minute"], int):
            return _err("VALIDATION_ERROR", "body.rate_limit_per_minute must be an integer")
        if body["rate_limit_per_minute"] < 1 or body["rate_limit_per_minute"] > 6000:
            return _err("VALIDATION_ERROR", "body.rate_limit_per_minute must be between 1 and 6000")
        # schema constraint enumerates common values, but update_tenant contract allows 1..6000; accept any int in range.
    if "status" in body and body["status"] not in ("active", "suspended", "deprovisioned"):
        return _err("VALIDATION_ERROR", "body.status is invalid")

    tenants = _load("tenants.json")
    ops = _load("operations.json")
    entities = _load("directory_entities.json")
    memberships = _load("group_memberships.json")
    audit_events = _load("audit_log_events.json")
    compliance = _load("compliance_records.json")

    tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)

    # Ambient auth: require there exists at least one active tenant to authorize updates.
    caller_tenant = next((t for t in tenants if t.get("status") == "active"), None)
    if caller_tenant is None:
        return _err("UNAUTHORIZED", "No active tenant context available to authorize updates")

    # record operation (even if NOT_FOUND / INVALID_TRANSITION)
    op = {
        "id": _new_id("m365_op"),
        "tenant_id": caller_tenant["id"],
        "tool_name": TOOL_NAME,
        "operation_kind": "update",
        "request_payload": {"tenant_id": tenant_id, "body": body},
        "target_entity_id": None,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("operations.json", ops)

    # start operation
    if _ops_transition_allowed(op["status"], "running"):
        op["status"] = "running"
        op["attempt_count"] = 1
        op["started_at"] = now
        op["updated_at"] = now

    if tenant_row is None:
        if _ops_transition_allowed(op["status"], "failed"):
            op["status"] = "failed"
            op["error_code"] = "NOT_FOUND"
            op["error_message"] = "Tenant not found"
            op["finished_at"] = now
            op["updated_at"] = now
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Tenant not found", tenant_id=tenant_id)

    # enforce lifecycle transition rules
    if "status" in body:
        new_status = body["status"]
        old_status = tenant_row.get("status")
        if new_status != old_status:
            if not _tenant_transition_allowed(old_status, new_status):
                if _ops_transition_allowed(op["status"], "failed"):
                    op["status"] = "failed"
                    op["error_code"] = "INVALID_TRANSITION"
                    op["error_message"] = f"Illegal tenant status transition: {old_status} -> {new_status}"
                    op["finished_at"] = now
                    op["updated_at"] = now
                _save("operations.json", ops)
                return _err("INVALID_TRANSITION", f"Illegal tenant status transition: {old_status} -> {new_status}")

    # apply updates
    mutated = False
    if "display_name" in body:
        tenant_row["display_name"] = body["display_name"].strip()
        mutated = True
    if "default_region" in body:
        tenant_row["default_region"] = body["default_region"]
        mutated = True
    if "rate_limit_per_minute" in body:
        tenant_row["rate_limit_per_minute"] = body["rate_limit_per_minute"]
        mutated = True
    if "status" in body:
        if body["status"] != tenant_row.get("status"):
            tenant_row["status"] = body["status"]
            mutated = True

    if not mutated:
        # No success without effect: if nothing changes, report conflict? better validation error-like.
        if _ops_transition_allowed(op["status"], "failed"):
            op["status"] = "failed"
            op["error_code"] = "CONFLICT"
            op["error_message"] = "No changes detected; update would have no effect"
            op["finished_at"] = now
            op["updated_at"] = now
        _save("operations.json", ops)
        return _err("CONFLICT", "No changes detected; update would have no effect")

    tenant_row["updated_at"] = now

    # If deprovisioned, enforce "on delete cascade" semantics across collections.
    # Implemented as actual deletions for tenant-owned rows.
    if tenant_row.get("status") == "deprovisioned":
        tid = tenant_row["id"]
        entities = [e for e in entities if e.get("tenant_id") != tid]
        memberships = [m for m in memberships if m.get("tenant_id") != tid]
        audit_events = [a for a in audit_events if a.get("tenant_id") != tid]
        compliance = [c for c in compliance if c.get("tenant_id") != tid]
        _save("directory_entities.json", entities)
        _save("group_memberships.json", memberships)
        _save("audit_log_events.json", audit_events)
        _save("compliance_records.json", compliance)

    _save("tenants.json", tenants)

    # finish op
    if _ops_transition_allowed(op["status"], "succeeded"):
        op["status"] = "succeeded"
        op["response_payload"] = {"tenant_id": tenant_id}
        op["finished_at"] = now
        op["updated_at"] = now
    _save("operations.json", ops)

    return {"data": tenant_row, "operation": op}

def list_operations(tenant_id, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time")

    def _record_op(tenant_row, status, response_payload=None, error=None, request_payload=None):
        ops = _load("operations.json")
        def _new_id(prefix):
            alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            ts = int(now.timestamp() * 1000)
            x = ts
            chars = []
            while x > 0:
                x, r = divmod(x, 36)
                chars.append(alphabet[r])
            core = "".join(reversed(chars or ["0"]))
            core = (core + "0" * 18)[:18]
            cand = f"{prefix}{core}"
            used = {o.get("id") for o in ops if isinstance(o, dict)}
            if cand not in used:
                return cand
            for i in range(1, 10000):
                suf = ""
                y = i
                while y > 0:
                    y, r = divmod(y, 36)
                    suf = alphabet[r] + suf
                suf = (suf + "0" * 4)[:4]
                cand2 = f"{prefix}{core[:-4]}{suf}"
                if cand2 not in used:
                    return cand2
            return f"{prefix}{core}{int(time.time())}"

        op = {
            "id": _new_id("m365_op_"),
            "tenant_id": tenant_row["id"],
            "tool_name": "list_operations",
            "operation_kind": "read",
            "request_payload": request_payload or {},
            "target_entity_id": None,
            "status": "succeeded" if status == "succeeded" else "failed",
            "attempt_count": 1,
            "max_attempts": 1,
            "rate_limited": False,
            "upstream_provider": "other",
            "upstream_request_count": 0,
            "response_format": "json",
            "response_payload": response_payload,
            "error_code": None if not error else error.get("code"),
            "error_message": None if not error else error.get("message"),
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Validate tenant_id
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        # no tenant context to log against -> return validation error
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant_row.get("status") != "active":
        # Ambient auth exists, but tenant not serviceable
        err = _err("UNAUTHORIZED", "tenant is not active", tenant_status=tenant_row.get("status"))
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    # Validate filters/sort/limit/cursor
    if filters is not None and not isinstance(filters, dict):
        err = _err("VALIDATION_ERROR", "filters must be an object")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    allowed_filter_keys = {"status", "tool_name", "operation_kind", "target_entity_id", "rate_limited", "created_after", "created_before", "parent_operation_id"}
    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in allowed_filter_keys:
                err = _err("VALIDATION_ERROR", f"filters contains unsupported field '{k}'")
                _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
                return err

    status_f = filters.get("status") if isinstance(filters, dict) else None
    if status_f is not None and status_f not in {"queued", "running", "succeeded", "failed", "cancelled", "partial"}:
        err = _err("VALIDATION_ERROR", "filters.status is invalid")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    tool_f = filters.get("tool_name") if isinstance(filters, dict) else None
    if tool_f is not None and not isinstance(tool_f, str):
        err = _err("VALIDATION_ERROR", "filters.tool_name must be a string")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    kind_f = filters.get("operation_kind") if isinstance(filters, dict) else None
    # Tool schema says read/write/workflow, but stored enum is read/create/update/delete/search/workflow/report.
    if kind_f is not None and kind_f not in {"read", "write", "workflow"}:
        err = _err("VALIDATION_ERROR", "filters.operation_kind must be one of 'read','write','workflow'")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    target_f = filters.get("target_entity_id") if isinstance(filters, dict) else None
    if target_f is not None:
        if not isinstance(target_f, str) or not re.match(r"^m365_ent_[0-9A-Z]{18,}$", target_f):
            err = _err("VALIDATION_ERROR", "filters.target_entity_id must match ^m365_ent_[0-9A-Z]{18,}$")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
            return err

    rl_f = filters.get("rate_limited") if isinstance(filters, dict) else None
    if rl_f is not None and not isinstance(rl_f, bool):
        err = _err("VALIDATION_ERROR", "filters.rate_limited must be boolean")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    parent_f = filters.get("parent_operation_id") if isinstance(filters, dict) else None
    if parent_f is not None:
        if not isinstance(parent_f, str) or not re.match(r"^m365_op_[0-9A-Z]{18,}$", parent_f):
            err = _err("VALIDATION_ERROR", "filters.parent_operation_id must match ^m365_op_[0-9A-Z]{18,}$")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
            return err

    created_after_s = filters.get("created_after") if isinstance(filters, dict) else None
    created_before_s = filters.get("created_before") if isinstance(filters, dict) else None
    created_after_dt, err = _parse_dt(created_after_s, "filters.created_after")
    if err:
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err
    created_before_dt, err = _parse_dt(created_before_s, "filters.created_before")
    if err:
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err
    if created_after_dt and created_before_dt and created_after_dt > created_before_dt:
        err = _err("VALIDATION_ERROR", "created_after must be <= created_before")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    allowed_sort = {"created_at", "-created_at", "updated_at", "-updated_at", "started_at", "-started_at", "finished_at", "-finished_at"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        err = _err("VALIDATION_ERROR", "sort must be one of the supported values")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
        return err

    # Cursor: opaque base64(json({"o": offset}))
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            err = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
            return err
        try:
            pad = "=" * (-len(cursor) % 4)
            decoded = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(decoded)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad cursor")
            offset = obj["o"]
        except (ValueError, json.JSONDecodeError):
            err = _err("VALIDATION_ERROR", "cursor is invalid")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "filters": filters, "sort": sort, "limit": limit, "cursor": cursor})
            return err

    # Read + filter
    ops = _load("operations.json")
    rows = [o for o in ops if isinstance(o, dict) and o.get("tenant_id") == tenant_id]

    if status_f is not None:
        rows = [o for o in rows if o.get("status") == status_f]
    if tool_f is not None:
        rows = [o for o in rows if o.get("tool_name") == tool_f]
    if kind_f is not None:
        if kind_f == "workflow":
            rows = [o for o in rows if o.get("operation_kind") == "workflow"]
        elif kind_f == "read":
            rows = [o for o in rows if o.get("operation_kind") == "read"]
        else:  # write
            rows = [o for o in rows if o.get("operation_kind") in {"create", "update", "delete"}]
    if target_f is not None:
        rows = [o for o in rows if o.get("target_entity_id") == target_f]
    if rl_f is not None:
        rows = [o for o in rows if bool(o.get("rate_limited")) == rl_f]
    if created_after_dt is not None or created_before_dt is not None:
        def _created_dt(o):
            s = o.get("created_at")
            if not isinstance(s, str):
                return None
            try:
                ss = s
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        tmp = []
        for o in rows:
            dt = _created_dt(o)
            if dt is None:
                continue
            if created_after_dt is not None and dt < created_after_dt:
                continue
            if created_before_dt is not None and dt > created_before_dt:
                continue
            tmp.append(o)
        rows = tmp
    if parent_f is not None:
        tmp = []
        for o in rows:
            rp = o.get("request_payload")
            if isinstance(rp, dict) and rp.get("parent_operation_id") == parent_f:
                tmp.append(o)
        rows = tmp

    # Sort
    field = sort.lstrip("-")
    desc = sort.startswith("-")

    def _dt_key(v):
        if not isinstance(v, str):
            return None
        try:
            ss = v
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _sort_key(o):
        dt = _dt_key(o.get(field))
        # None sorts last when desc? keep stable: map None to far past/future
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if desc else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        return dt

    rows.sort(key=_sort_key, reverse=desc)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Record operation execution
    req_payload = {"tenant_id": tenant_id, "filters": filters or {}, "sort": sort, "limit": limit, "cursor": cursor}
    resp = {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}
    _record_op(tenant_row, "succeeded", response_payload=resp, request_payload=req_payload)

    return resp

def get_operation(tenant_id, operation_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
                if isinstance(d, dict) and isinstance(d.get("rows"), list):
                    return d["rows"]
                return []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix, rows):
        import uuid
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(1000):
            cand = f"{prefix}{uuid.uuid4().hex.upper()[:20]}"
            if cand not in used:
                return cand
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    # Relax validation: accept any non-empty strings (audit: calls used tenant_id in operation_id slot)
    if not isinstance(tenant_id, str) or not tenant_id:
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string")
    if not isinstance(operation_id, str) or not operation_id:
        return _err("VALIDATION_ERROR", "operation_id must be a non-empty string")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found")

    ops = _load("operations.json")

    # record operation for this call
    op_id = _new_id("m365_opr_", ops)
    now = _now()
    log_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "get_operation",
        "operation_kind": "read",
        "request_payload": {"tenant_id": tenant_id, "operation_id": operation_id},
        "target_entity_id": None,
        "status": "running",
        "attempt_count": 1,
        "max_attempts": 1,
        "rate_limited": False,
        "upstream_provider": "other",
        "upstream_request_count": 0,
        "response_format": "json",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(log_row)
    _save("operations.json", ops)

    target = next((o for o in ops if isinstance(o, dict) and o.get("id") == operation_id and o.get("tenant_id") == tenant_id), None)
    if not target:
        log_row["status"] = "failed"
        log_row["error_code"] = "not_found"
        log_row["error_message"] = "operation not found"
        log_row["finished_at"] = _now()
        log_row["updated_at"] = log_row["finished_at"]
        _save("operations.json", ops)
        return _err("NOT_FOUND", "operation not found")

    payload = {"operation": target}
    log_row["status"] = "succeeded"
    log_row["response_payload"] = payload
    log_row["finished_at"] = _now()
    log_row["updated_at"] = log_row["finished_at"]
    _save("operations.json", ops)
    return payload

def update_operation(tenant_id, operation_id, body, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0507000" if __import__("os").path.isdir("./environment_mix/0507000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _record_op(tenant_row, status, response_payload=None, error=None, request_payload=None):
        ops = _load("operations.json")
        def _new_id(prefix):
            alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            ts = int(now.timestamp() * 1000)
            x = ts
            chars = []
            while x > 0:
                x, r = divmod(x, 36)
                chars.append(alphabet[r])
            core = "".join(reversed(chars or ["0"]))
            core = (core + "0" * 18)[:18]
            cand = f"{prefix}{core}"
            used = {o.get("id") for o in ops if isinstance(o, dict)}
            if cand not in used:
                return cand
            for i in range(1, 10000):
                suf = ""
                y = i
                while y > 0:
                    y, r = divmod(y, 36)
                    suf = alphabet[r] + suf
                suf = (suf + "0" * 4)[:4]
                cand2 = f"{prefix}{core[:-4]}{suf}"
                if cand2 not in used:
                    return cand2
            return f"{prefix}{core}{int(time.time())}"

        op = {
            "id": _new_id("m365_op_"),
            "tenant_id": tenant_row["id"],
            "tool_name": "update_operation",
            "operation_kind": "update",
            "request_payload": request_payload or {},
            "target_entity_id": None,
            "status": "succeeded" if status == "succeeded" else "failed",
            "attempt_count": 1,
            "max_attempts": 1,
            "rate_limited": False,
            "upstream_provider": "other",
            "upstream_request_count": 0,
            "response_format": "json",
            "response_payload": response_payload,
            "error_code": None if not error else error.get("code"),
            "error_message": None if not error else error.get("message"),
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Validate ids
    if not isinstance(tenant_id, str) or not re.match(r"^m365_tnt_[0-9A-Z]{18,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id must match ^m365_tnt_[0-9A-Z]{18,}$")
    if not isinstance(operation_id, str) or not re.match(r"^m365_op_[0-9A-Z]{18,}$", operation_id):
        tenants = _load("tenants.json")
        tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if tenant_row:
            err = _err("VALIDATION_ERROR", "operation_id must match ^m365_op_[0-9A-Z]{18,}$")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return _err("VALIDATION_ERROR", "operation_id must match ^m365_op_[0-9A-Z]{18,}$")

    # Validate body
    if not isinstance(body, dict):
        tenants = _load("tenants.json")
        tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if tenant_row:
            err = _err("VALIDATION_ERROR", "body must be an object")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return _err("VALIDATION_ERROR", "body must be an object")
    for k in body.keys():
        if k not in {"status", "max_attempts"}:
            tenants = _load("tenants.json")
            tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
            if tenant_row:
                err = _err("VALIDATION_ERROR", f"body contains unsupported field '{k}'")
                _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return _err("VALIDATION_ERROR", f"body contains unsupported field '{k}'")

    req_status = body.get("status")
    if req_status is not None and req_status not in {"queued", "running", "succeeded", "failed", "cancelled", "partial"}:
        tenants = _load("tenants.json")
        tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        if tenant_row:
            err = _err("VALIDATION_ERROR", "body.status is invalid")
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return _err("VALIDATION_ERROR", "body.status is invalid")

    req_max_attempts = body.get("max_attempts")
    if req_max_attempts is not None:
        if not isinstance(req_max_attempts, int) or req_max_attempts < 1 or req_max_attempts > 50:
            tenants = _load("tenants.json")
            tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
            if tenant_row:
                err = _err("VALIDATION_ERROR", "body.max_attempts must be an integer between 1 and 50")
                _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return _err("VALIDATION_ERROR", "body.max_attempts must be an integer between 1 and 50")

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant_row:
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)
    if tenant_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "tenant is not active", tenant_status=tenant_row.get("status"))
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return err

    ops = _load("operations.json")
    idx = None
    op_row = None
    for i, o in enumerate(ops):
        if isinstance(o, dict) and o.get("id") == operation_id and o.get("tenant_id") == tenant_id:
            idx = i
            op_row = o
            break
    if op_row is None:
        err = _err("NOT_FOUND", "operation not found", tenant_id=tenant_id, operation_id=operation_id)
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return err

    # Apply updates with lifecycle transitions
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "partial", "cancelled"},
        "partial": {"running", "succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": {"queued"},
        "cancelled": set(),
    }

    changed = False

    # Update max_attempts (stored constraint says <=10, but tool allows 50; enforce store constraint to keep ledger valid)
    if req_max_attempts is not None:
        if req_max_attempts > 10:
            err = _err("VALIDATION_ERROR", "max_attempts cannot exceed 10 for this service", max_allowed=10)
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return err
        if op_row.get("max_attempts") != req_max_attempts:
            op_row["max_attempts"] = req_max_attempts
            changed = True

    if req_status is not None:
        cur = op_row.get("status")
        if cur not in transitions:
            err = _err("CONFLICT", "operation has an unknown current status", current_status=cur)
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return err
        if req_status == cur:
            # Idempotent: but must still have effect? treat as conflict/no-op for a mutation endpoint.
            err = _err("CONFLICT", "requested status is the same as current status", status=cur)
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return err
        if req_status not in transitions[cur]:
            err = _err("INVALID_TRANSITION", f"cannot transition operation from {cur} to {req_status}", from_status=cur, to_status=req_status)
            _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
            return err

        # Rate limiting rule: prevent queued->running if upstream requests last minute would exceed rate_limit_per_minute
        if cur == "queued" and req_status == "running":
            # compute upstream_request_count in last rolling minute (based on started_at/created_at)
            window_start = now - datetime.timedelta(minutes=1)
            used = 0
            for o in ops:
                if not isinstance(o, dict) or o.get("tenant_id") != tenant_id:
                    continue
                dt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
                if dt is None:
                    continue
                if dt >= window_start:
                    urc = o.get("upstream_request_count")
                    if isinstance(urc, int) and urc > 0:
                        used += urc
            this_urc = op_row.get("upstream_request_count")
            if not isinstance(this_urc, int) or this_urc < 0:
                this_urc = 0
            budget = tenant_row.get("rate_limit_per_minute")
            if not isinstance(budget, int):
                budget = 60
            if used + this_urc > budget:
                # Delay: keep queued, mark rate_limited
                if not op_row.get("rate_limited"):
                    op_row["rate_limited"] = True
                    changed = True
                err = _err("RATE_LIMIT", "tenant rate limit prevents starting operation right now", rate_limit_per_minute=budget, used_last_minute=used, requested=this_urc)
                _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
                # persist the rate_limited flag update if changed
                if changed:
                    op_row["updated_at"] = _iso(now)
                    ops[idx] = op_row
                    _save("operations.json", ops)
                return err

            # Allowed to start
            op_row["rate_limited"] = bool(op_row.get("rate_limited"))
            op_row["started_at"] = op_row.get("started_at") or _iso(now)

        # Cancellation: ensure finished_at set for terminal states
        op_row["status"] = req_status
        if req_status in {"succeeded", "failed", "cancelled"}:
            op_row["finished_at"] = op_row.get("finished_at") or _iso(now)
            op_row["started_at"] = op_row.get("started_at") or _iso(now)
        elif req_status in {"running", "partial"}:
            op_row["started_at"] = op_row.get("started_at") or _iso(now)
            op_row["finished_at"] = None
        elif req_status == "queued":
            # retry: clear finished_at, increment attempt_count but do not exceed max_attempts
            ac = op_row.get("attempt_count")
            if not isinstance(ac, int) or ac < 0:
                ac = 0
            ma = op_row.get("max_attempts")
            if not isinstance(ma, int) or ma < 1:
                ma = 1
            if ac + 1 > ma:
                err = _err("QUOTA_EXCEEDED", "max_attempts exceeded; cannot retry", attempt_count=ac, max_attempts=ma)
                _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
                return err
            op_row["attempt_count"] = ac + 1
            op_row["finished_at"] = None
            # keep started_at as-is; control-plane retry re-queues
        changed = True

    if not changed:
        err = _err("CONFLICT", "no changes applied")
        _record_op(tenant_row, "failed", error=err["error"], request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
        return err

    op_row["updated_at"] = _iso(now)
    ops[idx] = op_row
    _save("operations.json", ops)

    resp = {"data": op_row}
    _record_op(tenant_row, "succeeded", response_payload=resp, request_payload={"tenant_id": tenant_id, "operation_id": operation_id, "body": body})
    return resp
